 6: 
 7: use Illuminate\Console\Command;
 8: use Illuminate\Support\Facades\DB;
 9: 
10: final class PruneStaffAuditLogs extends Command
11: {
12:     protected $signature = 'staff:prune-audit-logs';
13: 
14:     protected $description = 'Prune staff audit entries older than the configured retention period';
15: 
16:     public function handle(): int
17:     {
18:         $cutoff = now()->subDays(max(30, (int) config('auth.staff_audit_retention_days', 365)));
19:         do {
20:             $ids = DB::table('staff_audit_logs')->where('created_at', '<', $cutoff)->orderBy('id')->limit(1000)->pluck('id');
21:             DB::table('staff_audit_logs')->whereIn('id', $ids)->delete();
22:         } while ($ids->count() === 1000);
23: 
24:         return self::SUCCESS;
25:     }
26: } 1: <?php
