22: class AuthController extends Controller
23: {
24:     private const DUMMY_PASSWORD_HASH = '$2y$12$dRibbzvWAKqkXBRPna4QCuri7dR8TKHRGDIt.RsplFZRfRcJzmPlq';
25: 
26:     public function login(AdminLoginRequest $request): JsonResource|JsonResponse
27:     {
28:         $credentials = $request->validated();
29:         $user = User::query()
30:             ->whereRaw('LOWER(email) = ?', [$credentials['email']])
31:             ->first();
32:         $storedHash = $user instanceof User ? $user->password : self::DUMMY_PASSWORD_HASH;
33:         $passwordMatches = Hash::check($credentials['password'], $storedHash);
34: 
35:         if (! $user instanceof User || ! $user->is_active || $user->is_system || ! $passwordMatches) {
36:             return response()->json([
37:                 'message' => 'بيانات تسجيل الدخول غير صحيحة أو الحساب غير نشط.',
38:             ], 401);
39:         }
40: 
41:         $emailKey = hash('sha256', Str::transliterate(Str::lower(trim($credentials['email']))));
42:         RateLimiter::clear('admin-login-email:'.$emailKey);
43:         RateLimiter::clear('admin-login-email-hour:'.$emailKey);
44: 
45:         $user->load(['branch', 'roles.permissions', 'permissions']);
46:         $redirect = app(LoginDestinationResolver::class)->resolve($user);
47:         $token = app(StaffTokenService::class)->issue($user, StaffHandoffService::credentialFingerprint($user));
48: 
49:         return UserResource::make($user)->additional(['token' => $token, 'redirect' => $redirect]);
50:     }
51: 
52:     public function me(Request $request): JsonResource
53:     {
54:         $user = $request->user('staff');
55: 
56:         abort_unless($user instanceof User, 403);
57: 
58:         $user->load(['branch', 'roles.permissions', 'permissions']);
59: 
60:         return UserResource::make($user);
61:     }
62: 
63:     public function logout(Request $request): Response
64:     {
65:         $request->user('staff')?->currentAccessToken()?->delete();
66: 
67:         return response()->noContent();
68:     }
