13: class PermissionController extends Controller
14: {
15:     public function index(PermissionRegistrar $permissionRegistrar): JsonResponse
16:     {
17:         $permissions = $permissionRegistrar
18:             ->getPermissions(['guard_name' => 'staff'])
19:             ->sortBy('name');
20: 
21:         $groups = $permissions
22:             ->groupBy(fn (Permission $permission): string => Str::before($permission->name, '.'))
23:             ->map(fn ($group) => $group->map(fn (Permission $permission): array => [
24:                 'id' => $permission->id,
25:                 'name' => $permission->name,
26:             ])->values());
27: 
28:         return response()->json(['data' => (object) $groups->all()]);
29:     }
