  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\StaffRole;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Requests\Api\V1\Admin\StoreRoleRequest;
 10: use App\Http\Requests\Api\V1\Admin\UpdateRoleRequest;
 11: use App\Http\Resources\Api\V1\Admin\RoleResource;
 12: use App\Models\User;
 13: use App\Services\BranchAccess;
 14: use App\Services\StaffAdministration;
 15: use Illuminate\Http\JsonResponse;
 16: use Illuminate\Http\Request;
 17: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 18: use Illuminate\Http\Response;
 19: use Illuminate\Support\Facades\DB;
 20: use Spatie\Permission\Models\Role;
 21: 
 22: class RoleController extends Controller
 23: {
 24:     public function index(Request $request): AnonymousResourceCollection
 25:     {
 26:         $validated = $request->validate([
 27:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 28:         ]);
 29: 
 30:         $roles = Role::query()
 31:             ->where('guard_name', 'staff')
 32:             ->with('permissions')
 33:             ->withCount('users')
 34:             ->orderBy('id')
 35:             ->paginate($validated['per_page'] ?? 15)
 36:             ->withQueryString();
 37: 
 38:         return RoleResource::collection($roles);
 39:     }
 40: 
 41:     public function store(StoreRoleRequest $request): JsonResponse
 42:     {
 43:         $validated = $request->validated();
 44:         $permissions = $validated['permissions'] ?? [];
 45:         $currentUser = $request->user('staff');
 46: 
 47:         if (StaffRole::isReserved($validated['name'])) {
 48:             return response()->json([
 49:                 'message' => 'هذا الاسم محجوز لدور أساسي في النظام.',
 50:             ], 403);
 51:         }
 52: 
 53:         if (! $this->mayGrantPermissions($currentUser, $permissions)) {
 54:             return response()->json([
 55:                 'message' => 'لا يمكنك إسناد صلاحيات لا تملكها.',
 56:             ], 403);
 57:         }
 58: 
 59:         $role = DB::transaction(function () use ($validated, $permissions, $currentUser): Role {
 60:             StaffAdministration::lock();
 61:             StaffAdministration::authorize($currentUser, ['roles.create', 'roles.manage']);
 62:             app(BranchAccess::class)->assertCentralAccess($currentUser);
 63:             abort_unless($this->mayGrantPermissions($currentUser, $permissions), 403);
 64:             StaffAdministration::clearPermissionCacheAfterCommit();
 65:             $role = Role::create([
 66:                 'name' => $validated['name'],
 67:                 'guard_name' => 'staff',
 68:             ]);
 69:             $role->syncPermissions($permissions);
 70:             StaffAdministration::audit($currentUser, 'role.created', 'role', $role->id, array_keys($validated), after: StaffAdministration::roleState($role));
 71: 
 72:             return $role->load('permissions')->loadCount('users');
 73:         });
 74: 
 75:         return RoleResource::make($role)->response()->setStatusCode(201);
 76:     }
 77: 
 78:     public function show(Role $role): RoleResource
 79:     {
 80:         $this->ensureStaffRole($role);
 81: 
 82:         return RoleResource::make($role->load('permissions')->loadCount('users'));
 83:     }
 84: 
 85:     public function update(UpdateRoleRequest $request, Role $role): RoleResource|JsonResponse
 86:     {
 87:         $validated = $request->validated();
 88:         $permissions = $validated['permissions'] ?? null;
 89:         $currentUser = $request->user('staff');
 90: 
 91:         if (array_key_exists('name', $validated) && StaffRole::isReserved($validated['name'])) {
 92:             return response()->json([
 93:                 'message' => 'هذا الاسم محجوز لدور أساسي في النظام.',
 94:             ], 403);
 95:         }
 96: 
 97:         if (is_array($permissions) && ! $this->mayGrantPermissions($currentUser, $permissions)) {
 98:             return response()->json([
 99:                 'message' => 'لا يمكنك إسناد صلاحيات لا تملكها.',
100:             ], 403);
101:         }
102: 
103:         $failure = DB::transaction(function () use ($role, $validated, $permissions, $currentUser): ?string {
104:             StaffAdministration::lock();
105:             StaffAdministration::authorize($currentUser, ['roles.update', 'roles.manage']);
106:             app(BranchAccess::class)->assertCentralAccess($currentUser);
107:             $lockedRole = Role::query()->whereKey($role->getKey())->lockForUpdate()->firstOrFail();
108:             $this->ensureStaffRole($lockedRole);
109:             StaffAdministration::assertVersion($lockedRole, isset($validated['expected_version']) ? (int) $validated['expected_version'] : null);
110:             $before = StaffAdministration::roleState($lockedRole);
111: 
112:             if (($lockedRole->name === StaffRole::SuperAdmin->value || (StaffRole::isReserved($lockedRole->name) && array_key_exists('name', $validated)))) {
113:                 return 'protected';
114:             }
115: 
116:             abort_unless($this->mayGrantPermissions($currentUser, array_unique(array_merge(
117:                 $lockedRole->permissions()->pluck('name')->all(), $permissions ?? []
118:             ))), 403);
119:             StaffAdministration::clearPermissionCacheAfterCommit();
120: 
121:             if (array_key_exists('name', $validated)) {
122:                 $lockedRole->name = $validated['name'];
123:                 $lockedRole->save();
124:             }
125: 
126:             if ($permissions !== null) {
127:                 $lockedRole->syncPermissions($permissions);
128:             }
129:             StaffAdministration::advanceVersion($lockedRole);
130:             StaffAdministration::audit($currentUser, 'role.updated', 'role', $lockedRole->id, array_keys($validated), $before, StaffAdministration::roleState($lockedRole));
131: 
132:             return null;
133:         });
134: 
135:         if ($failure !== null) {
136:             return response()->json([
137:                 'message' => 'لا يمكن تعديل اسم دور أساسي أو تغيير دور Super Admin.',
138:             ], 403);
139:         }
140: 
141:         return RoleResource::make($role->refresh()->load('permissions')->loadCount('users'));
142:     }
143: 
144:     public function destroy(Request $request, Role $role): JsonResponse|Response
145:     {
146:         $this->ensureStaffRole($role);
147: 
148:         $result = DB::transaction(function () use ($role, $request): string {
149:             StaffAdministration::lock();
150:             StaffAdministration::authorize($request->user('staff'), ['roles.delete', 'roles.manage']);
151:             app(BranchAccess::class)->assertCentralAccess($request->user('staff'));
152:             $lockedRole = Role::query()->whereKey($role->getKey())->lockForUpdate()->firstOrFail();
153:             $this->ensureStaffRole($lockedRole);
154: 
155:             if (StaffRole::isReserved($lockedRole->name)) {
156:                 return 'protected';
157:             }
158: 
159:             abort_unless($this->mayGrantPermissions($request->user('staff'), $lockedRole->permissions()->pluck('name')->all()), 403);
160: 
161:             if ($lockedRole->users()->exists()) {
162:                 return 'in_use';
163:             }
164: 
165:             StaffAdministration::audit($request->user('staff'), 'role.deleted', 'role', $lockedRole->id, ['name', 'permissions'], before: StaffAdministration::roleState($lockedRole));
166:             $lockedRole->delete();
167:             StaffAdministration::clearPermissionCacheAfterCommit();
168: 
169:             return 'deleted';
170:         });
171: 
172:         if ($result === 'protected') {
173:             return response()->json([
174:                 'message' => 'لا يمكن حذف دور أساسي في النظام.',
175:             ], 403);
176:         }
177: 
178:         if ($result === 'in_use') {
179:             return response()->json([
180:                 'message' => 'لا يمكن حذف دور مسند إلى موظفين. انقل الموظفين إلى دور آخر أولًا.',
181:             ], 409);
182:         }
183: 
184:         return response()->noContent();
185:     }
186: 
187:     private function mayGrantPermissions(mixed $user, array $permissions): bool
188:     {
189:         if (! $user instanceof User) {
190:             return false;
191:         }
192: 
193:         $user->unsetRelation('roles')->unsetRelation('permissions');
194: 
195:         return $user->hasRole(StaffRole::SuperAdmin->value, 'staff')
196:             || $user->hasAllPermissions($permissions);
197:     }
198: 
199:     private function ensureStaffRole(Role $role): void
200:     {
201:         abort_unless($role->guard_name === 'staff', 404);
202:     }
203: } 1: <?php
