 5: namespace App\Http\Middleware;
 6: 
 7: use App\Models\User;
 8: use App\Services\StaffAdministration;
 9: use Closure;
10: use Illuminate\Auth\Access\AuthorizationException;
11: use Illuminate\Http\Request;
12: use Illuminate\Support\Facades\RateLimiter;
13: use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;
14: use Throwable;
15: 
16: final class AuditStaffAdministration
17: {
18:     public function handle(Request $request, Closure $next): mixed
19:     {
20:         if (! in_array($request->method(), ['POST', 'PATCH', 'PUT', 'DELETE'], true)
21:             || ! preg_match('~^api/v1/admin/(users|roles|settings)(?:/([0-9]+))?$~', $request->path(), $target)) {
22:             return $next($request);
23:         }
24:         $actor = $request->user('staff');
25:         $key = 'staff:admin-mutations:'.($actor?->id ?? 'guest');
26:         $limit = max(1, (int) config('auth.staff_admin_mutations_minute', 60));
27:         if (RateLimiter::tooManyAttempts($key, $limit)) {
28:             return response()->json(['message' => 'طلبات إدارية كثيرة؛ حاول بعد قليل.'], 429);
29:         }
30:         RateLimiter::hit($key, 60);
31:         try {
32:             $response = $next($request);
33:         } catch (Throwable $exception) {
34:             if ($exception instanceof AuthorizationException
35:                 || ($exception instanceof HttpExceptionInterface && $exception->getStatusCode() === 403)) {
36:                 $this->record($request, $target);
37:             }
38:             throw $exception;
39:         }
40:         if ($response->getStatusCode() === 403) {
41:             $this->record($request, $target);
42:         }
43: 
44:         return $response;
45:     }
46: 
47:     private function record(Request $request, array $target): void
48:     {
49:         $actor = $request->user('staff');
50:         if ($actor instanceof User && ! $actor->is_system) {
51:             // Runs after a controller transaction has rolled back, so a rejected action remains visible.
52:             $type = ['users' => 'user', 'roles' => 'role', 'settings' => 'settings'][$target[1]];
53:             try {
54:                 StaffAdministration::audit($actor, 'administration.denied', $type, $target[2] ?? null, []);
55:             } catch (Throwable $exception) {
56:                 report($exception);
57:             }
58:         }
59:     }
60: } 1: <?php
