11: 
12: class UserResource extends JsonResource
13: {
14:     /**
15:      * @return array<string, mixed>
16:      */
17:     public function toArray(Request $request): array
18:     {
19:         return [
20:             'id' => $this->id,
21:             'version' => (int) $this->lock_version,
22:             'name' => $this->name,
23:             'email' => $this->email,
24:             'phone' => $this->phone,
