10: 
11: final class StaffTokenService
12: {
13:     public function issue(User $user, ?string $credentials = null): string
14:     {
15:         return DB::transaction(function () use ($user, $credentials): string {
16:             $user = User::query()->lockForUpdate()->findOrFail($user->id);
17:             if (! $user->is_active || $user->is_system) {
18:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
19:             }
20:             if ($credentials !== null && ! hash_equals(StaffHandoffService::credentialFingerprint($user), $credentials)) {
21:                 throw new BusinessException('رابط الدخول غير صالح أو انتهت صلاحيته.', [], 401);
22:             }
23:             $expiry = config('sanctum.expiration');
24:             $user->tokens()->where(fn ($query) => $query->where('expires_at', '<=', now())
25:                 ->when($expiry, fn ($query) => $query->orWhere('created_at', '<=', now()->subMinutes((int) $expiry))))->delete();
26:             $limit = max(1, (int) config('auth.staff_max_tokens', 20));
27:             $old = $user->tokens()->orderByDesc('id')->skip($limit - 1)->pluck('id');
28:             if ($old->isNotEmpty()) {
29:                 $user->tokens()->whereIn('id', $old)->delete();
30:             }
31: 
32:             return $user->createToken('staff-token', ['*'], now()->addMinutes(max(1, (int) config('auth.staff_token_minutes', 120))))->plainTextToken;
33:         });
34:     }
35: } 1: <?php
