18: export const adminApi = {
19:   // Users
20:   listUsers: (p: UserListParams, signal?: AbortSignal) =>
21:     api.get<Paginated<ApiUser>>(`${BASE}/users`, { params: userParams(p), signal }).then(r => r.data),
22:   getUser: (id: number, signal?: AbortSignal) =>
23:     api.get<{ data: ApiUser }>(`${BASE}/users/${id}`, { signal }).then(r => r.data.data),
24:   createUser: (body: CreateUserBody) =>
25:     api.post<{ data: ApiUser }>(`${BASE}/users`, body).then(r => r.data.data),
26:   updateUser: (id: number, body: UpdateUserBody) =>
27:     api.patch<{ data: ApiUser }>(`${BASE}/users/${id}`, body).then(r => r.data.data),
28:   deactivateUser: (id: number, version: number) =>
29:     api.delete<{ message?: string }>(`${BASE}/users/${id}`, {data:{expected_version:version}}).then(r => r.data),
30:   countUsers: (p: Omit<UserListParams, 'page' | 'per_page'>, signal?: AbortSignal) =>
31:     api.get<Paginated<ApiUser>>(`${BASE}/users`, { params: { ...userParams(p), per_page: 1 }, signal })
32:       .then(r => r.data.meta.total),
33: 
34:   // Roles (بنلف على كل الصفحات)
35:   listRoles: async (signal?: AbortSignal): Promise<ApiRole[]> => {
36:     const all: ApiRole[] = [];
37:     let page = 1, last = 1;
38:     do {
39:       const r = await api.get<Paginated<ApiRole>>(`${BASE}/roles`, { params: { per_page: 100, page }, signal });
40:       all.push(...r.data.data);
41:       last = r.data.meta.last_page;
42:       page++;
43:     } while (page <= last);
44:     return all;
45:   },
46:   createRole: (body: Required<Pick<RoleBody, 'name'>> & RoleBody) =>
47:     api.post<{ data: ApiRole }>(`${BASE}/roles`, body).then(r => r.data.data),
48:   updateRole: (id: number, body: RoleBody) =>
49:     api.patch<{ data: ApiRole }>(`${BASE}/roles/${id}`, body).then(r => r.data.data),
50:   deleteRole: (id: number) => api.delete(`${BASE}/roles/${id}`),
51: 
52:   // Permissions
53:   listPermissions: (signal?: AbortSignal) =>
54:     api.get<{ data: ApiPermissionGroups }>(`${BASE}/permissions`, { signal }).then(r => r.data.data),
55: 
56:   // Branches
57:   listBranches: async (signal?: AbortSignal): Promise<ApiBranch[]> => {
58:     const branches: ApiBranch[] = [];
