61:       const response = await api.get<Paginated<ApiBranch>>(`${BASE}/branches`, {params:{per_page:100,page},signal});
62:       branches.push(...response.data.data); last = response.data.meta.last_page; page++;
63:     } while (page <= last);
64:     return branches;
