 41: export function toAdminSettings(g: ApiSettingsGrouped): AdminSettings {
 42:   const f = flatten(g);
 43:   return {
 44:     company: {
 45:       company_logo: String(f.company_logo ?? ''),
 46:       company_name: String(f.company_name ?? ''),
 47:       company_email: String(f.company_email ?? ''),
 48:       company_phone: String(f.company_phone ?? ''),
 49:       company_address: String(f.company_address ?? ''),
 50:       commercial_register: String(f.commercial_register ?? ''),
 51:     },
 52:     tax: {
 53:       tax_enabled: asBool(f.tax_enabled),
 54:       tax_number: String(f.tax_number ?? ''),
 55:       default_tax_rate: Number(f.default_tax_rate ?? 0),
 56:       prices_include_tax: asBool(f.prices_include_tax),
 57:     },
 58:     numbering: Object.fromEntries(DOC_KEYS.map(k => [k, {
 59:       prefix: String(f[`${k}_prefix`] ?? ''),
 60:       padding: Number(f[`${k}_padding`] ?? 6),
 61:       next_number: Number(f[`${k}_next_number`] ?? 1),
 62:     }])),
 63:     orders: { return_window_days: Number(f.return_window_days ?? 14) },
 64:     purchases: { allow_self_approve_purchases: asBool(f.allow_self_approve_purchases) },
 65:   };
 66: }
