 68: /** بيرجّع flat map فيه المفاتيح اللي اتغيرت بس. ده اللي بيتبعت في PUT */
 69: export function settingsPatch(current: AdminSettings, server: AdminSettings): Record<string, unknown> {
 70:   const out: Record<string, unknown> = {};
 71:   (['company', 'tax', 'orders', 'purchases'] as const).forEach(g => {
 72:     Object.entries(current[g]).forEach(([k, v]) => {
 73:       if (JSON.stringify(v) !== JSON.stringify((server[g] as any)[k])) {
 74:         out[k] = typeof v === 'string' && v.trim() === '' && k !== 'company_name' ? null : v;
 75:       }
 76:     });
 77:   });
 78:   DOC_KEYS.forEach(k => {
 79:     const a = current.numbering[k], b = server.numbering[k];
 80:     if (!a || !b) return;
 81:     if (a.prefix !== b.prefix) out[`${k}_prefix`] = a.prefix ?? '';
 82:     if (a.padding !== b.padding) out[`${k}_padding`] = Number(a.padding);
 83:     if (a.next_number !== b.next_number) out[`${k}_next_number`] = Number(a.next_number);
 84:   });
 85:   return out;
 86: }
 87: export function settingsExpected(patch: Record<string, unknown>, server: AdminSettings): Record<string, unknown> {
 88:  const flat: Record<string, unknown> = {...server.company, ...server.tax, ...server.orders, ...server.purchases};
 89:  for (const key of DOC_KEYS) {
 90:    const value = server.numbering[key];
 91:    if (value) { flat[key+'_prefix'] = value.prefix; flat[key+'_padding'] = value.padding; flat[key+'_next_number'] = value.next_number; }
 92:  }
 93:  return Object.fromEntries(Object.keys(patch).map(key => [key, flat[key] ?? null]));
 94: }
 95: export function buildRolePatch(draft: {name: string; perms: string[]}, original?: {name: string; perms: string[]; version?: number}) {
 96:  const patch: import('./types').RoleBody = {};
 97:  if (original?.version != null) patch.expected_version = original.version;
 98:  if (draft.name.trim() !== original?.name) patch.name = draft.name.trim();
 99:  if (!original || draft.perms.length !== original.perms.length || draft.perms.some(p => !original.perms.includes(p))) patch.permissions = draft.perms;
100:  return patch;
