56: export function permLabel(key: string): string {
57:   if (OVERRIDES[key]) return OVERRIDES[key];
58:   const [res, ...rest] = key.split('.');
59:   const act = rest.join('.');
60:   if (ACTION[act] && RESOURCE[res]) return `${ACTION[act]} ${RESOURCE[res]}`;
61:   return key; // fallback: المفتاح نفسه
62: }
63: export const isSensitive = (key: string) => SENSITIVE.has(key) || key.endsWith('.manage');
