68: /** بيحوّل رد GET /permissions لنفس شكل PermissionGroup اللي roles.tsx متعوّد عليه */
69: export function buildPermissionGroups(api: Record<string, { name: string }[]>): UiPermGroup[] {
70:   const byModule = new Map<string, string[]>();
71:   Object.entries(api).forEach(([prefix, list]) => {
72:     const mod = UI_MODULES.find(m => m.prefixes.includes(prefix)) ?? OTHER_MODULE;
73:     byModule.set(mod.module, [...(byModule.get(mod.module) ?? []), ...list.map(p => p.name)]);
74:   });
75:   const seen = new Set<string>();
76:   return [...UI_MODULES, OTHER_MODULE]
77:     .filter(m => byModule.has(m.module))
78:     .map(m => {
79:       const names = [...new Set(byModule.get(m.module)!)].filter(n => !seen.has(n)).sort();
80:       names.forEach(n => seen.add(n));
81:       const prefixes = [...new Set(names.map(n => n.split('.')[0]))];
82:       return { module: m.module, label: m.label, icon: m.icon, keys: prefixes.join(' · '),
83:         perms: names.map(n => [n, permLabel(n), isSensitive(n)] as [string, string, boolean]) };
84:     }).filter(g => g.perms.length > 0);
85: } 1: export interface Paginated<T> {
