548: }  1: import React, { useEffect, useLayoutEffect, useRef, useState, useMemo } from 'react';
  2: import { createPortal } from 'react-dom';
  3: import { useRoles, useApi, useQueryError } from './hooks';
  4: import { adminApi } from './api/endpoints';
  5: import { UsersScreen } from './users';
  6: import { RolesScreen } from './roles';
  7: import { SettingsScreen } from './settings';
  8: import { ToastHost, Icon, EmptyState } from './ui';
  9: import styles from './admin-reference.css?inline';
 10: 
 11: export interface AdminMockPageProps {
 12:   page: 'users' | 'roles' | 'settings';
 13:   can?: (perm: string) => boolean;
 14:   darkMode?: boolean;
 15:   theme?: string;
 16: }
 17: 
 18: export default function AdminMockPage({ page, can, darkMode, theme }: AdminMockPageProps) {
 19:   const host = useRef<HTMLDivElement>(null);
 20:   const [root, setRoot] = useState<ShadowRoot | null>(null);
 21: 
 22:   const canFn = can ?? (() => false);
 23:   const visible = (key: string) => canFn(key+'.view') || canFn(key+'.manage');
 24:   const rolesQ = useRoles(visible('roles'));
 25:   const roles = rolesQ.data ?? [];
 26:   const [usersTick, setUsersTick] = useState(0);
 27:   const usersTotal = useApi(signal => visible('users') ? adminApi.countUsers({}, signal) : Promise.resolve(undefined), [usersTick, visible('users')]);
 28:   useQueryError(rolesQ.error); useQueryError(usersTotal.error);
 29:   useEffect(() => { ['alfarid_mock_users','alfarid_mock_roles','alfarid_mock_settings'].forEach(key => localStorage.removeItem(key)); }, []);
 30:   // Parse URL query parameters if present (e.g. ?role=3 or ?roleId=2)
 31:   const queryParams = useMemo(() => {
 32:     const raw = window.location.hash.includes('?')
 33:       ? window.location.hash.split('?')[1]
 34:       : window.location.search.replace(/^\?/, '');
 35:     const sp = new URLSearchParams(raw);
 36:     const roleParam = sp.get('role') || sp.get('roleId');
 37:     const roleIdParam = sp.get('roleId') || sp.get('role');
 38:     return {
 39:       role: roleParam ? (isNaN(Number(roleParam)) ? 'all' : Number(roleParam)) : 'all',
 40:       roleId: roleIdParam && !isNaN(Number(roleIdParam)) ? Number(roleIdParam) : undefined,
 41:     };
 42:   }, [page, window.location.hash]);
 43: 
 44:   const [detectedDark, setDetectedDark] = useState(() => {
 45:     if (typeof darkMode === 'boolean') return darkMode;
 46:     if (typeof theme === 'string') return theme === 'dark';
 47:     try {
 48:       return localStorage.getItem('vortix_theme') === 'dark';
 49:     } catch {
 50:       return false;
 51:     }
 52:   });
 53: 
 54:   const isDark = typeof darkMode === 'boolean' ? darkMode : (theme ? theme === 'dark' : detectedDark);
 55: 
 56:   useLayoutEffect(() => {
 57:     if (host.current) {
 58:       setRoot(host.current.shadowRoot || host.current.attachShadow({ mode: 'open' }));
 59:     }
 60:     const fonts = document.createElement('link');
 61:     fonts.rel = 'stylesheet';
 62:     fonts.href = 'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Readex+Pro:wght@400;500;600;700&display=swap';
 63:     document.head.append(fonts);
 64:     return () => fonts.remove();
 65:   }, []);
 66: 
 67:   useEffect(() => {
 68:     if (host.current) {
 69:       host.current.setAttribute('data-theme', isDark ? 'dark' : 'light');
 70:     }
 71:   }, [isDark]);
 72: 
 73:   useEffect(() => {
 74:     const handleCustom = (e: any) => {
 75:       if (typeof e.detail?.darkMode === 'boolean') {
 76:         setDetectedDark(e.detail.darkMode);
 77:       }
 78:     };
 79:     window.addEventListener('vortix:theme-change', handleCustom);
 80: 
 81:     const checkParent = () => {
 82:       const rootNode = host.current?.getRootNode() as ShadowRoot | undefined;
 83:       const parentViewport = host.current?.closest('#app-viewport');
 84:       const target = parentViewport || (rootNode?.host?.querySelector?.('#app-viewport') || rootNode?.host) || document.querySelector('#app-viewport') || document.querySelector('[data-vortix-host]');
 85:       if (!target) return null;
 86:       const dark = target.classList?.contains('theme-dark') || target.getAttribute?.('data-theme') === 'dark';
 87:       setDetectedDark(dark);
 88:       return target;
 89:     };
 90: 
 91:     const target = checkParent();
 92:     let observer: MutationObserver | undefined;
 93:     if (target) {
 94:       observer = new MutationObserver(() => checkParent());
 95:       observer.observe(target, { attributes: true, attributeFilter: ['class', 'data-theme'] });
 96:     }
 97: 
 98:     return () => {
 99:       window.removeEventListener('vortix:theme-change', handleCustom);
100:       observer?.disconnect();
101:     };
102:   }, []);
103: 
104:   const handleNavigate = (targetPage: 'users' | 'roles' | 'settings', params?: Record<string, any>) => {
105:     let hash = `/${targetPage}`;
106:     if (params) {
107:       const sp = new URLSearchParams();
108:       Object.entries(params).forEach(([k, v]) => {
109:         if (v != null) sp.set(k, String(v));
110:       });
111:       const q = sp.toString();
112:       if (q) hash += `?${q}`;
113:     }
114:     window.location.hash = hash;
115:   };
116: 
117:   const navItems = [
118:     { id: 'users', label: 'المستخدمون', icon: 'users', count: usersTotal.loading ? undefined : usersTotal.data, path: '/users' },
119:     { id: 'roles', label: 'الأدوار والصلاحيات', icon: 'shield', count: rolesQ.loading ? undefined : roles.length, path: '/roles' },
120:     { id: 'settings', label: 'الإعدادات العامة', icon: 'sliders', path: '/settings' },
121:   ].filter(item => visible(item.id));
122: 
123:   return (
124:     <div
125:       ref={host}
126:       data-catalog-mock={page}
127:       data-admin-mock={page}
128:       data-theme={isDark ? 'dark' : 'light'}
129:       dir="rtl"
130:     >
131:       {root &&
132:         createPortal(
133:           <>
134:             <style>{styles}</style>
135:             <div className={`admin-mock-surface ${isDark ? 'theme-dark' : 'theme-light'} p-4 sm:p-6 lg:p-8 space-y-6`} dir="rtl" lang="ar">
136:               {/* Top Linking Bar between the 3 Administrative Screens */}
137:               <div className="flex flex-wrap items-center justify-between gap-3 pb-3 border-b" style={{ borderColor: 'var(--divider-color)' }}>
138:                 <div className="inline-flex p-1 rounded-full v-subcard" role="tablist">
139:                   {navItems.map((item) => {
140:                     const active = page === item.id;
141:                     return (
142:                       <button
143:                         type="button"
144:                         key={item.id}
145:                         role="tab"
146:                         aria-selected={active}
147:                         onClick={() => handleNavigate(item.id as any)}
148:                         className={`px-4 py-2 rounded-full text-[13px] font-semibold flex items-center gap-2 transition-all duration-150 ${
149:                           active ? 'shadow-xs' : 'hover:opacity-80'
150:                         }`}
151:                         style={{
152:                           background: active ? 'var(--pill-active-bg)' : 'transparent',
153:                           color: active ? 'var(--pill-active-text)' : 'var(--text-secondary)',
154:                         }}
155:                       >
156:                         <Icon name={item.icon} className="w-4 h-4" />
157:                         <span>{item.label}</span>
158:                         {item.count != null && (
159:                           <span
160:                             className="px-2 py-0.5 rounded-full text-[11px] font-medium"
161:                             style={{
162:                               background: active ? 'rgba(255, 255, 255, 0.2)' : 'var(--bg-card)',
163:                               color: active ? 'inherit' : 'var(--text-muted)',
164:                             }}
165:                           >
166:                             {item.count}
167:                           </span>
168:                         )}
169:                       </button>
170:                     );
171:                   })}
172:                 </div>
173: 
174:                 <div className="flex items-center gap-2 text-[12px]" style={{ color: 'var(--text-muted)' }}>
175:                   <span>لوحة الإدارة والتحكم</span>
176:                   <span>•</span>
177:                   <span>شركة الفريد</span>
178:                 </div>
179:               </div>
180: 
181:               {/* Screen Content */}
182:               {!visible(page) && <EmptyState icon="lock" title="لا تملك صلاحية الوصول لهذه الصفحة" />}
183:               {visible(page) && page === 'users' && (
