16: export function useMe() {
17:   const user = useAuthStore(s => s.user);
18:   return {
19:     me: user,
20:     meId: user?.id,
21:     centralAccess: !!user?.roles?.includes('Super Admin') || !!user?.permissions?.includes('inventory.all_branches'),
22:     iAmSuper: !!user?.roles?.includes('Super Admin'),
23:     myPerms: new Set(user?.permissions ?? []),
