27: /** helper لتنفيذ الـ mutations بنفس الشكل في كل مكان */
28: export async function runMutation<T>(fn: () => Promise<T>): Promise<{ ok: true; data: T } | { ok: false; error: ApiError }> {
29:   try { return { ok: true, data: await fn() }; }
30:   catch (e) { return { ok: false, error: normalizeError(e) }; }
31: }
32: export { useApi };
33: import { useEffect, useState } from 'react';
34: import { toast } from './ui';
35: export function useDebounced<T>(value: T, delay = 300) {
36:  const [debounced, setDebounced] = useState(value);
37:  useEffect(() => { const timer = setTimeout(() => setDebounced(value), delay); return () => clearTimeout(timer); }, [value, delay]);
38:  return debounced;
39: }
40: export function mapFieldErrors(fields: Record<string, string[]>) {
41:  const out: Record<string,string> = {};
42:  Object.entries(fields).forEach(([key, errors]) => { out[key.split('.')[0]] ??= errors[0]; });
43:  return out;
44: }
45: export function useQueryError(error?: ApiError) {
46:  useEffect(() => { if (error && error.status !== 401) toast(error.message, 'err'); }, [error]);
