 33: export function RolesScreen({ roles, rolesLoading, reloadRoles, can, onNavigate, initialRoleId }: RolesScreenProps) {
 34:   const permissionsQ = usePermissionGroups();
 35:   useQueryError(permissionsQ.error?.status === 403 ? undefined : permissionsQ.error);
 36:   const { iAmSuper, myPerms, centralAccess } = useMe();
 37:   const [nameError, setNameError] = useState<string>();
 38:   const [deleteConflict, setDeleteConflict] = useState<string>();
 39:   const loading = rolesLoading || permissionsQ.loading;
 40:   const [selId, setSelId] = useState<number | null>(initialRoleId ?? null);
 41:   const [draft, setDraft] = useState<{ id?: number; name: string; perms: string[]; system?: boolean; builtin?: boolean; isNew?: boolean } | null>(null);
 42:   const [q, setQ] = useState('');
 43:   const [openGroups, setOpenGroups] = useState<Set<string>>(() => new Set(['inventory', 'products', 'pos']));
 44:   const [saving, setSaving] = useState(false);
 45:   const [del, setDel] = useState<AdminRole | null>(null);
 46:   const [roleQ, setRoleQ] = useState('');
 47:   const appliedInitialRole = useRef<number | undefined>(undefined);
 48: 
 49:   useEffect(() => {
 50:     if (initialRoleId && appliedInitialRole.current !== initialRoleId && roles.some(r => r.id === initialRoleId)) {
 51:       setSelId(initialRoleId);
 52:       appliedInitialRole.current = initialRoleId;
 53:     }
 54:   }, [initialRoleId, roles]);
 55: 
 56:   useEffect(() => {
 57:     if (!draft && roles.length && !roles.some(r => r.id === selId)) {
 58:       setSelId((roles.find(r => !r.system) ?? roles[0]).id);
 59:     }
 60:   }, [roles, selId, draft]);
 61: 
 62:   const usersCount = (id: number) => (roles.find(r => r.id === id)?.users_count ?? 0);
 63:   const sel = roles.find(r => r.id === selId);
 64: 
 65:   useEffect(() => {
 66:     if (sel) {
 67:       setDraft({ id: sel.id, name: sel.name, perms: [...sel.perms], system: sel.system, builtin: sel.builtin });
 68:     }
 69:   }, [selId, roles]);
 70: 
 71:   const original = draft?.isNew ? { name: '', perms: [] as string[] } : sel;
 72:   const isDirty = draft && original && (draft.isNew || draft.name !== original.name || draft.perms.length !== original.perms.length || draft.perms.some(p => !original.perms.includes(p)));
 73:   const changeCount = draft && original && !draft.isNew
 74:     ? draft.perms.filter(p => !original.perms.includes(p)).length + original.perms.filter(p => !draft.perms.includes(p)).length + (draft.name !== original.name ? 1 : 0)
 75:     : null;
 76: 
 77:   const fallbackPermissions: Record<string, {name: string}[]> = {};
 78:   (draft?.perms ?? []).forEach(name => (fallbackPermissions[name.split('.')[0]] ??= []).push({name}));
 79:   const permissionGroups = permissionsQ.data ?? buildPermissionGroups(fallbackPermissions);
 80:   const allPerms = permissionGroups.flatMap(g => g.perms.map(p => p[0]));
 81:   const isSystem = draft?.system;
 82:   const editable = centralAccess && !permissionsQ.error && (draft?.isNew ? can('roles.create') || can('roles.manage') : can('roles.update') || can('roles.manage'));
 83:   const togglePerm = (k: string) => {
 84:     if (isSystem || !editable || (!iAmSuper && !myPerms.has(k))) return;
 85:     setDraft(d => d ? { ...d, perms: d.perms.includes(k) ? d.perms.filter(x => x !== k) : [...d.perms, k] } : null);
 86:   };
 87:   const toggleGroup = (g: typeof permissionGroups[0], on: boolean) => {
 88:     if (isSystem || !editable) return;
 89:     const keys = g.perms.map(p => p[0]).filter(key => iAmSuper || myPerms.has(key));
 90:     setDraft(d => d ? { ...d, perms: on ? [...new Set([...d.perms, ...keys])] : d.perms.filter(x => !keys.includes(x)) } : null);
 91:   };
 92:   const toggleOpen = (m: string) => setOpenGroups(s => { const n = new Set(s); n.has(m) ? n.delete(m) : n.add(m); return n; });
 93: 
 94:   const newRole = () => {
 95:     if (!centralAccess || !(can('roles.create') || can('roles.manage')) || permissionsQ.error) return;
 96:     setNameError(undefined);
