 98:     setDraft({ name: '', perms: [], isNew: true });
 99:     setOpenGroups(new Set(permissionGroups.map(g => g.module)));
100:   };
101:   const reset = () => {
102:     if (!draft) return;
103:     if (draft.isNew) {
104:       const fallback = roles.find(r => !r.system) || roles[0];
105:       setDraft(null);
106:       setSelId(fallback?.id ?? null);
107:       return;
108:     }
109:     if (sel) {
110:       setDraft({ id: sel.id, name: sel.name, perms: [...sel.perms], system: sel.system, builtin: sel.builtin });
111:     }
