116:     if ((!draft.builtin || draft.isNew) && ['super admin', 'cashier'].includes(draft.name.normalize('NFKC').trim().toLowerCase())) { setNameError('هذا الاسم محجوز'); return; }
117:     setSaving(true); setNameError(undefined);
118:     const result = await runMutation(() => draft.isNew
