141:     }
142:     setDel(null); setDeleteConflict(undefined); setDraft(null);
143:     setSelId(roles.find(x => x.id !== r.id && !x.system)?.id ?? null); reloadRoles();
144:     toast('تم حذف الدور', 'warn');
145:   };
146: 
147:   const total = Math.max(1, allPerms.length);
148:   const granted = isSystem ? allPerms.length : draft ? draft.perms.length : 0;
149:   const pct = Math.round((granted / total) * 100);
150:   const ql = q.trim().toLowerCase();
151:   const groups = permissionGroups.map(g => ({
