154:   })).filter(g => g.visible.length > 0);
155:   const sensitiveGranted = draft ? permissionGroups.flatMap(g => g.perms).filter(p => p[2] && draft.perms.includes(p[0])).length : 0;
156:   const shownRoles = roles.filter(r => !roleQ || r.name.includes(roleQ));
