 56: export function SettingsScreen({ onNavigate, can }: { onNavigate?: (page: 'users' | 'roles' | 'settings') => void; can: (p: string) => boolean }) {
 57:   const query = useSettingsQuery();
 58:   useQueryError(query.error);
 59:   const [server, setServer] = useState<AdminSettings | null>(null);
 60:   const [s, setS] = useState<AdminSettings | null>(null);
 61:   const [tab, setTab] = useState('company');
 62:   const [saving, setSaving] = useState(false);
 63:   const [conflict, setConflict] = useState<string | false>(false);
 64:   const [fieldErrors, setFieldErrors] = useState<Record<string,string[]>>({});
 65:   const { centralAccess } = useMe();
 66:   const editable = centralAccess && ( can('settings.update') || can('settings.manage'));
 67:   const loading = query.loading && !server;
 68:   useEffect(() => { if (query.data) { setServer(clone(query.data)); setS(clone(query.data)); setFieldErrors({}); } }, [query.data]);
 69:   const set = (group: keyof AdminSettings, key: string, val: any) =>
 70:     setS(p => p && editable ? ({ ...p, [group]: { ...(p[group] as any), [key]: val } }) : p);
 71: 
 72:   const setNum = (doc: string, key: string, val: any) =>
 73:     setS(p => p && editable ? ({ ...p, numbering: { ...p.numbering, [doc]: { ...p.numbering[doc], [key]: val } } }) : p);
 74: 
 75:   // compute changed fields (flat)
 76:   const diffs = useMemo(() => {
 77:     const out: [string, string][] = [];
 78:     if (!s || !server) return out;
 79:     (Object.keys(s) as (keyof AdminSettings)[]).forEach(g => {
 80:       Object.keys(s[g]).forEach(k => {
 81:         if (JSON.stringify((s[g] as any)[k]) !== JSON.stringify((server[g] as any)[k])) {
 82:           out.push([g, k]);
 83:         }
 84:       });
 85:     });
 86:     return out;
 87:   }, [s, server]);
 88: 
 89:   const dirtyGroups = new Set(diffs.map(d => d[0]));
 90:   const isDirty = diffs.length > 0;
 91: 
 92:   useEffect(() => {
 93:     if (!isDirty) return;
 94:     const guard = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ''; };
 95:     window.addEventListener('beforeunload', guard);
 96:     return () => window.removeEventListener('beforeunload', guard);
 97:   }, [isDirty]);
 98:   const save = async () => {
 99:     if (!s || !server || !editable || saving) return;
100:     const patch = settingsPatch(s, server);
101:     if (!Object.keys(patch).length) return;
102:     setSaving(true); setFieldErrors({});
103:     const result = await runMutation(() => adminApi.updateSettings({...patch, expected: settingsExpected(patch, server)}));
104:     setSaving(false);
105:     if (!result.ok) {
106:       if (result.error.status === 422) setFieldErrors(result.error.fields);
107:       if (result.error.status === 409) setConflict(result.error.message);
108:       if (result.error.status !== 401) toast(result.error.message, 'err');
109:       return;
110:     }
111:     const fresh = toAdminSettings(result.data.data);
112:     setServer(clone(fresh)); setS(clone(fresh)); setConflict(false);
113:     if (result.data.warnings?.length) result.data.warnings.forEach(message => toast(message, 'warn'));
114:     else toast('تم حفظ الإعدادات بنجاح');
115:   };
116:   const reload = () => { setConflict(false); query.reload(); };
117:   if (query.error && !server) return <EmptyState icon="lock" title={query.error.message} action={<GhostButton onClick={query.reload}>إعادة المحاولة</GhostButton>} />;
118:   if (!s || !server) return <SettingsSkeleton />;
119: 
120:   return (
121:     <section className="space-y-5 pb-20" data-screen-label="03 Settings">
122:       <PageHeader
123:         title="الإعدادات العامة"
124:         subtitle="هوية المؤسسة، الضرائب، الترقيم التلقائي للمستندات، سياسات الإرجاع وسير عمل المشتريات."
125:         action={
126:           <div className="flex items-center gap-3 stagger-item stagger-2">
127:             {onNavigate && (
128:               <GhostButton icon="users" onClick={() => onNavigate('users')}>
129:                 فريق العمل
130:               </GhostButton>
131:             )}
132:           </div>
133:         }
134:       />
135: 
136:       {conflict && (
137:         <div className="v-conflict rounded-[22px] p-4 flex flex-wrap items-center gap-4 v-pop-in">
138:           <span className="w-10 h-10 rounded-full flex items-center justify-center bg-white/15 shrink-0"><Icon name="alert" className="w-5 h-5" strokeWidth={2.2} /></span>
139:           <div className="flex-1 min-w-[240px]">
140:             <div className="font-semibold text-[14px]">تعارض في البيانات (409)</div>
141:             <div className="text-[12.5px] opacity-85 mt-0.5">{conflict}</div>
142:           </div>
143:           <div className="flex items-center gap-2">
144:             <button type="button" onClick={() => setConflict(false)} className="h-9 px-4 rounded-full text-[12.5px] font-semibold hover:bg-white/10">لاحقاً</button>
145:             <button type="button" onClick={reload} className="h-9 px-4 rounded-full text-[12.5px] font-semibold bg-white flex items-center gap-1.5" style={{ color: '#c2410c' }}><Icon name="refresh" className="w-3.5 h-3.5" strokeWidth={2.2} />إعادة التحميل</button>
146:           </div>
147:         </div>
148:       )}
149: 
150:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
151:         {/* Tabs rail */}
152:         <nav className="lg:col-span-3 v-card p-2 stagger-item stagger-2 lg:sticky lg:top-5">
153:           {SETTINGS_TABS.map((t) => {
154:             const active = tab === t.key;
155:             return (
156:               <button type="button" key={t.key} onClick={() => setTab(t.key)}
157:                 className={`w-full flex items-center gap-3 p-3 rounded-2xl text-start transition ${active ? 'v-tab-active' : 'v-tab'}`}>
158:                 <span className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${active ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={t.icon} className="w-4 h-4" /></span>
159:                 <div className="flex-1 min-w-0">
160:                   <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{t.label}</div>
161:                   <div className="text-[11px] truncate" style={{ color: 'var(--text-muted)' }}>{t.desc}</div>
162:                 </div>
163:                 {dirtyGroups.has(t.key) && <span className="w-2 h-2 rounded-full shrink-0" style={{ background: 'var(--accent-orange)' }} title="تعديلات غير محفوظة" />}
164:               </button>
165:             );
166:           })}
167:         </nav>
168: 
169:         <div className="lg:col-span-9 stagger-item stagger-3" key={tab}>
170:           {loading ? <SettingsSkeleton /> : (
171:             <fieldset disabled={!editable || saving} className="v-tab-in space-y-5">
172:               {tab === 'company' && <CompanyTab errors={fieldErrors} v={s.company} set={(k, val) => set('company', k, val)} />}
173:               {tab === 'tax' && <TaxTab errors={fieldErrors} v={s.tax} set={(k, val) => set('tax', k, val)} />}
174:               {tab === 'numbering' && <NumberingTab errors={fieldErrors} v={s.numbering} server={server.numbering} setNum={setNum} />}
175:               {tab === 'orders' && <ReturnsTab v={s.orders} set={(k, val) => set('orders', k, val)} />}
176:               {Object.entries(fieldErrors).filter(([key]) => !['company','tax','numbering'].includes(tab) && key in s[tab as 'orders' | 'purchases']).map(([key,messages]) => <div role="alert" key={key}>{messages.join('، ')}</div>)}
177:               {tab === 'purchases' && <PurchasesTab v={s.purchases} set={(k, val) => set('purchases', k, val)} />}
178:             </fieldset>
179:           )}
180:         </div>
181:       </div>
182: 
183:       <StickyBar show={isDirty && editable} onSave={save} onReset={() => setS(clone(server))} saving={saving} count={diffs.length} />
184:     </section>
185:   );
186: }
