191:       <Skeleton className="h-5 w-40 rounded" /><Skeleton className="h-3 w-64 rounded" />
192:       <div className="flex gap-4 pt-2"><Skeleton className="w-24 h-24 rounded-2xl" /><div className="flex-1 space-y-3"><Skeleton className="h-11 rounded-2xl" /><Skeleton className="h-3 w-40 rounded" /></div></div>
193:       <div className="grid grid-cols-2 gap-4">{[1, 2, 3, 4].map(i => <Skeleton key={i} className="h-11 rounded-2xl" />)}</div>
194:       <Skeleton className="h-24 rounded-2xl" />
195:     </div>
196:   );
197: }
