206:       <div className="v-subcard p-4 flex flex-wrap items-center gap-5 mb-6">
207:         <div className="w-[92px] h-[92px] rounded-[20px] flex items-center justify-center overflow-hidden shrink-0 v-logo-box">
208:           {v.company_logo && !logoErr ? <img src={v.company_logo} onError={() => setLogoErr(true)} className="w-full h-full object-contain p-2" alt="Logo" />
209:             : <div className="flex flex-col items-center gap-1" style={{ color: 'var(--text-muted)' }}><Icon name="image" className="w-6 h-6" strokeWidth={1.6} /><span className="text-[10px]">{logoErr ? 'رابط غير صالح' : 'لا يوجد شعار'}</span></div>}
210:         </div>
211:         <div className="flex-1 min-w-[240px]">
212:           <Field label="رابط شعار المنشأة" hint="PNG أو SVG بخلفية شفافة، يُفضّل 512×512 بكسل." error={errors.company_logo?.[0] || (logoErr ? 'تعذّر تحميل الصورة من هذا الرابط' : null)}>
213:             <TextInput value={v.company_logo} onChange={x => set('company_logo', x)} icon="link" dir="ltr" placeholder="https://cdn.company.com/logo.png" error={logoErr} />
