217:       <div className="grid grid-cols-1 md:grid-cols-2 gap-x-5 gap-y-4">
218:         <Field label="اسم الشركة" required className="md:col-span-2" error={errors.company_name?.[0] || (!v.company_name.trim() ? 'اسم الشركة مطلوب' : null)}>
219:           <TextInput value={v.company_name} onChange={x => set('company_name', x)} icon="building" placeholder="الاسم التجاري للمنشأة" error={!v.company_name.trim()} />
220:         </Field>
221:         <Field error={errors.company_email?.[0]} label="البريد الإلكتروني للشركة"><TextInput value={v.company_email} onChange={x => set('company_email', x)} icon="mail" dir="ltr" /></Field>
222:         <Field error={errors.company_phone?.[0]} label="رقم الهاتف الرسمي"><TextInput value={v.company_phone} onChange={x => set('company_phone', x)} icon="phone" dir="ltr" /></Field>
223:         <Field error={errors.commercial_register?.[0]} label="رقم السجل التجاري"><TextInput value={v.commercial_register} onChange={x => set('commercial_register', x)} icon="doc" dir="ltr" /></Field>
224:         <div />
225:         <Field error={errors.company_address?.[0]} label="عنوان المقر الرئيسي" className="md:col-span-2">
226:           <textarea value={v.company_address} onChange={e => set('company_address', e.target.value)} rows={3}
227:             className="v-input w-full px-3.5 py-3 text-[13px] outline-none resize-none leading-relaxed" style={{ color: 'var(--text-primary)' }} />
228:         </Field>
229:       </div>
230:     </SectionCard>
231: 
232:     {/* Invoice header preview */}
233:     <SectionCard title="معاينة ترويسة الفاتورة" subtitle="هكذا ستظهر بيانات الشركة أعلى المستندات المطبوعة.">
234:       <div className="v-paper rounded-2xl p-6">
235:         <div className="flex items-start justify-between gap-6 pb-5" style={{ borderBottom: '1.5px dashed rgba(24,21,28,.14)' }}>
236:           <div className="flex items-start gap-4">
237:             <div className="w-14 h-14 rounded-xl flex items-center justify-center overflow-hidden shrink-0" style={{ background: '#f5f2f6' }}>
238:               {v.company_logo && !logoErr ? <img src={v.company_logo} className="w-full h-full object-contain p-1" alt="Logo preview" /> :
239:                 <div className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }}><svg className="w-4 h-4 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 5l7 14 7-14" /></svg></div>}
240:             </div>
241:             <div>
242:               <div className="font-display text-[17px] font-bold text-[#18151c]">{v.company_name || '—'}</div>
243:               <div className="text-[11.5px] text-[#78737e] mt-1 whitespace-pre-line leading-relaxed">{v.company_address}</div>
244:             </div>
245:           </div>
246:           <div className="text-[11.5px] text-[#78737e] space-y-1 text-end shrink-0">
247:             <div dir="ltr">{v.company_phone}</div>
248:             <div dir="ltr">{v.company_email}</div>
249:             <div>س.ت: <span className="text-[#18151c] font-semibold">{v.commercial_register}</span></div>
250:           </div>
251:         </div>
252:         <div className="flex items-center justify-between pt-4">
253:           <span className="font-display text-[22px] font-bold text-[#18151c] tracking-tight">فاتورة ضريبية</span>
254:           <span className="font-mono text-[12px] font-semibold px-3 py-1 rounded-full" style={{ background: '#fde8e1', color: '#c2410c' }}>INV-001042</span>
255:         </div>
256:       </div>
257:     </SectionCard>
258:   </>;
