261: /* ---------- Tab 2: Tax ---------- */
262: function TaxTab({ errors, v, set }: { errors: Record<string,string[]>; v: AdminSettings['tax']; set: (k: keyof AdminSettings['tax'], val: any) => void }) {
263:   const [sample, setSample] = useState(1000);
264:   const rate = Number(v.default_tax_rate) || 0;
265:   const on = v.tax_enabled;
266:   let net: number, tax: number, gross: number;
267:   if (!on) { net = sample; tax = 0; gross = sample; }
268:   else if (v.prices_include_tax) { gross = sample; net = sample / (1 + rate / 100); tax = gross - net; }
269:   else { net = sample; tax = (sample * rate) / 100; gross = net + tax; }
270:   const rateErr = rate < 0 || rate > 100;
271: 
272:   return (
273:     <div className="grid grid-cols-1 xl:grid-cols-5 gap-5 items-start">
274:       <SectionCard title="ضريبة القيمة المضافة" subtitle="إعدادات الضريبة المطبّقة على الفواتير الإلكترونية." className="xl:col-span-3">
275:         <div className="v-subcard p-4 flex items-center justify-between gap-4">
276:           <div className="flex items-center gap-3">
277:             <span className={`w-10 h-10 rounded-full flex items-center justify-center ${on ? 'v-badge-green' : 'v-icon-well'}`}><Icon name="percent" className="w-4 h-4" /></span>
278:             <div>
279:               <div className="text-[13.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>تفعيل ضريبة القيمة المضافة</div>
280:               <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>{on ? 'تُحتسب الضريبة على جميع الفواتير' : 'لن تُضاف أي ضريبة على الفواتير'}</div>
281:             </div>
282:           </div>
283:           <Toggle on={on} onChange={x => set('tax_enabled', x)} />
284:         </div>
285: 
286:         <div className={`transition-opacity ${on ? '' : 'opacity-45 pointer-events-none'}`}>
287:           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-5">
288:             <Field error={errors.tax_number?.[0]} label="الرقم الضريبي" hint="يُطبع على الفواتير الإلكترونية.">
289:               <TextInput value={v.tax_number} onChange={x => set('tax_number', x)} icon="hash" dir="ltr" />
290:             </Field>
291:             <Field label="نسبة الضريبة الافتراضية" error={errors.default_tax_rate?.[0] || (rateErr ? 'النسبة يجب أن تكون بين 0 و 100' : null)}>
292:               <TextInput value={v.default_tax_rate} onChange={x => set('default_tax_rate', x === '' ? '' : Number(x))} type="number" dir="ltr" error={rateErr}
293:                 suffix={<span className="text-[13px] font-semibold" style={{ color: 'var(--text-muted)' }}>%</span>} />
294:             </Field>
295:           </div>
296:           <div className="flex flex-wrap gap-1.5 mt-2.5">
297:             {[5, 10, 14, 15].map(r => (
298:               <button type="button" key={r} onClick={() => set('default_tax_rate', r)} className="px-3 h-7 rounded-full text-[11.5px] font-semibold transition"
299:                 style={rate === r ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-subcard)', color: 'var(--text-secondary)' }}>{r}%</button>
300:             ))}
301:           </div>
302: 
303:           <div className="mt-6">
304:             <div className="text-[12.5px] font-semibold mb-2.5" style={{ color: 'var(--text-primary)' }}>طريقة احتساب الأسعار</div>
305:             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
306:               {[
307:                 { val: true, title: 'الأسعار شاملة الضريبة', en: 'Tax-Inclusive', desc: 'السعر المعروض هو ما يدفعه العميل، وتُستخرج الضريبة منه.' },
308:                 { val: false, title: 'الأسعار غير شاملة الضريبة', en: 'Tax-Exclusive', desc: 'تُضاف الضريبة فوق السعر المعروض عند إصدار الفاتورة.' },
309:               ].map(o => {
310:                 const act = v.prices_include_tax === o.val;
311:                 return (
312:                   <button type="button" key={String(o.val)} onClick={() => set('prices_include_tax', o.val)} className={`v-choice rounded-2xl p-4 text-start ${act ? 'is-on' : ''}`}>
313:                     <div className="flex items-center justify-between">
314:                       <span className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{o.title}</span>
315:                       <span className="v-radio"><span /></span>
316:                     </div>
317:                     <div className="text-[10.5px] font-mono mt-0.5" style={{ color: 'var(--accent-orange)' }}>{o.en}</div>
318:                     <div className="text-[11.5px] mt-2 leading-relaxed" style={{ color: 'var(--text-muted)' }}>{o.desc}</div>
319:                   </button>
320:                 );
321:               })}
322:             </div>
323:           </div>
324:         </div>
325:       </SectionCard>
326: 
327:       {Object.entries(errors).filter(([key]) => ['tax_number','default_tax_rate','tax_enabled','prices_include_tax'].includes(key)).map(([key, messages]) => <div role="alert" key={key}>{messages.join('، ')}</div>)}
328:       {/* Live calculator */}
329:       <div className="xl:col-span-2 v-card p-5 xl:sticky xl:top-5">
330:         <div className="flex items-center justify-between">
331:           <h3 className="font-display text-[16px] font-semibold" style={{ color: 'var(--text-primary)' }}>محاكاة حية</h3>
332:           <Badge tone={on ? 'green' : 'neutral'} dot>{on ? (v.prices_include_tax ? 'شامل' : 'غير شامل') : 'بدون ضريبة'}</Badge>
333:         </div>
334:         <p className="text-[11.5px] mt-1" style={{ color: 'var(--text-muted)' }}>غيّر سعر المنتج لترى أثر إعداداتك الحالية.</p>
335: 
336:         <div className="v-subcard p-4 mt-4">
337:           <div className="text-[11.5px] font-medium" style={{ color: 'var(--text-secondary)' }}>سعر المنتج المُدخل</div>
338:           <div className="flex items-baseline gap-2 mt-1">
339:             <input type="number" value={sample} onChange={e => setSample(Math.max(0, Number(e.target.value)))} dir="ltr"
340:               className="bg-transparent outline-none font-display text-[30px] font-bold w-full tabular-nums" style={{ color: 'var(--text-primary)' }} />
341:             <span className="text-[13px] font-semibold shrink-0" style={{ color: 'var(--text-muted)' }}>ج.م</span>
342:           </div>
343:           <input type="range" min="0" max="10000" step="50" value={sample} onChange={e => setSample(Number(e.target.value))} className="v-slider mt-2"
344:             style={{ background: `linear-gradient(to left, #e0491f ${(sample / 10000) * 100}%, var(--toggle-off-bg) ${(sample / 10000) * 100}%)` }} />
345:         </div>
346: 
347:         <div className="mt-4 space-y-0 v-divide">
348:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>الصافي قبل الضريبة</span><span className="font-semibold tabular-nums" style={{ color: 'var(--text-primary)' }}>{fmtMoney(net)}</span></div>
349:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>قيمة الضريبة ({on ? rate : 0}%)</span><span className="font-semibold tabular-nums" style={{ color: 'var(--accent-orange)' }}>+ {fmtMoney(tax)}</span></div>
350:         </div>
351: 
352:         <div className="v-orange-earnings rounded-[18px] p-4 mt-2">
353:           <div className="text-[12px] text-white/85">الإجمالي المستحق</div>
354:           <div className="font-display text-[28px] font-bold tabular-nums mt-0.5">{fmtMoney(gross)} <span className="text-[14px] font-medium text-white/80">ج.م</span></div>
355:           <div className="mt-3 h-3 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5 bg-white/10">
356:             <div className="h-full rounded-full bg-white transition-all duration-300" style={{ width: `${gross ? (net / gross) * 100 : 100}%` }} />
357:             <div className="h-full flex-1 rounded-full rewards-hatched-track" />
358:           </div>
359:           <div className="flex justify-between text-[10.5px] text-white/80 mt-1.5"><span>صافي</span><span>ضريبة</span></div>
360:         </div>
361:       </div>
362:     </div>
363:   );
364: }
365: 
366: /* ---------- Tab 3: Numbering ---------- */
367: function NumberingTab({ errors, v, server, setNum }: { errors: Record<string,string[]>; v: AdminSettings['numbering']; server: AdminSettings['numbering']; setNum: (doc: string, key: string, val: any) => void }) {
368:   const [q, setQ] = useState('');
369:   const docs = DOC_TYPES.filter(d => !q || d.label.includes(q) || d.key.includes(q.toLowerCase()) || v[d.key]?.prefix?.toLowerCase().includes(q.toLowerCase()));
370: 
371:   return (
372:     <SectionCard title="ترقيم المستندات" subtitle="حدد البادئة وطول الرقم والرقم التسلسلي التالي لكل نوع من وثائق النظام."
373:       aside={<div className="v-subcard px-3.5 h-9 rounded-full flex items-center gap-2 shrink-0">
374:         <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
375:         <input value={q} onChange={e => setQ(e.target.value)} placeholder="بحث عن مستند" className="bg-transparent text-[12.5px] outline-none w-32" style={{ color: 'var(--text-primary)' }} />
376:       </div>}>
377:       {docs.length === 0 && <EmptyState title="لا توجد مستندات مطابقة" text="جرّب البحث باسم المستند أو البادئة مثل INV-." />}
378:       <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
379:         {docs.map(d => {
380:           const n = v[d.key];
381:           if (!n) return null;
382:           const s = server[d.key] || n;
383:           const pad = Math.min(20, Math.max(1, Number(n.padding) || 1));
384:           const preview = `${n.prefix}${String(n.next_number || 0).padStart(pad, '0')}`;
385:           const changed = JSON.stringify(n) !== JSON.stringify(s);
386:           const padErr = n.padding < 1 || n.padding > 20;
387:           const lower = Number(n.next_number) < s.next_number;
388:           return (
389:             <div key={d.key} className={`v-subcard p-4 v-doc ${changed ? 'is-changed' : ''}`}>
390:               <div className="flex items-center justify-between gap-2 mb-3.5">
391:                 <div className="flex items-center gap-2.5 min-w-0">
392:                   <span className="w-8 h-8 rounded-[10px] flex items-center justify-center shrink-0" style={{ background: 'var(--bg-card)', color: 'var(--text-secondary)' }}><Icon name="doc" className="w-4 h-4" /></span>
393:                   <div className="min-w-0">
394:                     <div className="text-[13px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>{d.label}</div>
395:                     <div className="text-[10.5px] font-mono" style={{ color: 'var(--text-muted)' }}>{d.key}</div>
396:                   </div>
397:                 </div>
398:                 <span dir="ltr" className="v-preview-badge font-mono text-[12px] font-bold px-3 py-1.5 rounded-full truncate max-w-[55%]" title="المستند التالي">{preview}</span>
399:               </div>
400:               <div className="grid grid-cols-[1.1fr_.8fr_1.2fr] gap-2">
401:                 <div>
402:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>البادئة</div>
403:                   <input dir="ltr" value={n.prefix} onChange={e => setNum(d.key, 'prefix', e.target.value.toUpperCase())} className="v-mini-input w-full font-mono" />
404:                 </div>
405:                 <div>
406:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>حشو الأصفار</div>
407:                   <div className={`v-mini-input flex items-center !px-1 ${padErr ? 'is-error' : ''}`}>
408:                     <button type="button" onClick={() => setNum(d.key, 'padding', Math.max(1, pad - 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>−</button>
409:                     <input dir="ltr" type="number" min="1" max="20" value={n.padding} onChange={e => setNum(d.key, 'padding', Number(e.target.value))} className="bg-transparent outline-none w-full text-center tabular-nums" />
410:                     <button type="button" onClick={() => setNum(d.key, 'padding', Math.min(20, pad + 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>+</button>
411:                   </div>
412:                 </div>
413:                 <div>
414:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>الرقم التالي</div>
415:                   <input dir="ltr" type="number" min="1" max="999999999" value={n.next_number} onChange={e => setNum(d.key, 'next_number', Number(e.target.value))} className={`v-mini-input w-full tabular-nums ${lower ? 'is-warn' : ''}`} />
416:                 </div>
417:               </div>
418:               {(['prefix','padding','next_number'] as const).map(key => errors[d.key+'_'+key]?.map(message => <div role="alert" key={key+message} className="text-[11px] v-badge-red">{message}</div>))}
419:               {padErr && <div role="alert" className="text-[11px] v-badge-red">حشو الأصفار يجب أن يكون بين 1 و20</div>}
420:               {lower && <div className="text-[10.5px] mt-2 flex items-center gap-1 font-medium" style={{ color: '#b45309' }}><Icon name="alert" className="w-3 h-3" />رقم أقل من الحالي ({s.next_number}) لا يمكن حفظه</div>}
421:             </div>
422:           );
423:         })}
424:       </div>
425:     </SectionCard>
426:   );
427: }
