429: /* ---------- Tab 4: Returns ---------- */
430: function ReturnsTab({ v, set }: { v: AdminSettings['orders']; set: (k: keyof AdminSettings['orders'], val: any) => void }) {
431:   const d = v.return_window_days;
432:   const mode = d === 0 ? 'off' : d === -1 ? 'unlimited' : 'days';
433:   const [lastDays, setLastDays] = useState(d > 0 ? d : 14);
434:   useEffect(() => { if (d > 0) setLastDays(d); }, [d]);
435: 
436:   const cards = [
437:     { key: 'off', title: 'متوقف', desc: 'لا يُسمح بإرجاع المنتجات نهائياً.', icon: 'ban', val: 0, code: '0' },
438:     { key: 'days', title: 'خلال عدد أيام', desc: 'الإرجاع متاح لمدة محددة من تاريخ تسليم الطلب.', icon: 'calendar', val: lastDays, code: 'n' },
439:     { key: 'unlimited', title: 'غير محدود', desc: 'الإرجاع متاح في أي وقت دون قيود زمنية.', icon: 'infinity', val: -1, code: '-1' },
440:   ];
441: 
442:   const delivered = new Date();
443:   const deadline = new Date(delivered.getTime() + lastDays * 864e5);
444: 
445:   return (
446:     <SectionCard title="سياسة المبيعات والمرتجعات" subtitle="حدد المهلة المسموح خلالها للعميل بإرجاع المنتجات بعد التسليم.">
447:       <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
448:         {cards.map(c => {
449:           const act = mode === c.key;
450:           return (
451:             <button type="button" key={c.key} onClick={() => set('return_window_days', c.val)} className={`v-choice rounded-[18px] p-4 text-start ${act ? 'is-on' : ''}`}>
452:               <div className="flex items-center justify-between">
453:                 <span className={`w-10 h-10 rounded-xl flex items-center justify-center ${act ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={c.icon} className="w-[18px] h-[18px]" /></span>
454:                 <span className="v-radio"><span /></span>
455:               </div>
456:               <div className="text-[14px] font-semibold mt-3" style={{ color: 'var(--text-primary)' }}>{c.title}</div>
457:               <div className="text-[11.5px] mt-1 leading-relaxed" style={{ color: 'var(--text-muted)' }}>{c.desc}</div>
458:               <div className="text-[10.5px] font-mono mt-2" style={{ color: 'var(--text-muted)' }}>return_window_days = {c.key === 'days' ? lastDays : c.code}</div>
459:             </button>
460:           );
461:         })}
462:       </div>
463: 
464:       <div className="v-collapse" style={{ gridTemplateRows: mode === 'days' ? '1fr' : '0fr' }}>
465:         <div className="overflow-hidden">
466:           <div className="v-subcard p-5 mt-4">
467:             <div className="flex flex-wrap items-center justify-between gap-4">
468:               <div>
469:                 <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>عدد الأيام المسموح بها</div>
470:                 <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>تُحتسب من تاريخ تسليم الطلب للعميل</div>
471:               </div>
472:               <div className="flex items-center gap-2">
473:                 {[7, 14, 30, 60].map(n => (
474:                   <button type="button" key={n} onClick={() => set('return_window_days', n)} className="px-3.5 h-8 rounded-full text-[12px] font-semibold transition"
475:                     style={d === n ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-card)', color: 'var(--text-secondary)' }}>{n} يوم</button>
476:                 ))}
477:                 <div className="flex items-center gap-1.5 h-8 ps-3 pe-1 rounded-full" style={{ background: 'var(--bg-card)' }}>
478:                   <input type="number" min="1" max="365" value={d > 0 ? d : lastDays} onChange={e => set('return_window_days', Math.max(1, Number(e.target.value)))} dir="ltr"
479:                     className="bg-transparent outline-none w-10 text-center text-[13px] font-bold tabular-nums" style={{ color: 'var(--text-primary)' }} />
480:                   <span className="text-[11.5px] pe-2" style={{ color: 'var(--text-muted)' }}>يوم</span>
481:                 </div>
482:               </div>
483:             </div>
484:             {/* Timeline */}
485:             <div className="mt-6">
486:               <div className="h-3.5 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5">
487:                 <div className="h-full rounded-full transition-all duration-500" style={{ width: `${Math.min(100, (lastDays / 90) * 100)}%`, background: 'var(--accent-orange)' }} />
488:                 <div className="h-full flex-1 rounded-full spending-hatched-track" />
489:               </div>
490:               <div className="flex justify-between mt-2.5 text-[11.5px]">
491:                 <span style={{ color: 'var(--text-secondary)' }}><b style={{ color: 'var(--text-primary)' }}>التسليم</b> · {fmtDate(delivered)}</span>
492:                 <span style={{ color: 'var(--text-secondary)' }}>آخر موعد للإرجاع · <b style={{ color: 'var(--accent-orange)' }}>{fmtDate(deadline)}</b></span>
493:               </div>
494:             </div>
495:           </div>
496:         </div>
497:       </div>
498: 
499:       {mode === 'off' && <Notice tone="warn" className="mt-4" title="الإرجاع متوقف">لن يتمكن الموظفون من إنشاء مرتجعات مبيعات جديدة من أي فرع.</Notice>}
500:       {mode === 'unlimited' && <Notice tone="info" className="mt-4">يمكن إرجاع أي طلب مُسلّم دون قيود زمنية، مع خضوع المرتجع لدورة الاعتماد المعتادة.</Notice>}
501:     </SectionCard>
502:   );
503: }
