505: /* ---------- Tab 5: Purchases ---------- */
506: function PurchasesTab({ v, set }: { v: AdminSettings['purchases']; set: (k: keyof AdminSettings['purchases'], val: any) => void }) {
507:   const on = v.allow_self_approve_purchases;
508: 
509:   const Step = ({ who, label, active, icon, last }: { who: string; label: string; active?: boolean; icon: string; last?: boolean }) => (
510:     <div className="flex items-center gap-3 flex-1 min-w-[140px]">
511:       <div className="flex flex-col items-center gap-2 flex-1">
512:         <span className={`w-11 h-11 rounded-full flex items-center justify-center ${active ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={icon} className="w-[18px] h-[18px]" /></span>
513:         <div className="text-center"><div className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>{label}</div><div className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{who}</div></div>
514:       </div>
515:       {!last && <Icon name="chevLeft" className="w-4 h-4 shrink-0 -mt-8" style={{ color: 'var(--text-muted)' }} />}
516:     </div>
517:   );
518: 
519:   return <>
520:     <SectionCard title="دورة المشتريات" subtitle="التحكم في صلاحيات اعتماد طلبات وأوامر الشراء.">
521:       <div className="v-subcard p-5 flex items-start justify-between gap-5">
522:         <div className="flex items-start gap-3.5">
523:           <span className={`w-11 h-11 rounded-full flex items-center justify-center shrink-0 ${on ? 'v-badge-orange' : 'v-badge-green'}`}><Icon name={on ? 'userCheck' : 'dual'} className="w-5 h-5" /></span>
524:           <div>
525:             <div className="text-[14px] font-semibold" style={{ color: 'var(--text-primary)' }}>السماح بالاعتماد الذاتي لأوامر الشراء</div>
526:             <div className="text-[12px] mt-1 leading-relaxed max-w-[560px]" style={{ color: 'var(--text-secondary)' }}>
527:               هل يحق لنفس الموظف الذي أنشأ طلب/أمر الشراء أن يعتمده بنفسه (إذا كان يملك صلاحية <span className="font-mono text-[11px] px-1.5 py-0.5 rounded" style={{ background: 'var(--bg-card)' }} dir="ltr">purchases.approve</span>)، أم يشترط النظام موافقة موظف أو مدير آخر؟
528:             </div>
529:             <div className="text-[10.5px] font-mono mt-2" style={{ color: 'var(--text-muted)' }} dir="ltr">allow_self_approve_purchases = {String(on)}</div>
530:           </div>
531:         </div>
532:         <Toggle on={on} onChange={x => set('allow_self_approve_purchases', x)} />
533:       </div>
534: 
535:       <div className="mt-5">
536:         <div className="text-[12px] font-semibold mb-4" style={{ color: 'var(--text-muted)' }}>سير العمل الحالي</div>
537:         <div className="flex flex-wrap items-start gap-2">
538:           <Step icon="doc" label="إنشاء أمر الشراء" who="الموظف (أ)" active />
539:           <Step icon={on ? 'userCheck' : 'dual'} label="الاعتماد" who={on ? 'الموظف (أ) نفسه' : 'موظف/مدير آخر (ب)'} active />
540:           <Step icon="truck" label="استلام البضاعة" who="أمين المستودع" last />
541:         </div>
542:       </div>
543: 
544:       {on ? (
545:         <Notice tone="warn" className="mt-5" title="الرقابة الثنائية معطّلة">
546:           يمكن للموظف إنشاء أمر شراء واعتماده دون مراجعة. يُنصح بتعطيل هذا الخيار في الشركات الكبيرة لضمان الفصل بين الصلاحيات.
547:         </Notice>
548:       ) : (
549:         <div className="v-notice-ok rounded-2xl px-4 py-3 flex items-start gap-3 mt-5">
550:           <Icon name="shieldCheck" className="w-4 h-4 mt-0.5 shrink-0" strokeWidth={2} />
551:           <div className="text-[12.5px] leading-relaxed"><div className="font-semibold mb-0.5">الرقابة الثنائية (Dual Control) مفعّلة</div><div className="opacity-90">الخيار الموصى به للشركات الكبيرة — يضمن الفصل بين صلاحيات الإنشاء والاعتماد.</div></div>
552:         </div>
553:       )}
554:     </SectionCard>
555:   </>;
