 61: export function Icon({ name, className = 'w-4 h-4', strokeWidth = 1.9, style }: { name: string; className?: string; strokeWidth?: number; style?: CSSProperties }) {
 62:   return (
 63:     <svg className={className} style={style} fill="none" stroke="currentColor" strokeWidth={strokeWidth} viewBox="0 0 24 24">
 64:       {ICON_PATHS[name]}
 65:     </svg>
 66:   );
 67: }
 68: 
 69: export function Toggle({ on, onChange, disabled, size = 'md' }: { on: boolean; onChange: (val: boolean) => void; disabled?: boolean; size?: 'sm' | 'md' }) {
 70:   const w = size === 'sm' ? 'w-9 h-5' : 'w-11 h-6';
 71:   const k = size === 'sm' ? 'w-4 h-4' : 'w-5 h-5';
 72:   return (
 73:     <button type="button" role="switch" aria-checked={on} disabled={disabled}
 74:       onClick={() => !disabled && onChange(!on)}
 75:       className={`${w} rounded-full p-0.5 transition-colors duration-200 flex items-center shrink-0 ${disabled ? 'opacity-45 cursor-not-allowed' : ''}`}
 76:       style={{ background: on ? 'var(--accent-orange)' : 'var(--toggle-off-bg)', justifyContent: on ? 'flex-start' : 'flex-end' }}>
 77:       <span className={`${k} rounded-full bg-white shadow-sm block`} />
 78:     </button>
 79:   );
 80: }
 81: 
 82: export function Badge({ tone = 'neutral', children, className = '', dot }: { tone?: 'green' | 'red' | 'orange' | 'neutral' | 'dark' | 'outline'; children: ReactNode; className?: string; dot?: boolean }) {
 83:   const tones = {
 84:     green: 'v-badge-green', red: 'v-badge-red',
 85:     orange: 'v-badge-orange', neutral: 'v-badge-neutral', dark: 'v-badge-dark', outline: 'v-badge-outline',
 86:   };
 87:   return (
 88:     <span className={`${tones[tone]} inline-flex items-center gap-1.5 px-2.5 py-[3px] rounded-full text-[11px] font-semibold whitespace-nowrap ${className}`}>
 89:       {dot && <span className="w-1.5 h-1.5 rounded-full" style={{ background: 'currentColor' }} />}
 90:       {children}
 91:     </span>
 92:   );
 93: }
 94: 
 95: export const AVATAR_TONES = [
 96:   ['#fde8e1', '#c2410c'], ['#e8e4f7', '#5b4bb7'], ['#dcf3ea', '#11795a'], ['#fbeccc', '#a1620a'],
 97:   ['#e2eefb', '#2d6aa8'], ['#f7e1ec', '#b03a72'],
 98: ];
 99: 
100: export function Avatar({ name, id = 0, size = 36, ring }: { name: string; id?: number; size?: number; ring?: boolean }) {
101:   const parts = name.trim().split(/\s+/);
102:   const initials = (parts[0]?.[0] || '') + (parts[1]?.[0] || '');
103:   const [bg, fg] = AVATAR_TONES[Math.abs(id) % AVATAR_TONES.length];
104:   return (
105:     <div className="rounded-full flex items-center justify-center font-semibold shrink-0 avatar-chip"
106:       style={{ width: size, height: size, background: bg, color: fg, fontSize: size * 0.36, boxShadow: ring ? '0 0 0 2px var(--bg-card), 0 0 0 3.5px var(--accent-orange)' : undefined }}>
107:       {initials}
108:     </div>
109:   );
110: }
111: 
112: export function Field({ label, hint, error, required, children, className = '', aside }: { label: string; hint?: string; error?: string | null; required?: boolean; children: ReactNode; className?: string; aside?: ReactNode }) {
113:   return (
114:     <label className={`block ${className}`}>
115:       <div className="flex items-center justify-between mb-1.5">
116:         <span className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>
117:           {label}{required && <span style={{ color: 'var(--accent-orange)' }}> *</span>}
118:         </span>
119:         {aside}
120:       </div>
121:       {children}
122:       {error ? <div className="text-[11.5px] mt-1.5 font-medium" style={{ color: 'var(--badge-red-text)' }}>{error}</div>
123:         : hint ? <div className="text-[11.5px] mt-1.5" style={{ color: 'var(--text-muted)' }}>{hint}</div> : null}
124:     </label>
125:   );
126: }
127: 
128: export function TextInput({ value, onChange, placeholder, icon, dir, type = 'text', disabled, error, suffix, className = '', ...rest }: {
129:   value: string | number | undefined;
130:   onChange: (v: string) => void;
131:   placeholder?: string;
132:   icon?: string;
133:   dir?: string;
134:   type?: string;
135:   disabled?: boolean;
136:   error?: string | boolean | null;
137:   suffix?: ReactNode;
138:   className?: string;
139:   [key: string]: unknown;
140: }) {
141:   return (
142:     <div className={`v-input flex items-center gap-2 px-3.5 h-11 ${error ? 'is-error' : ''} ${disabled ? 'is-disabled' : ''} ${className}`}>
143:       {icon && <Icon name={icon} className="w-4 h-4 shrink-0" style={{ color: 'var(--text-muted)' }} />}
144:       <input type={type} value={value ?? ''} disabled={disabled} dir={dir} placeholder={placeholder}
145:         onChange={e => onChange(e.target.value)}
146:         className="bg-transparent outline-none w-full text-[13px] h-full" style={{ color: 'var(--text-primary)' }} {...rest} />
147:       {suffix}
148:     </div>
149:   );
150: }
151: 
152: export function useOutside(ref: React.RefObject<HTMLElement | null>, cb: () => void, active: boolean) {
153:   useEffect(() => {
154:     if (!active) return;
155:     const h = (e: MouseEvent) => {
156:       // Document listeners see the shadow host as target; inspect the original path.
157:       if (ref.current && !e.composedPath().includes(ref.current)) cb();
158:     };
159:     document.addEventListener('mousedown', h);
160:     return () => document.removeEventListener('mousedown', h);
161:   }, [active, cb, ref]);
162: }
