164: export interface SelectOption {
165:   value: string | number | null;
166:   label: string;
167:   icon?: string;
168:   meta?: string;
169:   disabled?: boolean;
170: }
171: 
172: export function Select({ value, onChange, options, placeholder = 'اختر', searchable, icon, compact, renderValue, width, disabled }: {
173:   value: string | number | null;
174:   onChange: (v: any) => void;
175:   options: SelectOption[];
176:   placeholder?: string;
177:   searchable?: boolean;
178:   icon?: string;
179:   compact?: boolean;
180:   renderValue?: (cur?: SelectOption) => ReactNode;
181:   width?: number | string;
182:   disabled?: boolean;
183: }) {
184:   const [open, setOpen] = useState(false);
185:   const [q, setQ] = useState('');
186:   const ref = useRef<HTMLDivElement>(null);
187:   useOutside(ref, () => setOpen(false), open);
188:   const cur = options.find(o => o.value === value);
189:   const list = options.filter(o => !q || o.label.includes(q));
190:   return (
191:     <div ref={ref} className="relative" style={{ width }}>
192:       <button type="button" disabled={disabled} onClick={() => setOpen(!open)}
193:         className={compact ? 'v-subcard rounded-full px-3.5 h-9 flex items-center gap-2 text-[12.5px] font-medium w-full hover:opacity-90 transition'
194:           : `v-input flex items-center gap-2 px-3.5 h-11 w-full text-[13px] ${open ? 'is-focus' : ''}`}
195:         style={{ color: 'var(--text-primary)' }}>
196:         {icon && <Icon name={icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
197:         <span className="truncate flex-1 text-start" style={{ color: cur ? 'var(--text-primary)' : 'var(--text-muted)' }}>
198:           {renderValue ? renderValue(cur) : cur ? cur.label : placeholder}
199:         </span>
200:         <Icon name="chevDown" className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-180' : ''}`} style={{ color: 'var(--text-muted)' }} />
201:       </button>
202:       {open && (
203:         <div className="v-pop absolute z-40 mt-1.5 w-full min-w-[220px] p-1.5 start-0">
204:           {searchable && (
205:             <div className="v-subcard rounded-full px-3 h-9 flex items-center gap-2 mb-1.5">
206:               <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
207:               <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="بحث..." className="bg-transparent outline-none text-[12.5px] w-full" style={{ color: 'var(--text-primary)' }} />
208:             </div>
209:           )}
210:           <div className="max-h-[240px] overflow-y-auto">
211:             {list.length === 0 && <div className="text-[12px] px-3 py-3 text-center" style={{ color: 'var(--text-muted)' }}>لا توجد نتائج</div>}
212:             {list.map(o => (
213:               <button type="button" key={String(o.value)} disabled={o.disabled}
214:                 onClick={() => { onChange(o.value); setOpen(false); setQ(''); }}
215:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start transition v-option ${o.value === value ? 'is-active' : ''} ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
216:                 {o.icon && <Icon name={o.icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
217:                 <span className="flex-1 truncate">{o.label}</span>
218:                 {o.meta && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.meta}</span>}
219:                 {o.value === value && <Icon name="check" className="w-3.5 h-3.5" style={{ color: 'var(--accent-orange)' }} strokeWidth={2.4} />}
220:               </button>
221:             ))}
222:           </div>
223:         </div>
224:       )}
225:     </div>
226:   );
227: }
