237: export function MultiSelect({ values, onChange, options, placeholder = 'اختر', disabled }: {
238:   values: (number | string)[];
239:   onChange: (v: (number | string)[]) => void;
240:   options: MultiSelectOption[];
241:   placeholder?: string;
242:   disabled?: boolean;
243: }) {
244:   const [open, setOpen] = useState(false);
245:   const [q, setQ] = useState('');
246:   const ref = useRef<HTMLDivElement>(null);
247:   useOutside(ref, () => setOpen(false), open);
248:   const toggle = (v: number | string) => {
249:     if (disabled || options.find(option => option.value === v)?.disabled) return;
250:     onChange(values.includes(v) ? values.filter(x => x !== v) : [...values, v]);
251:   };
252:   const list = options.filter(o => !q || o.label.includes(q));
253:   return (
254:     <div ref={ref} className="relative">
255:       <div onClick={() => !disabled && setOpen(true)}
256:         className={`v-input flex flex-wrap items-center gap-1.5 px-2 py-1.5 min-h-[44px] cursor-text ${open ? 'is-focus' : ''} ${disabled ? 'is-disabled' : ''}`}>
257:         {values.map(v => {
258:           const o = options.find(x => x.value === v); if (!o) return null;
259:           return (
260:             <span key={v} className="v-chip inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-semibold">
261:               {o.system && <Icon name="shieldCheck" className="w-3 h-3" style={{ color: 'var(--accent-orange)' }} />}
262:               {o.label}
263:               {!disabled && !o.disabled && (
264:                 <button type="button" onClick={e => { e.stopPropagation(); toggle(v); }} className="w-5 h-5 rounded-full flex items-center justify-center hover:opacity-70">
265:                   <Icon name="close" className="w-3 h-3" strokeWidth={2.4} />
266:                 </button>
267:               )}
268:             </span>
269:           );
270:         })}
271:         <input value={q} disabled={disabled} onChange={e => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)}
272:           placeholder={values.length ? '' : placeholder}
273:           className="bg-transparent outline-none text-[13px] flex-1 min-w-[80px] px-1.5 h-7" style={{ color: 'var(--text-primary)' }} />
274:       </div>
275:       {open && !disabled && (
276:         <div className="v-pop absolute z-40 mt-1.5 w-full p-1.5 max-h-[260px] overflow-y-auto">
277:           {list.map(o => {
278:             const on = values.includes(o.value);
279:             return (
280:               <button type="button" key={o.value} disabled={o.disabled} onClick={() => toggle(o.value)}
281:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start v-option ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
282:                 <Checkbox checked={on} />
283:                 <span className="flex-1">{o.label}</span>
284:                 {o.system && <Badge tone="orange">نظام</Badge>}
285:                 {o.note && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.note}</span>}
286:               </button>
287:             );
288:           })}
289:         </div>
290:       )}
291:     </div>
292:   );
293: }
