295: export function Checkbox({ checked, indeterminate, onChange, disabled, size = 18 }: {
296:   checked?: boolean;
297:   indeterminate?: boolean;
298:   onChange?: (val: boolean) => void;
299:   disabled?: boolean;
300:   size?: number;
301: }) {
302:   const on = checked || indeterminate;
303:   return (
304:     <span role="checkbox" aria-checked={indeterminate ? 'mixed' : !!checked}
305:       onClick={e => { if (onChange && !disabled) { e.stopPropagation(); onChange(!checked); } }}
306:       className={`inline-flex items-center justify-center shrink-0 transition-all duration-150 ${disabled ? 'opacity-50' : 'cursor-pointer'}`}
307:       style={{ width: size, height: size, borderRadius: 6, background: on ? 'var(--accent-orange)' : 'transparent', border: on ? '1.5px solid var(--accent-orange)' : '1.5px solid var(--checkbox-border)' }}>
308:       {checked && !indeterminate && <Icon name="check" className="w-3 h-3 text-white" strokeWidth={3} />}
309:       {indeterminate && <span className="w-2 h-[2px] rounded bg-white" />}
310:     </span>
311:   );
312: }
