494: // Toast System
495: interface ToastItem {
496:   id: number;
497:   text: string;
498:   tone: 'ok' | 'warn' | 'err';
499: }
500: 
501: export const toastBus = { fn: null as ((t: ToastItem) => void) | null };
502: 
503: export function toast(text: string, tone: 'ok' | 'warn' | 'err' = 'ok') {
504:   toastBus.fn && toastBus.fn({ text, tone, id: Date.now() });
505: }
506: 
507: export function ToastHost() {
508:   const [t, setT] = useState<ToastItem | null>(null);
509:   useEffect(() => {
510:     toastBus.fn = v => {
511:       setT(v);
512:       setTimeout(() => setT(c => (c && c.id === v.id ? null : c)), 2600);
513:     };
514:   }, []);
515:   return (
516:     <div className={`fixed top-6 inset-x-0 z-[70] flex justify-center pointer-events-none transition-all duration-300 ${t ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
517:       <div className="px-4 py-2.5 rounded-full shadow-lg text-[12.5px] font-medium flex items-center gap-2" style={{ background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }}>
518:         <span className="w-2 h-2 rounded-full" style={{ background: t?.tone === 'err' ? '#fb7185' : t?.tone === 'warn' ? '#f59e0b' : '#34d399' }} />
519:         <span>{t?.text}</span>
520:       </div>
521:     </div>
522:   );
523: }
