525: export function Drawer({ open, onClose, children, width = 520 }: { open: boolean; onClose: () => void; children: ReactNode; width?: number }) {
526:   useEffect(() => {
527:     if (!open) return;
528:     const h = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
529:     window.addEventListener('keydown', h);
530:     return () => window.removeEventListener('keydown', h);
531:   }, [open, onClose]);
532: 
533:   return (
534:     <div className={`fixed inset-0 z-50 ${open ? '' : 'pointer-events-none'}`}>
535:       <div onClick={onClose} className={`absolute inset-0 v-scrim transition-opacity duration-300 ${open ? 'opacity-100' : 'opacity-0'}`} />
536:       <div className={`absolute top-3 bottom-3 start-3 v-card v-drawer flex flex-col transition-transform duration-[420ms] ${open ? 'translate-x-0' : 'translate-x-[calc(100%+24px)]'}`}
537:         style={{ width: `min(${width}px, calc(100vw - 24px))`, transitionTimingFunction: 'cubic-bezier(0.22,1,0.36,1)' }}>
538:         {children}
539:       </div>
540:     </div>
541:   );
542: }
