 43: function KpiCard({ label, value, icon, foot, accent, delay, loading, bar }: KpiCardProps) {
 44:   return (
 45:     <div className={`${accent ? 'v-orange-earnings' : 'v-card'} rounded-[22px] p-5 flex flex-col justify-between min-h-[150px] stagger-item ${delay ?? ''}`}>
 46:       <div className="flex items-center justify-between">
 47:         <span className={`text-[13px] font-medium ${accent ? 'text-white/90' : ''}`} style={accent ? undefined : { color: 'var(--text-secondary)' }}>{label}</span>
 48:         <span className={`w-8 h-8 rounded-full flex items-center justify-center ${accent ? 'bg-white/15 text-white' : 'v-icon-well'}`}>
 49:           <Icon name={icon} className="w-4 h-4" />
 50:         </span>
 51:       </div>
 52:       {loading ? <Skeleton className="h-9 w-20 my-3 rounded-xl" style={accent ? { background: 'rgba(255,255,255,.25)' } : null} />
 53:         : <div className="font-display text-[34px] font-bold tracking-tight my-2 tabular-nums" style={accent ? undefined : { color: 'var(--text-primary)' }}>{value}</div>}
 54:       {bar != null && (
 55:         <div className="h-3 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5 mb-2">
 56:           <div className="h-full rounded-full transition-all duration-700" style={{ width: `${bar}%`, background: accent ? '#fff' : 'var(--accent-orange)' }} />
 57:           <div className={`h-full flex-1 rounded-full ${accent ? 'rewards-hatched-track' : 'spending-hatched-track'}`} />
 58:         </div>
 59:       )}
 60:       <div className={`text-[11.5px] ${accent ? 'text-white/80' : ''}`} style={accent ? undefined : { color: 'var(--text-muted)' }}>{foot}</div>
 61:     </div>
 62:   );
 63: }
