 65: export interface UsersScreenProps {
 66:   rolesLoading: boolean;
 67:   can: (p: string) => boolean;
 68:   onUsersChanged?: () => void;
 69:   roles: AdminRole[];
 70:   onNavigate?: (page: 'users' | 'roles' | 'settings', params?: Record<string, any>) => void;
 71:   initialRoleFilter?: number | 'all';
 72: }
 73: 
 74: export function UsersScreen({ rolesLoading, can, onUsersChanged, roles, onNavigate, initialRoleFilter = 'all' }: UsersScreenProps) {
 75:   const { meId, iAmSuper, myPerms } = useMe();
 76:   const branchesQ = useBranches();
 77:   const branches = branchesQ.data ?? [];
 78:   const [kpiTick, setKpiTick] = useState(0);
 79:   const [mutating, setMutating] = useState(false);
 80:   const [drawerErrors, setDrawerErrors] = useState<Record<string,string>>({});
 81:   const [q, setQ] = useState('');
 82:   const [branch, setBranch] = useState<string | number>('all');
 83:   const [role, setRole] = useState<string | number>(initialRoleFilter);
 84:   const [status, setStatus] = useState<'all' | 'active' | 'inactive'>('all');
 85:   const [page, setPage] = useState(1);
 86:   const perPage = 8;
 87:   const [drawer, setDrawer] = useState<{ mode: 'create' } | { mode: 'edit'; user: AdminUser; focusPwd?: boolean } | null>(null);
 88:   const [confirm, setConfirm] = useState<AdminUser | null>(null);
 89: 
 90:   useEffect(() => {
 91:     if (initialRoleFilter !== 'all') {
 92:       setRole(initialRoleFilter);
 93:     }
 94:   }, [initialRoleFilter]);
 95: 
 96:   const qDebounced = useDebounced(q);
 97:   const roleName = role === 'all' ? undefined : roles.find(r => r.id === Number(role))?.name;
 98:   const list = useApi(async signal => {
 99:     if (role !== 'all' && !roleName) return null;
100:     return adminApi.listUsers({page, per_page: perPage, search: qDebounced, role: roleName,
101:       branch_id: branch === 'all' ? undefined : branch === 'none' ? 'none' : Number(branch),
102:       is_active: status === 'all' ? undefined : status === 'active'}, signal);
103:   }, [page, qDebounced, roleName, role, branch, status, rolesLoading]);
104:   const kpi = useApi(async signal => {
105:     const [all, active, inactive] = await Promise.all([adminApi.countUsers({}, signal), adminApi.countUsers({is_active:true}, signal), adminApi.countUsers({is_active:false}, signal)]);
106:     return {all, active, inactive};
107:   }, [kpiTick]);
108:   useQueryError(list.error); useQueryError(kpi.error); useQueryError(branchesQ.error);
109:   const rows = (list.data?.data ?? []).map(u => toAdminUser(u, meId));
110:   const loading = list.loading || (role !== 'all' && rolesLoading);
111:   const pages = list.data?.meta.last_page ?? 1;
112:   const filteredTotal = list.data?.meta.total ?? 0;
113:   const total = kpi.data?.all ?? 0, active = kpi.data?.active ?? 0, inactive = kpi.data?.inactive ?? 0;
114:   const roleById = (id: number) => roles.find(r => r.id === id);
115:   useEffect(() => setPage(1), [qDebounced, branch, role, status]);
116:   useEffect(() => { if (!rolesLoading && role !== 'all' && !roles.some(r => r.id === Number(role))) setRole('all'); }, [rolesLoading, roles, role]);
117:   useEffect(() => setDrawerErrors({}), [drawer]);
118:   const refreshAll = () => { list.reload(); setKpiTick(t => t+1); onUsersChanged?.(); };
119:   const hasAccessAll = (u: AdminUser) => u.roles.some(rid => roleById(rid)?.perms.includes('inventory.all_branches'));
120:   const anyFilter = q || branch !== 'all' || role !== 'all' || status !== 'all';
121:   const clearFilters = () => { setQ(''); setBranch('all'); setRole('all'); setStatus('all'); };
122: 
123:   const saveUser = async (data: Partial<AdminUser> & { password?: string; current_password?: string }, mode: 'create' | 'edit') => {
124:     setDrawerErrors({});
125:     const original = drawer?.mode === 'edit' ? drawer.user : undefined;
126:     const rolesChanged = !original || (data.roles ?? []).length !== original.roles.length
127:       || (data.roles ?? []).some(id => !original.roles.includes(id));
128:     const roleNames = roleIdsToNames(data.roles ?? [], roles);
129:     if ((mode === 'create' || rolesChanged) && roleNames.length !== (data.roles ?? []).length) {
130:       toast('قائمة الأدوار قديمة، أعد التحميل ثم حاول مرة أخرى', 'err');
131:       refreshAll();
132:       return;
133:     }
134:     const result = await runMutation(() => {
135:       if (mode === 'create') return adminApi.createUser({name: data.name!.trim(), email: data.email!.trim(), phone: data.phone || null,
136:         password: data.password!, branch_id: data.branch_id ?? null, is_active: data.is_active ?? true, roles: roleNames});
137:       const body: UpdateUserBody = {expected_version: original?.version, name: data.name?.trim(), email: data.email?.trim(), phone: data.phone || null};
138:       if (branches.length && data.branch_id !== original?.branch_id) body.branch_id = data.branch_id ?? null;
139:       if (data.password) body.password = data.password;
140:       if (data.current_password) body.current_password = data.current_password;
141:       if (data.id !== meId) {
142:         if (rolesChanged) body.roles = roleNames;
143:         if (data.is_active !== original?.is_active) body.is_active = data.is_active;
144:       }
145:       return adminApi.updateUser(data.id!, body);
146:     });
147:     if (!result.ok) {
148:       if (result.error.status === 422) setDrawerErrors(mapFieldErrors(result.error.fields));
149:       if (result.error.status === 404) refreshAll();
150:       if (result.error.status === 409) { setDrawer(null); refreshAll(); }
151:       if (result.error.status !== 401) toast(result.error.message, 'err');
152:       return;
153:     }
154:     toast(mode === 'create' ? 'تم إنشاء المستخدم بنجاح' : data.password ? 'تم الحفظ وإنهاء جميع جلسات المستخدم' : 'تم حفظ التعديلات');
155:     setDrawer(null); refreshAll();
156:   };
157:   const doDeactivate = async (u: AdminUser) => {
158:     if (mutating) return;
159:     setMutating(true);
160:     const result = await runMutation(() => adminApi.deactivateUser(u.id, u.version!));
161:     setMutating(false);
162:     if (!result.ok) { if (result.error.status !== 401) toast(result.error.message,'err'); if (result.error.status === 404) refreshAll(); return; }
163:     setConfirm(null); toast('تم تعطيل حساب '+u.name+' وإنهاء جلساته','warn'); refreshAll();
164:   };
165:   const doActivate = async (u: AdminUser) => {
166:     if (mutating) return;
167:     setMutating(true);
168:     const result = await runMutation(() => adminApi.updateUser(u.id, {is_active:true, expected_version:u.version}));
169:     setMutating(false);
170:     if (!result.ok) { if (result.error.status !== 401) toast(result.error.message,'err'); return; }
171:     toast('تم تفعيل حساب '+u.name); refreshAll();
172:   };
173:   const mayUpdate = can('users.update') || can('users.manage');
174:   if (list.error && (!list.data || list.error.status === 403)) return <EmptyState icon="lock" title={list.error.message} action={<GhostButton onClick={list.reload}>إعادة المحاولة</GhostButton>} />;
175: 
176:   return (
177:     <section className="space-y-5" data-screen-label="01 Users">
178:       <PageHeader
179:         title="المستخدمون"
180:         subtitle="إدارة حسابات فريق العمل وتوزيع الفروع والأدوار."
181:         action={
182:           <div className="flex items-center gap-2.5 stagger-item stagger-2">
183:             {onNavigate && (
184:               <GhostButton icon="shield" onClick={() => onNavigate('roles')}>
185:                 الأدوار والصلاحيات
186:               </GhostButton>
187:             )}
188:             <PrimaryButton disabled={rolesLoading || !(can('users.create') || can('users.manage'))} icon="plus" onClick={() => setDrawer({ mode: 'create' })}>
189:               مستخدم جديد
190:             </PrimaryButton>
191:           </div>
192:         }
193:       />
194: 
195:       <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
196:         <KpiCard
197:           accent
198:           label="إجمالي المستخدمين"
199:           icon="users"
200:           value={total}
201:           loading={loading}
202:           delay="stagger-2"
203:           foot={
204:             <span className="flex items-center gap-2">
205:               <span>إجمالي الحسابات المسجلة</span>
206:             </span>
207:           }
208:         />
209:         <KpiCard
210:           label="المستخدمون النشطون"
211:           icon="userCheck"
212:           value={active}
213:           loading={loading}
214:           delay="stagger-3"
215:           bar={total ? Math.round((active / total) * 100) : 0}
216:           foot={
217:             <span className="flex items-center gap-2">
218:               <Badge tone="green">{total ? Math.round((active / total) * 100) : 0}%</Badge>
219:               من إجمالي الحسابات
220:             </span>
221:           }
222:         />
223:         <KpiCard
224:           label="الحسابات المعطلة"
225:           icon="userOff"
226:           value={inactive}
227:           loading={loading}
228:           delay="stagger-4"
229:           foot={
230:             <span className="flex items-center gap-2">
231:               <Badge tone="red">موقوفة</Badge>
232:               لا يمكنها تسجيل الدخول
233:             </span>
234:           }
235:         />
236:       </div>
237: 
238:       <div className="v-card p-5 stagger-item stagger-5">
239:         {/* Toolbar */}
240:         <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
241:           <div className="flex items-center gap-3">
242:             <h3 className="font-display text-[17px] font-semibold" style={{ color: 'var(--text-primary)' }}>فريق العمل</h3>
243:             <Badge tone="neutral">{filteredTotal} مستخدم</Badge>
244:           </div>
245:           <div className="flex flex-wrap items-center gap-2.5">
246:             <div className="v-subcard px-3.5 h-9 rounded-full flex items-center gap-2">
