297:                             {u.name}{isMe && <Badge tone="orange" className="!py-0 !px-2 !text-[10px]">أنت</Badge>}
298:                           </div>
299:                           <div className="text-[11.5px] mt-0.5" dir="ltr" style={{ color: 'var(--text-muted)', textAlign: 'right' }}>{u.email}</div>
300:                         </div>
301:                       </div>
302:                     </td>
303:                     <td className="px-3 tabular-nums" dir="ltr" style={{ color: u.phone ? 'var(--text-primary)' : 'var(--text-muted)', textAlign: 'right' }}>{u.phone || '—'}</td>
304:                     <td className="px-3">
