330:                       </div>
331:                     </td>
332:                     <td className="px-3">{u.is_active ? <Badge tone="green" dot>نشط</Badge> : <Badge tone="red" dot>معطل</Badge>}</td>
333:                     <td className="px-3 tabular-nums" style={{ color: 'var(--text-secondary)' }}>{fmtDate(u.created_at)}</td>
334:                     <td className="ps-3 pe-4">
