379:           <div className="w-12 h-12 rounded-2xl v-badge-red flex items-center justify-center mb-4"><Icon name="power" className="w-5 h-5" strokeWidth={2.2} /></div>
380:           <h3 className="font-display text-[18px] font-semibold" style={{ color: 'var(--text-primary)' }}>تعطيل حساب {confirm.name}؟</h3>
381:           <p className="text-[13px] mt-2 leading-relaxed" style={{ color: 'var(--text-secondary)' }}>
382:             لن يتمكن المستخدم من تسجيل الدخول، وسيتم <b style={{ color: 'var(--text-primary)' }}>إنهاء جميع جلساته الفعالة فوراً</b>. يمكنك إعادة تفعيل الحساب في أي وقت.
383:           </p>
384:           <div className="v-subcard p-3 mt-4 flex items-center gap-3">
385:             <Avatar name={confirm.name} id={confirm.id} size={32} />
386:             <div className="text-[12px]"><div className="font-semibold" style={{ color: 'var(--text-primary)' }}>{confirm.name}</div><div dir="ltr" style={{ color: 'var(--text-muted)', textAlign: 'right' }}>{confirm.email}</div></div>
387:           </div>
388:           <div className="grid grid-cols-2 gap-2.5 mt-5">
389:             <GhostButton onClick={() => setConfirm(null)}>إلغاء</GhostButton>
390:             <button type="button" disabled={mutating} onClick={() => doDeactivate(confirm)} className="h-10 rounded-full text-[13px] font-semibold text-white" style={{ background: 'var(--badge-red-text)' }}>تعطيل الحساب</button>
391:           </div>
392:         </>}
393:       </Modal>
394:     </section>
395:   );
396: }
