398: interface UserDrawerProps {
399:   state: { mode: 'create' } | { mode: 'edit'; user: AdminUser; focusPwd?: boolean } | null;
400:   onClose: () => void;
401:   onSave: (data: Partial<AdminUser> & { password?: string; current_password?: string }, mode: 'create' | 'edit') => Promise<void>;
402:   roles: AdminRole[];
403:   branches: AdminBranch[];
404:   meId?: number;
405:   myPerms: Set<string>;
406:   serverErrors: Record<string,string>;
407:   iAmSuper: boolean;
408: }
409: 
410: function UserDrawer({ state, onClose, onSave, roles, branches, meId, myPerms, serverErrors, iAmSuper }: UserDrawerProps) {
411:   const open = !!state;
412:   const mode = state?.mode ?? 'create';
413:   const blank = { name: '', email: '', password: '', current_password: '', phone: '', branch_id: null as number | null, roles: [] as number[], is_active: true };
414:   const [f, setF] = useState(blank);
415:   const [showPwd, setShowPwd] = useState(false);
416:   const [errors, setErrors] = useState<Record<string, string | undefined>>({});
417:   const [saving, setSaving] = useState(false);
418:   const [confirmSelf, setConfirmSelf] = useState(false);
419:   useEffect(() => { setErrors(serverErrors); }, [serverErrors]);
420:   const pwdRef = useRef<HTMLDivElement>(null);
421: 
422:   useEffect(() => {
423:     if (!state) return;
424:     setErrors({});
425:     setShowPwd(false);
426:     setSaving(false);
427:     if (state.mode === 'edit') {
428:       setF({ ...state.user, password: '', current_password: '', phone: state.user.phone || '' });
429:     } else {
430:       setF(blank);
431:     }
432:     if ('focusPwd' in state && state.focusPwd) {
433:       setTimeout(() => pwdRef.current?.querySelector('input')?.focus(), 450);
434:     }
435:   }, [state]);
436: 
437:   const isMe = mode === 'edit' && 'user' in (state || {}) && (state as any)?.user?.id === meId;
438:   const set = (k: string, v: any) => { setF(p => ({ ...p, [k]: v })); setErrors(e => ({ ...e, [k]: undefined })); };
439: 
440:   const validate = () => {
441:     const e: Record<string, string> = {};
442:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
443:     else if (f.name.length > 255) e.name = 'الحد الأقصى 255 حرفاً';
444:     if (!f.email.trim()) e.email = 'البريد الإلكتروني مطلوب';
445:     else if (!/^\S+@\S+\.\S+$/.test(f.email)) e.email = 'صيغة البريد غير صحيحة';
446:     if (mode === 'create' && !f.password) e.password = 'كلمة المرور مطلوبة عند الإنشاء';
447:     else if (f.password && (f.password.length < 12 || !/[A-Za-z\p{L}]/u.test(f.password) || !/\d/.test(f.password))) e.password = 'يجب ألا تقل عن 12 حرفًا وتحتوي على حروف وأرقام';
448:     if (isMe && state?.mode === 'edit' && (f.password || f.email.trim().toLowerCase() !== state.user.email.toLowerCase()) && !f.current_password) e.current_password = 'كلمة المرور الحالية مطلوبة لتغيير بيانات الدخول';
449:     if (f.phone && f.phone.length > 30) e.phone = 'الحد الأقصى 30 حرفاً';
450:     setErrors(e);
451:     return !Object.keys(e).length;
452:   };
453: 
454:   const persist = async () => {
455:     setSaving(true);
456:     try { await onSave({ ...f, phone: f.phone || null }, mode); } finally { setSaving(false); setConfirmSelf(false); }
457:   };
458:   const submit = async () => {
459:     if (saving || !validate()) return;
460:     if (isMe && state?.mode === 'edit' && (f.email !== state.user.email || f.password)) { setConfirmSelf(true); return; }
461:     await persist();
462:   };
463: 
464:   const pwdStrength = (() => {
465:     const p = f.password; if (!p) return 0;
466:     let s = 0; if (p.length >= 8) s++; if (/[A-Z]/.test(p) && /[a-z]/.test(p)) s++; if (/\d/.test(p)) s++; if (/[^A-Za-z0-9]/.test(p)) s++;
467:     return s;
468:   })();
469: 
470:   const roleOptions = roles.map(r => ({
471:     value: r.id, label: r.name, system: r.system,
472:     disabled: isMe || (!!r.system && !iAmSuper) || (!iAmSuper && r.perms.some(p => !myPerms.has(p))),
473:     note: !iAmSuper && r.perms.some(p => !myPerms.has(p)) ? 'لا تملك هذه الصلاحية لمنحها' : `${r.perms.length} صلاحية`,
474:   }));
475: 
476:   return (
477:     <>
478:     <Drawer open={open} onClose={onClose}>
479:       <div className="px-6 pt-5 pb-4 flex items-start justify-between gap-3" style={{ borderBottom: '1px solid var(--divider-color)' }}>
480:         <div className="flex items-center gap-3">
481:           {mode === 'edit' && f.name ? <Avatar name={f.name} id={(f as any).id || 0} size={44} /> :
482:             <div className="w-11 h-11 rounded-full flex items-center justify-center text-white" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }}><Icon name="plus" className="w-5 h-5" strokeWidth={2.4} /></div>}
483:           <div>
484:             <h2 className="font-display text-[19px] font-semibold" style={{ color: 'var(--text-primary)' }}>{mode === 'edit' ? 'تعديل المستخدم' : 'مستخدم جديد'}</h2>
485:             <p className="text-[12px] mt-0.5" style={{ color: 'var(--text-secondary)' }}>{mode === 'edit' ? 'حدّث البيانات والأدوار والفرع التابع له.' : 'أنشئ حساباً لموظف جديد وحدد صلاحياته.'}</p>
486:           </div>
487:         </div>
488:         <IconButton icon="close" onClick={onClose} />
489:       </div>
490: 
491:       <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
492:         {isMe && <Notice tone="info" title="أنت تعدّل حسابك الشخصي">لا يمكنك تغيير أدوارك أو حالة حسابك</Notice>}
493: 
494:         <div>
495:           <div className="text-[11px] font-semibold tracking-wide mb-3" style={{ color: 'var(--text-muted)' }}>البيانات الأساسية</div>
496:           <div className="space-y-4">
497:             <Field label="الاسم كامل" required error={errors.name}>
498:               <TextInput value={f.name} onChange={v => set('name', v)} placeholder="مثال: محمد أحمد علي" maxLength={255} error={errors.name} />
499:             </Field>
500:             <Field label="البريد الإلكتروني" required error={errors.email}>
501:               <TextInput value={f.email} onChange={v => set('email', v)} placeholder="name@company.com" dir="ltr" icon="mail" error={errors.email} />
502:             </Field>
503:             {isMe && state?.mode === 'edit' && (f.password || f.email.trim().toLowerCase() !== state.user.email.toLowerCase()) && (
504:               <Field label="كلمة المرور الحالية" required error={errors.current_password}>
505:                 <TextInput value={f.current_password} onChange={v => set('current_password', v)} type="password" dir="ltr" icon="lock" placeholder="أدخل كلمة المرور الحالية" error={errors.current_password} />
506:               </Field>
507:             )}
508:             <div ref={pwdRef}>
509:               <Field label="كلمة المرور" required={mode === 'create'} error={errors.password}
510:                 hint={mode === 'edit' ? 'اتركه فارغاً للإبقاء على كلمة المرور الحالية.' : '12 حرفًا على الأقل، مع حروف وأرقام.'}
511:                 aside={pwdStrength > 0 ? (
512:                   <span className="flex items-center gap-1">
513:                     {[1, 2, 3, 4].map(i => <span key={i} className="w-5 h-1 rounded-full" style={{ background: i <= pwdStrength ? (pwdStrength < 2 ? '#e11d48' : pwdStrength < 3 ? '#f59e0b' : '#16a34a') : 'var(--toggle-off-bg)' }} />)}
514:                   </span>
515:                 ) : undefined}>
516:                 <TextInput value={f.password} onChange={v => set('password', v)} type={showPwd ? 'text' : 'password'} dir="ltr" icon="lock"
517:                   placeholder={mode === 'edit' ? '••••••••' : 'أدخل كلمة مرور قوية'} error={errors.password}
518:                   suffix={<button type="button" onClick={() => setShowPwd(!showPwd)} style={{ color: 'var(--text-muted)' }} className="hover:opacity-70"><Icon name={showPwd ? 'eyeOff' : 'eye'} className="w-4 h-4" /></button>} />
519:               </Field>
520:               {mode === 'edit' && f.password && <Notice tone="warn" className="mt-2.5">سيتم إنهاء جميع جلسات هذا المستخدم فور حفظ كلمة المرور الجديدة.</Notice>}
521:             </div>
522:             <Field label="رقم الهاتف" hint="اختياري" error={errors.phone}>
523:               <TextInput value={f.phone} onChange={v => set('phone', v)} placeholder="+20 1xx xxx xxxx" dir="ltr" icon="phone" maxLength={30} error={errors.phone} />
524:             </Field>
525:           </div>
526:         </div>
527: 
528:         <div className="h-px" style={{ background: 'var(--divider-color)' }} />
529: 
530:         <div>
531:           <div className="text-[11px] font-semibold tracking-wide mb-3" style={{ color: 'var(--text-muted)' }}>الفرع والصلاحيات</div>
532:           <div className="space-y-4">
533:             <Field error={errors.branch_id} label="الفرع">
534:               <Select disabled={!branches.length} searchable icon="building" value={f.branch_id} onChange={v => set('branch_id', v)} placeholder="اختر الفرع"
535:                 options={[{ value: null, label: 'بدون فرع', icon: 'ban' }, ...(branches.length ? branches : state?.mode === 'edit' && state.user.branch_id ? [{id:state.user.branch_id, name:state.user.branch_name ?? 'الفرع الحالي'}] : []).map(b => ({ value: b.id, label: b.name }))]} />
536:             </Field>
537:             <Field error={errors.roles} label="الأدوار" hint={!iAmSuper ? 'إسناد دور Super Admin متاح فقط لمن يمتلك هذا الدور.' : 'يمكن إسناد أكثر من دور للمستخدم.'}>
538:               <MultiSelect values={f.roles} onChange={v => set('roles', v as number[])} options={roleOptions} placeholder="اختر دوراً أو أكثر" disabled={isMe || !roles.length} />
539:             </Field>
540:           </div>
541:         </div>
542: 
543:         <div className={`v-subcard p-4 flex items-center justify-between gap-4 ${isMe ? 'opacity-60' : ''}`}>
544:           <div className="flex items-center gap-3">
545:             <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.is_active ? 'v-badge-green' : 'v-badge-red'}`}><Icon name={f.is_active ? 'userCheck' : 'userOff'} className="w-4 h-4" /></span>
546:             <div>
547:               <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{f.is_active ? 'حساب نشط' : 'موقوف مؤقتاً'}</div>
548:               <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>{f.is_active ? 'يمكنه تسجيل الدخول واستخدام النظام' : 'سيتم إنهاء جلساته ومنعه من الدخول'}</div>
549:             </div>
550:           </div>
551:           <Toggle on={f.is_active} onChange={v => set('is_active', v)} disabled={isMe} />
552:         </div>
553:       </div>
554: 
555:       <div className="px-6 py-4 flex items-center gap-2.5" style={{ borderTop: '1px solid var(--divider-color)' }}>
556:         <AccentButton icon="check" onClick={submit} loading={saving} className="flex-1">{mode === 'edit' ? 'حفظ التعديلات' : 'إنشاء المستخدم'}</AccentButton>
557:         <GhostButton onClick={onClose}>إلغاء</GhostButton>
558:       </div>
559:     </Drawer>
560:     <Modal open={confirmSelf} onClose={() => setConfirmSelf(false)}>
561:       <h3>سيتم تسجيل خروجك من جميع الأجهزة</h3>
562:       <div className="flex gap-3 mt-4"><AccentButton loading={saving} onClick={persist}>تأكيد الحفظ</AccentButton><GhostButton onClick={() => setConfirmSelf(false)}>إلغاء</GhostButton></div>
563:     </Modal>
564:     </>
565:   );
