 21:   const original = draft?.isNew ? { name: '', perms: [] } : sel;
 22:   const isDirty = draft && original && (draft.isNew || draft.name !== original.name || draft.perms.length !== original.perms.length || draft.perms.some(p => !original.perms.includes(p)));
 23:   const changeCount = draft && original && !draft.isNew
 24:     ? draft.perms.filter(p => !original.perms.includes(p)).length + original.perms.filter(p => !draft.perms.includes(p)).length + (draft.name !== original.name ? 1 : 0)
 25:     : null;
