 29:   const toggleGroup = (g, on) => { if (isSystem) return; const keys = g.perms.map(p => p[0]); setDraft(d => ({ ...d, perms: on ? [...new Set([...d.perms, ...keys])] : d.perms.filter(x => !keys.includes(x)) })); };
 30:   const toggleOpen = m => setOpenGroups(s => { const n = new Set(s); n.has(m) ? n.delete(m) : n.add(m); return n; });
