 88:                 <div className="flex-1"><div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{draft.name || 'دور جديد'}</div><div className="text-[11px]" style={{ color: 'var(--text-muted)' }}>مسودة غير محفوظة</div></div>
