 28: function SettingsScreen() {
 29:   const [loading, setLoading] = useState(true);
 30:   const [server, setServer] = useState(() => clone(INITIAL_SETTINGS));
 31:   const [s, setS] = useState(() => clone(INITIAL_SETTINGS));
 32:   const [tab, setTab] = useState(() => localStorage.getItem('vx-settings-tab') || 'company');
 33:   const [saving, setSaving] = useState(false);
 34:   const [conflict, setConflict] = useState(false);
 35:   const [simConflict, setSimConflict] = useState(false);
 36: 
 37:   useEffect(() => { const t = setTimeout(() => setLoading(false), 850); return () => clearTimeout(t); }, []);
 38:   useEffect(() => localStorage.setItem('vx-settings-tab', tab), [tab]);
 39: 
 40:   const set = (group, key, val) => setS(p => ({ ...p, [group]: { ...p[group], [key]: val } }));
 41:   const setNum = (doc, key, val) => setS(p => ({ ...p, numbering: { ...p.numbering, [doc]: { ...p.numbering[doc], [key]: val } } }));
 42: 
 43:   // compute changed fields (flat)
 44:   const diffs = useMemo(() => {
 45:     const out = [];
 46:     Object.keys(s).forEach(g => Object.keys(s[g]).forEach(k => {
 47:       if (JSON.stringify(s[g][k]) !== JSON.stringify(server[g][k])) out.push([g, k]);
 48:     }));
 49:     return out;
 50:   }, [s, server]);
 51:   const dirtyGroups = new Set(diffs.map(d => d[0]));
 52:   const isDirty = diffs.length > 0;
 53: 
 54:   const save = async () => {
 55:     setSaving(true); await sleep(800); setSaving(false);
 56:     if (simConflict) { setConflict(true); toast('تعذّر الحفظ: تم تعديل الإعدادات من مستخدم آخر', 'err'); return; }
 57:     setServer(clone(s)); toast(`تم حفظ ${diffs.length} إعداد بنجاح`);
 58:   };
 59:   const reload = async () => {
 60:     setLoading(true); setConflict(false); setSimConflict(false);
 61:     await sleep(700);
 62:     const fresh = clone(server); fresh.tax.default_tax_rate = 14; fresh.company.company_phone = '+20 2 2735 8899';
 63:     setServer(fresh); setS(clone(fresh)); setLoading(false);
 64:     toast('تم تحميل أحدث نسخة من الخادم');
 65:   };
 66: 
 67:   return (
 68:     <section className="space-y-5 pb-20" data-screen-label="03 Settings">
 69:       <PageHeader title="الإعدادات العامة" subtitle="هوية المؤسسة، الضرائب، الترقيم التلقائي للمستندات، سياسات الإرجاع وسير عمل المشتريات."
 70:         action={
 71:           <label className="flex items-center gap-2 text-[11.5px] font-medium v-subcard rounded-full ps-3 pe-1.5 h-9 stagger-item stagger-2" style={{ color: 'var(--text-secondary)' }} title="محاكاة لحالة التعارض 409 عند الحفظ">
 72:             محاكاة تعارض 409
 73:             <Toggle size="sm" on={simConflict} onChange={setSimConflict} />
 74:           </label>
 75:         } />
 76: 
 77:       {conflict && (
 78:         <div className="v-conflict rounded-[22px] p-4 flex flex-wrap items-center gap-4 v-pop-in">
 79:           <span className="w-10 h-10 rounded-full flex items-center justify-center bg-white/15 shrink-0"><Icon name="alert" className="w-5 h-5" strokeWidth={2.2} /></span>
 80:           <div className="flex-1 min-w-[240px]">
 81:             <div className="font-semibold text-[14px]">تعارض في البيانات (409)</div>
 82:             <div className="text-[12.5px] opacity-85 mt-0.5">قام مدير آخر بتعديل الإعدادات أثناء عملك. أعد تحميل أحدث نسخة من الخادم قبل الحفظ لتجنب الكتابة فوق تعديلاته.</div>
 83:           </div>
 84:           <div className="flex items-center gap-2">
 85:             <button onClick={() => setConflict(false)} className="h-9 px-4 rounded-full text-[12.5px] font-semibold hover:bg-white/10">لاحقاً</button>
 86:             <button onClick={reload} className="h-9 px-4 rounded-full text-[12.5px] font-semibold bg-white flex items-center gap-1.5" style={{ color: '#c2410c' }}><Icon name="refresh" className="w-3.5 h-3.5" strokeWidth={2.2} />إعادة التحميل</button>
 87:           </div>
 88:         </div>
 89:       )}
 90: 
 91:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
 92:         {/* Tabs rail */}
 93:         <nav className="lg:col-span-3 v-card p-2 stagger-item stagger-2 lg:sticky lg:top-5">
 94:           {SETTINGS_TABS.map((t, i) => {
 95:             const active = tab === t.key;
 96:             return (
 97:               <button key={t.key} onClick={() => setTab(t.key)}
 98:                 className={`w-full flex items-center gap-3 p-3 rounded-2xl text-start transition ${active ? 'v-tab-active' : 'v-tab'}`}>
 99:                 <span className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${active ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={t.icon} className="w-4 h-4" /></span>
100:                 <div className="flex-1 min-w-0">
101:                   <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{t.label}</div>
102:                   <div className="text-[11px] truncate" style={{ color: 'var(--text-muted)' }}>{t.desc}</div>
103:                 </div>
104:                 {dirtyGroups.has(t.key) && <span className="w-2 h-2 rounded-full shrink-0" style={{ background: 'var(--accent-orange)' }} title="تعديلات غير محفوظة" />}
105:               </button>
106:             );
107:           })}
108:         </nav>
109: 
110:         <div className="lg:col-span-9 stagger-item stagger-3" key={tab}>
111:           {loading ? <SettingsSkeleton /> : (
112:             <div className="v-tab-in space-y-5">
113:               {tab === 'company' && <CompanyTab v={s.company} set={(k, v) => set('company', k, v)} />}
114:               {tab === 'tax' && <TaxTab v={s.tax} set={(k, v) => set('tax', k, v)} />}
115:               {tab === 'numbering' && <NumberingTab v={s.numbering} server={server.numbering} setNum={setNum} />}
116:               {tab === 'orders' && <ReturnsTab v={s.orders} set={(k, v) => set('orders', k, v)} />}
117:               {tab === 'purchases' && <PurchasesTab v={s.purchases} set={(k, v) => set('purchases', k, v)} />}
118:             </div>
119:           )}
120:         </div>
121:       </div>
122: 
123:       <StickyBar show={isDirty} onSave={save} onReset={() => setS(clone(server))} saving={saving} count={diffs.length} />
124:     </section>
125:   );
126: }
