200: /* ---------- Tab 2: Tax ---------- */
201: function TaxTab({ v, set }) {
202:   const [sample, setSample] = useState(1000);
203:   const rate = Number(v.default_tax_rate) || 0;
204:   const on = v.tax_enabled;
205:   let net, tax, gross;
206:   if (!on) { net = sample; tax = 0; gross = sample; }
207:   else if (v.prices_include_tax) { gross = sample; net = sample / (1 + rate / 100); tax = gross - net; }
208:   else { net = sample; tax = sample * rate / 100; gross = net + tax; }
209:   const rateErr = rate < 0 || rate > 100;
210: 
211:   return (
212:     <div className="grid grid-cols-1 xl:grid-cols-5 gap-5 items-start">
213:       <SectionCard title="ضريبة القيمة المضافة" subtitle="إعدادات الضريبة المطبّقة على الفواتير الإلكترونية." className="xl:col-span-3">
