235:           <div className="flex flex-wrap gap-1.5 mt-2.5">
236:             {[5, 10, 14, 15].map(r => (
237:               <button key={r} onClick={() => set('default_tax_rate', r)} className="px-3 h-7 rounded-full text-[11.5px] font-semibold transition"
238:                 style={rate === r ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-subcard)', color: 'var(--text-secondary)' }}>{r}%</button>
239:             ))}
240:           </div>
241: 
242:           <div className="mt-6">
243:             <div className="text-[12.5px] font-semibold mb-2.5" style={{ color: 'var(--text-primary)' }}>طريقة احتساب الأسعار</div>
244:             <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
245:               {[
246:                 { val: true, title: 'الأسعار شاملة الضريبة', en: 'Tax-Inclusive', desc: 'السعر المعروض هو ما يدفعه العميل، وتُستخرج الضريبة منه.' },
247:                 { val: false, title: 'الأسعار غير شاملة الضريبة', en: 'Tax-Exclusive', desc: 'تُضاف الضريبة فوق السعر المعروض عند إصدار الفاتورة.' },
