274:         <div className="v-subcard p-4 mt-4">
275:           <div className="text-[11.5px] font-medium" style={{ color: 'var(--text-secondary)' }}>سعر المنتج المُدخل</div>
276:           <div className="flex items-baseline gap-2 mt-1">
277:             <input type="number" value={sample} onChange={e => setSample(Math.max(0, Number(e.target.value)))} dir="ltr"
278:               className="bg-transparent outline-none font-display text-[30px] font-bold w-full tabular-nums" style={{ color: 'var(--text-primary)' }} />
279:             <span className="text-[13px] font-semibold shrink-0" style={{ color: 'var(--text-muted)' }}>ج.م</span>
280:           </div>
281:           <input type="range" min="0" max="10000" step="50" value={sample} onChange={e => setSample(Number(e.target.value))} className="v-slider mt-2"
282:             style={{ background: `linear-gradient(to left, #e0491f ${sample / 100}%, var(--toggle-off-bg) ${sample / 100}%)` }} />
283:         </div>
284: 
285:         <div className="mt-4 space-y-0 v-divide">
286:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>الصافي قبل الضريبة</span><span className="font-semibold tabular-nums" style={{ color: 'var(--text-primary)' }}>{fmtMoney(net)}</span></div>
287:           <div className="flex items-center justify-between py-3 text-[13px]"><span style={{ color: 'var(--text-secondary)' }}>قيمة الضريبة ({on ? rate : 0}%)</span><span className="font-semibold tabular-nums" style={{ color: 'var(--accent-orange)' }}>+ {fmtMoney(tax)}</span></div>
288:         </div>
289: 
290:         <div className="v-orange-earnings rounded-[18px] p-4 mt-2">
291:           <div className="text-[12px] text-white/85">الإجمالي المستحق</div>
292:           <div className="font-display text-[28px] font-bold tabular-nums mt-0.5">{fmtMoney(gross)} <span className="text-[14px] font-medium text-white/80">ج.م</span></div>
293:           <div className="mt-3 h-3 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5 bg-white/10">
294:             <div className="h-full rounded-full bg-white transition-all duration-300" style={{ width: `${gross ? net / gross * 100 : 100}%` }} />
295:             <div className="h-full flex-1 rounded-full rewards-hatched-track" />
296:           </div>
297:           <div className="flex justify-between text-[10.5px] text-white/80 mt-1.5"><span>صافي</span><span>ضريبة</span></div>
298:         </div>
299:       </div>
300:     </div>
301:   );
302: }
