304: /* ---------- Tab 3: Numbering ---------- */
305: function NumberingTab({ v, server, setNum }) {
306:   const [q, setQ] = useState('');
307:   const docs = DOC_TYPES.filter(d => !q || d.label.includes(q) || d.key.includes(q.toLowerCase()) || v[d.key].prefix.toLowerCase().includes(q.toLowerCase()));
308:   return (
309:     <SectionCard title="ترقيم المستندات" subtitle="حدد البادئة وطول الرقم والرقم التسلسلي التالي لكل نوع من وثائق النظام."
310:       aside={<div className="v-subcard px-3.5 h-9 rounded-full flex items-center gap-2 shrink-0">
311:         <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
312:         <input value={q} onChange={e => setQ(e.target.value)} placeholder="بحث عن مستند" className="bg-transparent text-[12.5px] outline-none w-32" style={{ color: 'var(--text-primary)' }} />
313:       </div>}>
314:       {docs.length === 0 && <EmptyState title="لا توجد مستندات مطابقة" text="جرّب البحث باسم المستند أو البادئة مثل INV-." />}
315:       <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
316:         {docs.map(d => {
317:           const n = v[d.key];
318:           const pad = Math.min(20, Math.max(1, Number(n.padding) || 1));
319:           const preview = `${n.prefix}${String(n.next_number || 0).padStart(pad, '0')}`;
320:           const changed = JSON.stringify(n) !== JSON.stringify(server[d.key]);
321:           const padErr = n.padding < 1 || n.padding > 20;
322:           const lower = Number(n.next_number) < server[d.key].next_number;
323:           return (
324:             <div key={d.key} className={`v-subcard p-4 v-doc ${changed ? 'is-changed' : ''}`}>
325:               <div className="flex items-center justify-between gap-2 mb-3.5">
326:                 <div className="flex items-center gap-2.5 min-w-0">
327:                   <span className="w-8 h-8 rounded-[10px] flex items-center justify-center shrink-0" style={{ background: 'var(--bg-card)', color: 'var(--text-secondary)' }}><Icon name="doc" className="w-4 h-4" /></span>
328:                   <div className="min-w-0">
329:                     <div className="text-[13px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>{d.label}</div>
330:                     <div className="text-[10.5px] font-mono" style={{ color: 'var(--text-muted)' }}>{d.key}</div>
331:                   </div>
332:                 </div>
333:                 <span dir="ltr" className="v-preview-badge font-mono text-[12px] font-bold px-3 py-1.5 rounded-full truncate max-w-[55%]" title="المستند التالي">{preview}</span>
334:               </div>
335:               <div className="grid grid-cols-[1.1fr_.8fr_1.2fr] gap-2">
336:                 <div>
337:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>البادئة</div>
338:                   <input dir="ltr" value={n.prefix} onChange={e => setNum(d.key, 'prefix', e.target.value.toUpperCase())} className="v-mini-input w-full font-mono" />
339:                 </div>
340:                 <div>
341:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>حشو الأصفار</div>
342:                   <div className={`v-mini-input flex items-center !px-1 ${padErr ? 'is-error' : ''}`}>
343:                     <button onClick={() => setNum(d.key, 'padding', Math.max(1, pad - 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>−</button>
344:                     <input dir="ltr" type="number" min="1" max="20" value={n.padding} onChange={e => setNum(d.key, 'padding', Number(e.target.value))} className="bg-transparent outline-none w-full text-center tabular-nums" />
345:                     <button onClick={() => setNum(d.key, 'padding', Math.min(20, pad + 1))} className="w-6 h-6 rounded-md flex items-center justify-center hover:opacity-60 text-[14px] font-bold" style={{ color: 'var(--text-secondary)' }}>+</button>
346:                   </div>
347:                 </div>
348:                 <div>
349:                   <div className="text-[10.5px] font-medium mb-1" style={{ color: 'var(--text-muted)' }}>الرقم التالي</div>
350:                   <input dir="ltr" type="number" min="1" value={n.next_number} onChange={e => setNum(d.key, 'next_number', Number(e.target.value))} className={`v-mini-input w-full tabular-nums ${lower ? 'is-warn' : ''}`} />
351:                 </div>
352:               </div>
353:               {lower && <div className="text-[10.5px] mt-2 flex items-center gap-1 font-medium" style={{ color: '#b45309' }}><Icon name="alert" className="w-3 h-3" />رقم أقل من الحالي ({server[d.key].next_number}) قد يسبب تكراراً</div>}
354:             </div>
355:           );
356:         })}
357:       </div>
358:     </SectionCard>
359:   );
360: }
