362: /* ---------- Tab 4: Returns ---------- */
363: function ReturnsTab({ v, set }) {
364:   const d = v.return_window_days;
365:   const mode = d === 0 ? 'off' : d === -1 ? 'unlimited' : 'days';
366:   const [lastDays, setLastDays] = useState(d > 0 ? d : 14);
367:   useEffect(() => { if (d > 0) setLastDays(d); }, [d]);
368:   const cards = [
369:     { key: 'off', title: 'متوقف', desc: 'لا يُسمح بإرجاع المنتجات نهائياً.', icon: 'ban', val: 0, code: '0' },
370:     { key: 'days', title: 'خلال عدد أيام', desc: 'الإرجاع متاح لمدة محددة من تاريخ تسليم الطلب.', icon: 'calendar', val: lastDays, code: 'n' },
371:     { key: 'unlimited', title: 'غير محدود', desc: 'الإرجاع متاح في أي وقت دون قيود زمنية.', icon: 'infinity', val: -1, code: '-1' },
372:   ];
373:   // timeline example
374:   const delivered = new Date(); const deadline = new Date(delivered.getTime() + lastDays * 864e5);
375:   return (
376:     <SectionCard title="سياسة المبيعات والمرتجعات" subtitle="حدد المهلة المسموح خلالها للعميل بإرجاع المنتجات بعد التسليم.">
377:       <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
378:         {cards.map(c => {
379:           const act = mode === c.key;
380:           return (
381:             <button key={c.key} onClick={() => set('return_window_days', c.val)} className={`v-choice rounded-[18px] p-4 text-start ${act ? 'is-on' : ''}`}>
382:               <div className="flex items-center justify-between">
383:                 <span className={`w-10 h-10 rounded-xl flex items-center justify-center ${act ? 'text-white v-accent-btn' : 'v-icon-well'}`}><Icon name={c.icon} className="w-[18px] h-[18px]" /></span>
384:                 <span className="v-radio"><span /></span>
385:               </div>
386:               <div className="text-[14px] font-semibold mt-3" style={{ color: 'var(--text-primary)' }}>{c.title}</div>
387:               <div className="text-[11.5px] mt-1 leading-relaxed" style={{ color: 'var(--text-muted)' }}>{c.desc}</div>
388:               <div className="text-[10.5px] font-mono mt-2" style={{ color: 'var(--text-muted)' }}>return_window_days = {c.key === 'days' ? lastDays : c.code}</div>
389:             </button>
390:           );
391:         })}
392:       </div>
393: 
394:       <div className="v-collapse" style={{ gridTemplateRows: mode === 'days' ? '1fr' : '0fr' }}>
395:         <div className="overflow-hidden">
396:           <div className="v-subcard p-5 mt-4">
397:             <div className="flex flex-wrap items-center justify-between gap-4">
398:               <div>
399:                 <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>عدد الأيام المسموح بها</div>
400:                 <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>تُحتسب من تاريخ تسليم الطلب للعميل</div>
401:               </div>
402:               <div className="flex items-center gap-2">
403:                 {[7, 14, 30, 60].map(n => (
404:                   <button key={n} onClick={() => set('return_window_days', n)} className="px-3.5 h-8 rounded-full text-[12px] font-semibold transition"
405:                     style={d === n ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { background: 'var(--bg-card)', color: 'var(--text-secondary)' }}>{n} يوم</button>
406:                 ))}
407:                 <div className="flex items-center gap-1.5 h-8 ps-3 pe-1 rounded-full" style={{ background: 'var(--bg-card)' }}>
408:                   <input type="number" min="1" max="365" value={d > 0 ? d : lastDays} onChange={e => set('return_window_days', Math.max(1, Number(e.target.value)))} dir="ltr"
409:                     className="bg-transparent outline-none w-10 text-center text-[13px] font-bold tabular-nums" style={{ color: 'var(--text-primary)' }} />
410:                   <span className="text-[11.5px] pe-2" style={{ color: 'var(--text-muted)' }}>يوم</span>
411:                 </div>
412:               </div>
413:             </div>
414:             {/* Timeline */}
415:             <div className="mt-6">
416:               <div className="h-3.5 w-full rounded-full overflow-hidden flex items-center gap-1 p-0.5">
417:                 <div className="h-full rounded-full transition-all duration-500" style={{ width: `${Math.min(100, lastDays / 90 * 100)}%`, background: 'var(--accent-orange)' }} />
418:                 <div className="h-full flex-1 rounded-full spending-hatched-track" />
419:               </div>
420:               <div className="flex justify-between mt-2.5 text-[11.5px]">
421:                 <span style={{ color: 'var(--text-secondary)' }}><b style={{ color: 'var(--text-primary)' }}>التسليم</b> · {fmtDate(delivered)}</span>
422:                 <span style={{ color: 'var(--text-secondary)' }}>آخر موعد للإرجاع · <b style={{ color: 'var(--accent-orange)' }}>{fmtDate(deadline)}</b></span>
423:               </div>
424:             </div>
425:           </div>
426:         </div>
427:       </div>
428: 
429:       {mode === 'off' && <Notice tone="warn" className="mt-4" title="الإرجاع متوقف">لن يتمكن الموظفون من إنشاء مرتجعات مبيعات جديدة من أي فرع.</Notice>}
430:       {mode === 'unlimited' && <Notice tone="info" className="mt-4">يمكن إرجاع أي طلب مُسلّم دون قيود زمنية، مع خضوع المرتجع لدورة الاعتماد المعتادة.</Notice>}
431:     </SectionCard>
432:   );
433: }
