 60: function Icon({ name, className = 'w-4 h-4', strokeWidth = 1.9, style }) {
 61:   return (
 62:     <svg className={className} style={style} fill="none" stroke="currentColor" strokeWidth={strokeWidth} viewBox="0 0 24 24">
 63:       {ICON_PATHS[name]}
 64:     </svg>
 65:   );
 66: }
