 68: function Toggle({ on, onChange, disabled, size = 'md' }) {
 69:   const w = size === 'sm' ? 'w-9 h-5' : 'w-11 h-6';
 70:   const k = size === 'sm' ? 'w-4 h-4' : 'w-5 h-5';
 71:   return (
 72:     <button type="button" role="switch" aria-checked={on} disabled={disabled}
 73:       onClick={() => !disabled && onChange(!on)}
 74:       className={`${w} rounded-full p-0.5 transition-colors duration-200 flex items-center shrink-0 ${disabled ? 'opacity-45 cursor-not-allowed' : ''}`}
 75:       style={{ background: on ? 'var(--accent-orange)' : 'var(--toggle-off-bg)', justifyContent: on ? 'flex-start' : 'flex-end' }}>
 76:       <span className={`${k} rounded-full bg-white shadow-sm block`} />
 77:     </button>
 78:   );
 79: }
