 81: function Badge({ tone = 'neutral', children, className = '', dot }) {
 82:   const tones = {
 83:     green: 'v-badge-green', red: 'v-badge-red',
 84:     orange: 'v-badge-orange', neutral: 'v-badge-neutral', dark: 'v-badge-dark', outline: 'v-badge-outline',
 85:   };
 86:   return (
 87:     <span className={`${tones[tone]} inline-flex items-center gap-1.5 px-2.5 py-[3px] rounded-full text-[11px] font-semibold whitespace-nowrap ${className}`}>
 88:       {dot && <span className="w-1.5 h-1.5 rounded-full" style={{ background: 'currentColor' }} />}
 89:       {children}
 90:     </span>
 91:   );
 92: }
