 94: const AVATAR_TONES = [
 95:   ['#fde8e1', '#c2410c'], ['#e8e4f7', '#5b4bb7'], ['#dcf3ea', '#11795a'], ['#fbeccc', '#a1620a'],
 96:   ['#e2eefb', '#2d6aa8'], ['#f7e1ec', '#b03a72'],
 97: ];
 98: function Avatar({ name, id = 0, size = 36, ring }) {
 99:   const parts = name.trim().split(/\s+/);
100:   const initials = (parts[0]?.[0] || '') + (parts[1]?.[0] || '');
101:   const [bg, fg] = AVATAR_TONES[id % AVATAR_TONES.length];
102:   return (
103:     <div className="rounded-full flex items-center justify-center font-semibold shrink-0 avatar-chip"
104:       style={{ width: size, height: size, background: bg, color: fg, fontSize: size * 0.36, boxShadow: ring ? '0 0 0 2px var(--bg-card), 0 0 0 3.5px var(--accent-orange)' : undefined }}>
105:       {initials}
106:     </div>
107:   );
108: }
