110: // Field wrapper
111: function Field({ label, hint, error, required, children, className = '', aside }) {
112:   return (
113:     <label className={`block ${className}`}>
114:       <div className="flex items-center justify-between mb-1.5">
115:         <span className="text-[12.5px] font-semibold" style={{ color: 'var(--text-primary)' }}>
116:           {label}{required && <span style={{ color: 'var(--accent-orange)' }}> *</span>}
117:         </span>
118:         {aside}
119:       </div>
120:       {children}
121:       {error ? <div className="text-[11.5px] mt-1.5 font-medium" style={{ color: 'var(--badge-red-text)' }}>{error}</div>
122:         : hint ? <div className="text-[11.5px] mt-1.5" style={{ color: 'var(--text-muted)' }}>{hint}</div> : null}
123:     </label>
124:   );
125: }
