127: function TextInput({ value, onChange, placeholder, icon, dir, type = 'text', disabled, error, suffix, className = '', ...rest }) {
128:   return (
129:     <div className={`v-input flex items-center gap-2 px-3.5 h-11 ${error ? 'is-error' : ''} ${disabled ? 'is-disabled' : ''} ${className}`}>
130:       {icon && <Icon name={icon} className="w-4 h-4 shrink-0" style={{ color: 'var(--text-muted)' }} />}
131:       <input type={type} value={value ?? ''} disabled={disabled} dir={dir} placeholder={placeholder}
132:         onChange={e => onChange(e.target.value)}
133:         className="bg-transparent outline-none w-full text-[13px] h-full" style={{ color: 'var(--text-primary)' }} {...rest} />
134:       {suffix}
135:     </div>
136:   );
137: }
