139: // Close on outside click
140: function useOutside(ref, cb, active) {
141:   useEffect(() => {
142:     if (!active) return;
143:     const h = e => { if (ref.current && !ref.current.contains(e.target)) cb(); };
144:     document.addEventListener('mousedown', h);
145:     return () => document.removeEventListener('mousedown', h);
146:   }, [active]);
147: }
148: 
149: // Searchable select (single) — options: [{value,label,icon?,meta?}]
150: function Select({ value, onChange, options, placeholder = 'اختر', searchable, icon, compact, renderValue, width }) {
151:   const [open, setOpen] = useState(false);
152:   const [q, setQ] = useState('');
153:   const ref = useRef(null);
154:   useOutside(ref, () => setOpen(false), open);
155:   const cur = options.find(o => o.value === value);
156:   const list = options.filter(o => !q || o.label.includes(q));
157:   return (
158:     <div ref={ref} className="relative" style={{ width }}>
159:       <button type="button" onClick={() => setOpen(!open)}
160:         className={compact ? 'v-subcard rounded-full px-3.5 h-9 flex items-center gap-2 text-[12.5px] font-medium w-full hover:opacity-90 transition'
161:           : `v-input flex items-center gap-2 px-3.5 h-11 w-full text-[13px] ${open ? 'is-focus' : ''}`}
162:         style={{ color: 'var(--text-primary)' }}>
163:         {icon && <Icon name={icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
164:         <span className="truncate flex-1 text-start" style={{ color: cur ? 'var(--text-primary)' : 'var(--text-muted)' }}>
165:           {renderValue ? renderValue(cur) : cur ? cur.label : placeholder}
166:         </span>
167:         <Icon name="chevDown" className={`w-3.5 h-3.5 shrink-0 transition-transform ${open ? 'rotate-180' : ''}`} style={{ color: 'var(--text-muted)' }} />
168:       </button>
169:       {open && (
170:         <div className="v-pop absolute z-40 mt-1.5 w-full min-w-[220px] p-1.5 start-0">
171:           {searchable && (
172:             <div className="v-subcard rounded-full px-3 h-9 flex items-center gap-2 mb-1.5">
173:               <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
174:               <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="بحث..." className="bg-transparent outline-none text-[12.5px] w-full" style={{ color: 'var(--text-primary)' }} />
175:             </div>
176:           )}
177:           <div className="max-h-[240px] overflow-y-auto">
178:             {list.length === 0 && <div className="text-[12px] px-3 py-3 text-center" style={{ color: 'var(--text-muted)' }}>لا توجد نتائج</div>}
179:             {list.map(o => (
180:               <button type="button" key={String(o.value)} disabled={o.disabled}
181:                 onClick={() => { onChange(o.value); setOpen(false); setQ(''); }}
182:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start transition v-option ${o.value === value ? 'is-active' : ''} ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
183:                 {o.icon && <Icon name={o.icon} className="w-3.5 h-3.5 shrink-0" style={{ color: 'var(--text-muted)' }} />}
184:                 <span className="flex-1 truncate">{o.label}</span>
185:                 {o.meta && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.meta}</span>}
186:                 {o.value === value && <Icon name="check" className="w-3.5 h-3.5" style={{ color: 'var(--accent-orange)' }} strokeWidth={2.4} />}
187:               </button>
188:             ))}
189:           </div>
190:         </div>
191:       )}
192:     </div>
193:   );
194: }
195: 
196: // Multi-select chips
197: function MultiSelect({ values, onChange, options, placeholder = 'اختر', disabled }) {
198:   const [open, setOpen] = useState(false);
199:   const [q, setQ] = useState('');
200:   const ref = useRef(null);
201:   useOutside(ref, () => setOpen(false), open);
202:   const toggle = v => onChange(values.includes(v) ? values.filter(x => x !== v) : [...values, v]);
203:   const list = options.filter(o => !q || o.label.includes(q));
204:   return (
205:     <div ref={ref} className="relative">
206:       <div onClick={() => !disabled && setOpen(true)}
207:         className={`v-input flex flex-wrap items-center gap-1.5 px-2 py-1.5 min-h-[44px] cursor-text ${open ? 'is-focus' : ''} ${disabled ? 'is-disabled' : ''}`}>
208:         {values.map(v => {
209:           const o = options.find(x => x.value === v); if (!o) return null;
210:           return (
211:             <span key={v} className="v-chip inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-semibold">
212:               {o.system && <Icon name="shieldCheck" className="w-3 h-3" style={{ color: 'var(--accent-orange)' }} />}
213:               {o.label}
214:               {!disabled && (
215:                 <button type="button" onClick={e => { e.stopPropagation(); toggle(v); }} className="w-5 h-5 rounded-full flex items-center justify-center hover:opacity-70">
216:                   <Icon name="close" className="w-3 h-3" strokeWidth={2.4} />
217:                 </button>
218:               )}
219:             </span>
220:           );
221:         })}
222:         <input value={q} disabled={disabled} onChange={e => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)}
223:           placeholder={values.length ? '' : placeholder}
224:           className="bg-transparent outline-none text-[13px] flex-1 min-w-[80px] px-1.5 h-7" style={{ color: 'var(--text-primary)' }} />
225:       </div>
226:       {open && !disabled && (
227:         <div className="v-pop absolute z-40 mt-1.5 w-full p-1.5 max-h-[260px] overflow-y-auto">
228:           {list.map(o => {
229:             const on = values.includes(o.value);
230:             return (
231:               <button type="button" key={o.value} disabled={o.disabled} onClick={() => toggle(o.value)}
232:                 className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-[12.5px] text-start v-option ${o.disabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
233:                 <Checkbox checked={on} />
234:                 <span className="flex-1">{o.label}</span>
235:                 {o.system && <Badge tone="orange">نظام</Badge>}
236:                 {o.note && <span className="text-[11px]" style={{ color: 'var(--text-muted)' }}>{o.note}</span>}
237:               </button>
238:             );
239:           })}
240:         </div>
241:       )}
242:     </div>
243:   );
244: }
245: 
246: function Checkbox({ checked, indeterminate, onChange, disabled, size = 18 }) {
247:   const on = checked || indeterminate;
248:   return (
249:     <span role="checkbox" aria-checked={indeterminate ? 'mixed' : !!checked}
250:       onClick={e => { if (onChange && !disabled) { e.stopPropagation(); onChange(!checked); } }}
251:       className={`inline-flex items-center justify-center shrink-0 transition-all duration-150 ${disabled ? 'opacity-50' : 'cursor-pointer'}`}
252:       style={{ width: size, height: size, borderRadius: 6, background: on ? 'var(--accent-orange)' : 'transparent', border: on ? '1.5px solid var(--accent-orange)' : '1.5px solid var(--checkbox-border)' }}>
253:       {checked && !indeterminate && <Icon name="check" className="w-3 h-3 text-white" strokeWidth={3} />}
254:       {indeterminate && <span className="w-2 h-[2px] rounded bg-white" />}
255:     </span>
256:   );
257: }
