259: // Segmented control
260: function Segmented({ value, onChange, options, size = 'md' }) {
261:   return (
262:     <div className="v-subcard inline-flex p-1 rounded-full">
263:       {options.map(o => {
264:         const active = o.value === value;
265:         return (
266:           <button type="button" key={String(o.value)} onClick={() => onChange(o.value)}
267:             className={`${size === 'sm' ? 'px-3 py-1 text-[11.5px]' : 'px-3.5 py-1.5 text-[12px]'} rounded-full font-semibold transition-all ${active ? 'shadow-xs' : ''}`}
268:             style={{ background: active ? 'var(--seg-active-bg)' : 'transparent', color: active ? 'var(--text-primary)' : 'var(--text-secondary)' }}>
269:             {o.label}{o.count != null && <span className="ms-1.5 opacity-60 font-medium">{o.count}</span>}
270:           </button>
271:         );
272:       })}
273:     </div>
274:   );
275: }
