385: // Toast
386: const toastBus = { fn: null };
387: function toast(text, tone = 'ok') { toastBus.fn && toastBus.fn({ text, tone, id: Date.now() }); }
388: function ToastHost() {
389:   const [t, setT] = useState(null);
390:   useEffect(() => { toastBus.fn = v => { setT(v); setTimeout(() => setT(c => (c && c.id === v.id ? null : c)), 2600); }; }, []);
391:   return (
392:     <div className={`fixed top-6 inset-x-0 z-[70] flex justify-center pointer-events-none transition-all duration-300 ${t ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
393:       <div className="px-4 py-2.5 rounded-full shadow-lg text-[12.5px] font-medium flex items-center gap-2" style={{ background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }}>
394:         <span className="w-2 h-2 rounded-full" style={{ background: t?.tone === 'err' ? '#fb7185' : t?.tone === 'warn' ? '#f59e0b' : '#34d399' }} />
395:         <span>{t?.text}</span>
396:       </div>
397:     </div>
398:   );
399: }
