401: // Modal / Drawer
402: function Drawer({ open, onClose, children, width = 520 }) {
403:   useEffect(() => {
404:     if (!open) return;
405:     const h = e => e.key === 'Escape' && onClose();
406:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
407:   }, [open]);
408:   return (
409:     <div className={`fixed inset-0 z-50 ${open ? '' : 'pointer-events-none'}`}>
410:       <div onClick={onClose} className={`absolute inset-0 v-scrim transition-opacity duration-300 ${open ? 'opacity-100' : 'opacity-0'}`} />
411:       <div className={`absolute top-3 bottom-3 start-3 v-card v-drawer flex flex-col transition-transform duration-[420ms] ${open ? 'translate-x-0' : 'translate-x-[calc(100%+24px)]'}`}
412:         style={{ width: `min(${width}px, calc(100vw - 24px))`, transitionTimingFunction: 'cubic-bezier(0.22,1,0.36,1)' }}>
413:         {children}
414:       </div>
415:     </div>
416:   );
