 26: function UsersScreen({ users, setUsers, roles }) {
 27:   const [loading, setLoading] = useState(true);
 28:   const [q, setQ] = useState('');
 29:   const [branch, setBranch] = useState('all');
 30:   const [role, setRole] = useState('all');
 31:   const [status, setStatus] = useState('all');
 32:   const [page, setPage] = useState(1);
 33:   const perPage = 8;
 34:   const [drawer, setDrawer] = useState(null); // null | {mode:'create'} | {mode:'edit', user}
 35:   const [confirm, setConfirm] = useState(null);
 36: 
 37:   useEffect(() => { const t = setTimeout(() => setLoading(false), 900); return () => clearTimeout(t); }, []);
 38:   useEffect(() => setPage(1), [q, branch, role, status]);
 39: 
 40:   const me = users.find(u => u.id === CURRENT_USER_ID);
 41:   const iAmSuper = me && me.roles.includes(1);
 42:   const roleById = id => roles.find(r => r.id === id);
 43:   const branchById = id => ADMIN_BRANCHES.find(b => b.id === id);
 44: 
 45:   const filtered = users.filter(u => {
 46:     if (q && !(u.name.includes(q) || u.email.toLowerCase().includes(q.toLowerCase()))) return false;
 47:     if (branch === 'none' && u.branch_id !== null) return false;
 48:     if (typeof branch === 'number' && u.branch_id !== branch) return false;
 49:     if (role !== 'all' && !u.roles.includes(role)) return false;
 50:     if (status === 'active' && !u.is_active) return false;
 51:     if (status === 'inactive' && u.is_active) return false;
 52:     return true;
 53:   });
 54:   const pages = Math.max(1, Math.ceil(filtered.length / perPage));
 55:   const rows = filtered.slice((page - 1) * perPage, page * perPage);
 56: 
 57:   const total = users.length, active = users.filter(u => u.is_active).length, inactive = total - active;
 58:   const hasAccessAll = u => u.roles.some(rid => roleById(rid)?.perms.includes('branches.access_all'));
 59:   const anyFilter = q || branch !== 'all' || role !== 'all' || status !== 'all';
 60:   const clearFilters = () => { setQ(''); setBranch('all'); setRole('all'); setStatus('all'); };
 61: 
 62:   const saveUser = (data, mode) => {
 63:     if (mode === 'create') {
 64:       const id = Math.max(...users.map(u => u.id)) + 1;
 65:       setUsers([{ ...data, id, created_at: new Date().toISOString().slice(0, 10) }, ...users]);
 66:       toast('تم إنشاء المستخدم بنجاح');
 67:     } else {
 68:       setUsers(users.map(u => u.id === data.id ? { ...u, ...data } : u));
 69:       toast(data.password ? 'تم الحفظ وإنهاء جميع جلسات المستخدم' : 'تم حفظ التعديلات');
 70:     }
 71:     setDrawer(null);
 72:   };
 73: 
 74:   const doDeactivate = u => {
 75:     setUsers(users.map(x => x.id === u.id ? { ...x, is_active: false } : x));
 76:     setConfirm(null);
 77:     toast(`تم تعطيل حساب ${u.name} وإنهاء جلساته`, 'warn');
 78:   };
 79:   const doActivate = u => {
 80:     setUsers(users.map(x => x.id === u.id ? { ...x, is_active: true } : x));
 81:     toast(`تم تفعيل حساب ${u.name}`);
 82:   };
 83: 
 84:   return (
 85:     <section className="space-y-5" data-screen-label="01 Users">
 86:       <PageHeader title="المستخدمون" subtitle="إدارة حسابات فريق العمل وتوزيع الفروع والأدوار."
 87:         action={<PrimaryButton icon="plus" onClick={() => setDrawer({ mode: 'create' })} className="stagger-item stagger-2">مستخدم جديد</PrimaryButton>} />
 88: 
 89:       <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
 90:         <KpiCard accent label="إجمالي المستخدمين" icon="users" value={total} loading={loading} delay="stagger-2"
 91:           foot={<span className="flex items-center gap-2"><span className="px-2 py-0.5 rounded-full text-[10.5px] font-semibold bg-white/20 text-white">+3</span>خلال آخر 30 يوماً</span>} />
 92:         <KpiCard label="المستخدمون النشطون" icon="userCheck" value={active} loading={loading} delay="stagger-3" bar={total ? Math.round(active / total * 100) : 0}
 93:           foot={<span className="flex items-center gap-2"><Badge tone="green">{total ? Math.round(active / total * 100) : 0}%</Badge> من إجمالي الحسابات</span>} />
 94:         <KpiCard label="الحسابات المعطلة" icon="userOff" value={inactive} loading={loading} delay="stagger-4"
 95:           foot={<span className="flex items-center gap-2"><Badge tone="red">موقوفة</Badge> لا يمكنها تسجيل الدخول</span>} />
 96:       </div>
 97: 
 98:       <div className="v-card p-5 stagger-item stagger-5">
 99:         {/* Toolbar */}
100:         <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
101:           <div className="flex items-center gap-3">
102:             <h3 className="font-display text-[17px] font-semibold" style={{ color: 'var(--text-primary)' }}>فريق العمل</h3>
103:             <Badge tone="neutral">{filtered.length} مستخدم</Badge>
104:           </div>
105:           <div className="flex flex-wrap items-center gap-2.5">
106:             <div className="v-subcard px-3.5 h-9 rounded-full flex items-center gap-2">
107:               <Icon name="search" className="w-3.5 h-3.5" style={{ color: 'var(--text-muted)' }} />
108:               <input value={q} onChange={e => setQ(e.target.value)} placeholder="بحث بالاسم أو البريد" className="bg-transparent text-[12.5px] outline-none w-40 sm:w-48" style={{ color: 'var(--text-primary)' }} />
109:               {q && <button onClick={() => setQ('')} style={{ color: 'var(--text-muted)' }}><Icon name="close" className="w-3 h-3" strokeWidth={2.4} /></button>}
110:             </div>
111:             <Select compact icon="building" width={170} value={branch} onChange={setBranch} searchable
112:               options={[{ value: 'all', label: 'كل الفروع' }, { value: 'none', label: 'بدون فرع' }, ...ADMIN_BRANCHES.map(b => ({ value: b.id, label: b.name }))]} />
113:             <Select compact icon="shield" width={150} value={role} onChange={setRole}
114:               options={[{ value: 'all', label: 'كل الأدوار' }, ...roles.map(r => ({ value: r.id, label: r.name }))]} />
115:             <Segmented size="sm" value={status} onChange={setStatus}
116:               options={[{ value: 'all', label: 'الكل' }, { value: 'active', label: 'نشط' }, { value: 'inactive', label: 'معطل' }]} />
117:           </div>
118:         </div>
119: 
120:         <div className="overflow-x-auto">
121:           <table className="w-full text-start border-collapse min-w-[900px]">
122:             <thead>
123:               <tr className="v-subcard text-[11.5px] font-medium" style={{ color: 'var(--text-secondary)' }}>
124:                 <th className="py-2.5 ps-4 pe-3 text-start rounded-s-xl font-medium">المستخدم</th>
125:                 <th className="py-2.5 px-3 text-start font-medium">الهاتف</th>
126:                 <th className="py-2.5 px-3 text-start font-medium">الفرع</th>
127:                 <th className="py-2.5 px-3 text-start font-medium">الأدوار</th>
128:                 <th className="py-2.5 px-3 text-start font-medium">الحالة</th>
129:                 <th className="py-2.5 px-3 text-start font-medium">تاريخ الإنشاء</th>
130:                 <th className="py-2.5 ps-3 pe-4 text-end rounded-e-xl font-medium">الإجراءات</th>
131:               </tr>
132:             </thead>
133:             <tbody className="text-[12.5px] v-divide">
134:               {loading && Array.from({ length: 6 }).map((_, i) => (
135:                 <tr key={i}>
136:                   <td className="py-3.5 ps-4 pe-3"><div className="flex items-center gap-3"><Skeleton className="w-9 h-9 rounded-full" /><div className="space-y-1.5"><Skeleton className="h-3 w-28 rounded" /><Skeleton className="h-2.5 w-36 rounded" /></div></div></td>
137:                   <td className="px-3"><Skeleton className="h-3 w-24 rounded" /></td>
138:                   <td className="px-3"><Skeleton className="h-6 w-28 rounded-full" /></td>
139:                   <td className="px-3"><Skeleton className="h-6 w-20 rounded-full" /></td>
140:                   <td className="px-3"><Skeleton className="h-6 w-14 rounded-full" /></td>
141:                   <td className="px-3"><Skeleton className="h-3 w-20 rounded" /></td>
142:                   <td className="pe-4"><Skeleton className="h-8 w-[72px] rounded-full ms-auto" /></td>
143:                 </tr>
144:               ))}
145:               {!loading && rows.map(u => {
146:                 const b = branchById(u.branch_id);
147:                 const isMe = u.id === CURRENT_USER_ID;
148:                 return (
149:                   <tr key={u.id} className={`v-row transition-colors ${!u.is_active ? 'is-muted' : ''}`}>
150:                     <td className="py-3 ps-4 pe-3">
151:                       <div className="flex items-center gap-3">
152:                         <Avatar name={u.name} id={u.id} ring={isMe} />
153:                         <div className="min-w-0">
154:                           <div className="font-semibold text-[13px] flex items-center gap-1.5" style={{ color: 'var(--text-primary)' }}>
