158:                         </div>
159:                       </div>
160:                     </td>
161:                     <td className="px-3 tabular-nums" dir="ltr" style={{ color: u.phone ? 'var(--text-primary)' : 'var(--text-muted)', textAlign: 'right' }}>{u.phone || '—'}</td>
162:                     <td className="px-3">
163:                       {hasAccessAll(u) ? <Badge tone="dark"><Icon name="globe" className="w-3 h-3" />كل الفروع</Badge>
164:                         : b ? <Badge tone="outline"><Icon name="building" className="w-3 h-3 opacity-60" />{b.name}</Badge>
165:                         : <span className="text-[12px]" style={{ color: 'var(--text-muted)' }}>بدون فرع</span>}
166:                     </td>
