169:                         {u.roles.length === 0 && <span className="text-[12px]" style={{ color: 'var(--text-muted)' }}>لا يوجد دور</span>}
170:                         {u.roles.map(rid => { const r = roleById(rid); return r && (
171:                           <Badge key={rid} tone={r.system ? 'orange' : 'neutral'}>{r.system && <Icon name="shieldCheck" className="w-3 h-3" />}{r.name}</Badge>
172:                         ); })}
173:                       </div>
174:                     </td>
