201:         {/* Pagination */}
202:         {!loading && filtered.length > 0 && (
203:           <div className="flex items-center justify-between mt-4 pt-4" style={{ borderTop: '1px solid var(--divider-color)' }}>
204:             <span className="text-[12px]" style={{ color: 'var(--text-muted)' }}>
205:               عرض {(page - 1) * perPage + 1}–{Math.min(page * perPage, filtered.length)} من {filtered.length}
206:             </span>
207:             <div className="flex items-center gap-1.5">
208:               <IconButton icon="chevRight" onClick={() => setPage(Math.max(1, page - 1))} />
209:               {Array.from({ length: pages }).map((_, i) => (
210:                 <button key={i} onClick={() => setPage(i + 1)} className="w-8 h-8 rounded-full text-[12px] font-semibold transition"
211:                   style={page === i + 1 ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' } : { color: 'var(--text-secondary)' }}>{i + 1}</button>
212:               ))}
213:               <IconButton icon="chevLeft" onClick={() => setPage(Math.min(pages, page + 1))} />
214:             </div>
215:           </div>
216:         )}
217:       </div>
218: 
219:       <UserDrawer state={drawer} onClose={() => setDrawer(null)} onSave={saveUser} roles={roles} users={users} iAmSuper={iAmSuper} />
220: 
221:       <Modal open={!!confirm} onClose={() => setConfirm(null)}>
222:         {confirm && <>
223:           <div className="w-12 h-12 rounded-2xl v-badge-red flex items-center justify-center mb-4"><Icon name="power" className="w-5 h-5" strokeWidth={2.2} /></div>
224:           <h3 className="font-display text-[18px] font-semibold" style={{ color: 'var(--text-primary)' }}>تعطيل حساب {confirm.name}؟</h3>
225:           <p className="text-[13px] mt-2 leading-relaxed" style={{ color: 'var(--text-secondary)' }}>
226:             لن يتمكن المستخدم من تسجيل الدخول، وسيتم <b style={{ color: 'var(--text-primary)' }}>إنهاء جميع جلساته الفعالة فوراً</b>. يمكنك إعادة تفعيل الحساب في أي وقت.
227:           </p>
228:           <div className="v-subcard p-3 mt-4 flex items-center gap-3">
229:             <Avatar name={confirm.name} id={confirm.id} size={32} />
230:             <div className="text-[12px]"><div className="font-semibold" style={{ color: 'var(--text-primary)' }}>{confirm.name}</div><div dir="ltr" style={{ color: 'var(--text-muted)', textAlign: 'right' }}>{confirm.email}</div></div>
231:           </div>
232:           <div className="grid grid-cols-2 gap-2.5 mt-5">
233:             <GhostButton onClick={() => setConfirm(null)}>إلغاء</GhostButton>
234:             <button onClick={() => doDeactivate(confirm)} className="h-10 rounded-full text-[13px] font-semibold text-white" style={{ background: 'var(--badge-red-text)' }}>تعطيل الحساب</button>
235:           </div>
236:         </>}
237:       </Modal>
238:     </section>
239:   );
240: }
