242: function UserDrawer({ state, onClose, onSave, roles, users, iAmSuper }) {
243:   const open = !!state;
244:   const mode = state?.mode;
245:   const blank = { name: '', email: '', password: '', phone: '', branch_id: null, roles: [], is_active: true };
246:   const [f, setF] = useState(blank);
247:   const [showPwd, setShowPwd] = useState(false);
248:   const [errors, setErrors] = useState({});
249:   const [saving, setSaving] = useState(false);
250:   const pwdRef = useRef(null);
251: 
252:   useEffect(() => {
253:     if (!state) return;
254:     setErrors({}); setShowPwd(false); setSaving(false);
255:     setF(state.mode === 'edit' ? { ...state.user, password: '', phone: state.user.phone || '' } : blank);
256:     if (state.focusPwd) setTimeout(() => pwdRef.current?.querySelector('input')?.focus(), 450);
257:   }, [state]);
258: 
259:   const isMe = mode === 'edit' && f.id === CURRENT_USER_ID;
260:   const set = (k, v) => { setF(p => ({ ...p, [k]: v })); setErrors(e => ({ ...e, [k]: undefined })); };
261: 
262:   const validate = () => {
263:     const e = {};
264:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
265:     else if (f.name.length > 255) e.name = 'الحد الأقصى 255 حرفاً';
266:     if (!f.email.trim()) e.email = 'البريد الإلكتروني مطلوب';
267:     else if (!/^\S+@\S+\.\S+$/.test(f.email)) e.email = 'صيغة البريد غير صحيحة';
268:     else if (users.some(u => u.email.toLowerCase() === f.email.toLowerCase() && u.id !== f.id)) e.email = 'هذا البريد مستخدم بالفعل في النظام';
269:     if (mode === 'create' && !f.password) e.password = 'كلمة المرور مطلوبة عند الإنشاء';
270:     else if (f.password && f.password.length < 8) e.password = 'يجب ألا تقل عن 8 أحرف';
271:     if (f.phone && f.phone.length > 30) e.phone = 'الحد الأقصى 30 حرفاً';
272:     setErrors(e);
273:     return !Object.keys(e).length;
274:   };
275: 
276:   const submit = async () => {
277:     if (!validate()) return;
278:     setSaving(true); await sleep(700);
279:     onSave({ ...f, phone: f.phone || null }, mode);
280:   };
281: 
282:   const pwdStrength = (() => {
283:     const p = f.password; if (!p) return 0;
284:     let s = 0; if (p.length >= 8) s++; if (/[A-Z]/.test(p) && /[a-z]/.test(p)) s++; if (/\d/.test(p)) s++; if (/[^A-Za-z0-9]/.test(p)) s++;
285:     return s;
286:   })();
287: 
288:   const roleOptions = roles.map(r => ({
289:     value: r.id, label: r.name, system: r.system,
290:     disabled: r.system && !iAmSuper,
291:     note: `${r.perms.length} صلاحية`,
292:   }));
293: 
294:   return (
295:     <Drawer open={open} onClose={onClose}>
296:       <div className="px-6 pt-5 pb-4 flex items-start justify-between gap-3" style={{ borderBottom: '1px solid var(--divider-color)' }}>
297:         <div className="flex items-center gap-3">
298:           {mode === 'edit' && f.name ? <Avatar name={f.name} id={f.id || 0} size={44} /> :
299:             <div className="w-11 h-11 rounded-full flex items-center justify-center text-white" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }}><Icon name="plus" className="w-5 h-5" strokeWidth={2.4} /></div>}
300:           <div>
301:             <h2 className="font-display text-[19px] font-semibold" style={{ color: 'var(--text-primary)' }}>{mode === 'edit' ? 'تعديل المستخدم' : 'مستخدم جديد'}</h2>
302:             <p className="text-[12px] mt-0.5" style={{ color: 'var(--text-secondary)' }}>{mode === 'edit' ? 'حدّث البيانات والأدوار والفرع التابع له.' : 'أنشئ حساباً لموظف جديد وحدد صلاحياته.'}</p>
303:           </div>
304:         </div>
305:         <IconButton icon="close" onClick={onClose} />
306:       </div>
307: 
308:       <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
309:         {isMe && <Notice tone="info" title="أنت تعدّل حسابك الشخصي">لا يمكنك تعطيل حسابك أو إزالة أدوارك بنفسك.</Notice>}
310: 
311:         <div>
312:           <div className="text-[11px] font-semibold tracking-wide mb-3" style={{ color: 'var(--text-muted)' }}>البيانات الأساسية</div>
313:           <div className="space-y-4">
314:             <Field label="الاسم كامل" required error={errors.name}>
315:               <TextInput value={f.name} onChange={v => set('name', v)} placeholder="مثال: محمد أحمد علي" maxLength={255} error={errors.name} />
316:             </Field>
317:             <Field label="البريد الإلكتروني" required error={errors.email}>
318:               <TextInput value={f.email} onChange={v => set('email', v)} placeholder="name@company.com" dir="ltr" icon="mail" error={errors.email} />
319:             </Field>
320:             <div ref={pwdRef}>
321:               <Field label="كلمة المرور" required={mode === 'create'} error={errors.password}
322:                 hint={mode === 'edit' ? 'اتركه فارغاً للإبقاء على كلمة المرور الحالية.' : '8 أحرف على الأقل.'}
323:                 aside={pwdStrength > 0 && (
324:                   <span className="flex items-center gap-1">
325:                     {[1, 2, 3, 4].map(i => <span key={i} className="w-5 h-1 rounded-full" style={{ background: i <= pwdStrength ? (pwdStrength < 2 ? '#e11d48' : pwdStrength < 3 ? '#f59e0b' : '#16a34a') : 'var(--toggle-off-bg)' }} />)}
326:                   </span>
327:                 )}>
328:                 <TextInput value={f.password} onChange={v => set('password', v)} type={showPwd ? 'text' : 'password'} dir="ltr" icon="lock"
329:                   placeholder={mode === 'edit' ? '••••••••' : 'أدخل كلمة مرور قوية'} error={errors.password}
330:                   suffix={<button type="button" onClick={() => setShowPwd(!showPwd)} style={{ color: 'var(--text-muted)' }} className="hover:opacity-70"><Icon name={showPwd ? 'eyeOff' : 'eye'} className="w-4 h-4" /></button>} />
331:               </Field>
332:               {mode === 'edit' && f.password && <Notice tone="warn" className="mt-2.5">سيتم إنهاء جميع جلسات هذا المستخدم فور حفظ كلمة المرور الجديدة.</Notice>}
333:             </div>
334:             <Field label="رقم الهاتف" hint="اختياري" error={errors.phone}>
335:               <TextInput value={f.phone} onChange={v => set('phone', v)} placeholder="+20 1xx xxx xxxx" dir="ltr" icon="phone" maxLength={30} error={errors.phone} />
336:             </Field>
337:           </div>
338:         </div>
339: 
340:         <div className="h-px" style={{ background: 'var(--divider-color)' }} />
341: 
342:         <div>
343:           <div className="text-[11px] font-semibold tracking-wide mb-3" style={{ color: 'var(--text-muted)' }}>الفرع والصلاحيات</div>
344:           <div className="space-y-4">
345:             <Field label="الفرع">
346:               <Select searchable icon="building" value={f.branch_id} onChange={v => set('branch_id', v)} placeholder="اختر الفرع"
347:                 options={[{ value: null, label: 'بدون فرع', icon: 'ban' }, ...ADMIN_BRANCHES.map(b => ({ value: b.id, label: b.name }))]} />
348:             </Field>
349:             <Field label="الأدوار" hint={!iAmSuper ? 'إسناد دور Super Admin متاح فقط لمن يمتلك هذا الدور.' : 'يمكن إسناد أكثر من دور للمستخدم.'}>
350:               <MultiSelect values={f.roles} onChange={v => set('roles', v)} options={roleOptions} placeholder="اختر دوراً أو أكثر" disabled={isMe} />
351:             </Field>
352:           </div>
353:         </div>
354: 
355:         <div className={`v-subcard p-4 flex items-center justify-between gap-4 ${isMe ? 'opacity-60' : ''}`}>
356:           <div className="flex items-center gap-3">
357:             <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.is_active ? 'v-badge-green' : 'v-badge-red'}`}><Icon name={f.is_active ? 'userCheck' : 'userOff'} className="w-4 h-4" /></span>
358:             <div>
359:               <div className="text-[13px] font-semibold" style={{ color: 'var(--text-primary)' }}>{f.is_active ? 'حساب نشط' : 'موقوف مؤقتاً'}</div>
360:               <div className="text-[11.5px]" style={{ color: 'var(--text-muted)' }}>{f.is_active ? 'يمكنه تسجيل الدخول واستخدام النظام' : 'سيتم إنهاء جلساته ومنعه من الدخول'}</div>
361:             </div>
362:           </div>
363:           <Toggle on={f.is_active} onChange={v => set('is_active', v)} disabled={isMe} />
364:         </div>
365:       </div>
366: 
367:       <div className="px-6 py-4 flex items-center gap-2.5" style={{ borderTop: '1px solid var(--divider-color)' }}>
368:         <AccentButton icon="check" onClick={submit} loading={saving} className="flex-1">{mode === 'edit' ? 'حفظ التعديلات' : 'إنشاء المستخدم'}</AccentButton>
369:         <GhostButton onClick={onClose}>إلغاء</GhostButton>
370:       </div>
371:     </Drawer>
372:   );
373: }
