139:     public function update(UpdateUserRequest $request, User $user): UserResource|JsonResponse
140:     {
141:         abort_if($user->is_system, 404);
142:         $validated = $request->validated();
143:         $currentUser = $request->user('staff');
144:         $isCurrentUser = $currentUser instanceof User && $currentUser->is($user);
145: 
146:         if ($isCurrentUser && (array_key_exists('roles', $validated) || array_key_exists('is_active', $validated))) {
147:             return response()->json([
148:                 'message' => 'لا يمكنك تغيير أدوارك أو حالة تنشيط حسابك الحالي.',
149:             ], 403);
150:         }
151: 
152:         $roles = $validated['roles'] ?? null;
153:         $userAttributes = Arr::except($validated, ['roles', 'current_password', 'expected_version']);
154: 
155:         if (array_key_exists('password', $userAttributes) && $userAttributes['password'] === null) {
156:             unset($userAttributes['password']);
157:         }
158: 
159:         $verifiedPasswordHash = null;
160:         $credentialChange = $isCurrentUser && (isset($userAttributes['password'])
161:             || (isset($userAttributes['email']) && $userAttributes['email'] !== $user->email));
162:         $passwordLimitKey = 'staff:current-password:'.$user->id;
163:         if ($credentialChange && RateLimiter::tooManyAttempts($passwordLimitKey, max(1, (int) config('auth.staff_current_password_failures', 5)))) {
164:             throw new TooManyRequestsHttpException(RateLimiter::availableIn($passwordLimitKey));
165:         }
166:         if ($isCurrentUser && (isset($userAttributes['password'])
167:             || (isset($userAttributes['email']) && $userAttributes['email'] !== $user->email))
168:             && is_string($validated['current_password'] ?? null)
169:             && Hash::check($validated['current_password'], $user->password)) {
170:             $verifiedPasswordHash = $user->password;
171:         }
172: 
173:         if ($credentialChange && is_string($validated['current_password'] ?? null)) {
174:             if ($verifiedPasswordHash === null) {
175:                 RateLimiter::hit($passwordLimitKey, 3600);
176:             } else {
177:                 RateLimiter::clear($passwordLimitKey);
178:             }
179:         }
180:         if ($credentialChange && $verifiedPasswordHash === null) {
181:             throw ValidationException::withMessages(['current_password' => 'أدخل كلمة المرور الحالية الصحيحة لتغيير بيانات الدخول.']);
182:         }
183:         if (isset($userAttributes['password'])) {
184:             $userAttributes['password'] = Hash::make($userAttributes['password']);
185:         }
186: 
187:         $isSuperAdminRequester = $currentUser instanceof User
188:             && $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff');
189:         $assigningSuperAdmin = is_array($roles)
190:             && in_array(StaffRole::SuperAdmin->value, $roles, true);
191: 
192:         $failure = DB::transaction(function () use (
193:             $user,
194:             $userAttributes,
195:             $roles,
196:             $currentUser,
197:             $isSuperAdminRequester,
198:             $assigningSuperAdmin,
199:             $validated,
200:             $verifiedPasswordHash,
201:         ): ?string {
202:             StaffAdministration::lock();
203:             StaffAdministration::authorize($currentUser, ['users.update', 'users.manage']);
204:             $isSuperAdminRequester = $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff');
205:             $lockedUser = User::query()->whereKey($user->getKey())->lockForUpdate()->firstOrFail();
206:             $this->assertAccessible($currentUser, $lockedUser);
207:             StaffAdministration::assertVersion($lockedUser, isset($validated['expected_version']) ? (int) $validated['expected_version'] : null);
208:             $before = StaffAdministration::userState($lockedUser);
209:             $ownCredentialsChanged = $currentUser->is($lockedUser) && (isset($userAttributes['password'])
210:                 || (isset($userAttributes['email']) && $userAttributes['email'] !== $lockedUser->email));
211:             if ($ownCredentialsChanged && ($verifiedPasswordHash === null
212:                 || ! hash_equals($lockedUser->password, $verifiedPasswordHash))) {
213:                 throw ValidationException::withMessages(['current_password' => 'أدخل كلمة المرور الحالية الصحيحة لتغيير بيانات الدخول.']);
214:             }
215:             if (array_key_exists('branch_id', $userAttributes)) {
216:                 $branch = $this->branches->restrictedBranch($currentUser);
217:                 abort_if($branch !== null && (int) ($userAttributes['branch_id'] ?? 0) !== $branch, 403);
218:             }
219:             if ($roles !== null) {
220:                 StaffAdministration::lockRoles($roles);
221:             }
222:             $targetIsSuperAdmin = $lockedUser->hasRole(StaffRole::SuperAdmin->value, 'staff');
223: 
224:             if ($targetIsSuperAdmin && (
225:                 (array_key_exists('is_active', $userAttributes) && ! (bool) $userAttributes['is_active'])
226:                 || ($roles !== null && ! in_array(StaffRole::SuperAdmin->value, $roles, true))
227:             )) {
228:                 if (! $isSuperAdminRequester || ! StaffAdministration::hasOtherActiveSuperAdmin($lockedUser)) {
229:                     return 'protected_super_admin';
230:                 }
231:             }
232: 
233:             if (! $isSuperAdminRequester && (
234:                 $targetIsSuperAdmin || $assigningSuperAdmin
235:             )) {
236:                 return 'protected';
237:             }
238: 
239:             if (! $this->mayManageUser($currentUser, $lockedUser, $roles ?? [])) {
240:                 return 'insufficient_permissions';
241:             }
242: 
243:             $emailChanged = isset($userAttributes['email']) && $userAttributes['email'] !== $lockedUser->email;
244:             $lockedUser->update($userAttributes);
245: 
246:             $rolesChanged = false;
247:             if ($roles !== null) {
248:                 $requestedRoles = $roles;
249:                 sort($requestedRoles);
250:                 $currentRoles = $before['roles'];
251:                 sort($currentRoles);
252:                 $rolesChanged = $requestedRoles !== $currentRoles;
253:                 if ($rolesChanged) {
