256:             }
257: 
258:             $passwordChanged = array_key_exists('password', $userAttributes);
259:             $deactivated = array_key_exists('is_active', $userAttributes)
260:                 && ! (bool) $userAttributes['is_active'];
261: 
262:             StaffAdministration::advanceVersion($lockedUser);
263:             StaffAdministration::audit($currentUser, 'user.updated', 'user', $lockedUser->id, array_keys($userAttributes + ($roles !== null ? ['roles' => $roles] : [])), $before, StaffAdministration::userState($lockedUser));
