287:     public function destroy(Request $request, User $user): JsonResponse
288:     {
289:         abort_if($user->is_system, 404);
290:         $currentUser = $request->user('staff');
291:         $validated = $request->validate(['expected_version' => ['required', 'integer', 'min:0']]);
292: 
293:         if ($currentUser instanceof User && $currentUser->is($user)) {
294:             return response()->json([
295:                 'message' => 'لا يمكنك تعطيل حسابك الحالي.',
296:             ], 403);
297:         }
298: 
299:         $deleted = DB::transaction(function () use ($currentUser, $user, $validated): bool {
300:             StaffAdministration::lock();
301:             StaffAdministration::authorize($currentUser, ['users.delete', 'users.manage']);
302:             $lockedUser = User::query()->whereKey($user->getKey())->lockForUpdate()->firstOrFail();
303: 
304:             $this->assertAccessible($currentUser, $lockedUser);
305:             if (($lockedUser->hasRole(StaffRole::SuperAdmin->value, 'staff')
306:                 && (! $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff') || ! StaffAdministration::hasOtherActiveSuperAdmin($lockedUser)))
307:                 || ! $this->mayManageUser($currentUser, $lockedUser)) {
308:                 return false;
309:             }
310: 
311:             if (! $lockedUser->is_active) {
312:                 return true;
313:             }
314:             StaffAdministration::assertVersion($lockedUser, (int) $validated['expected_version']);
315:             $before = StaffAdministration::userState($lockedUser);
316:             $lockedUser->forceFill(['is_active' => false]);
317:             StaffAdministration::advanceVersion($lockedUser);
318:             StaffAdministration::audit($currentUser, 'user.deactivated', 'user', $lockedUser->id, ['is_active'], $before, StaffAdministration::userState($lockedUser));
319:             $lockedUser->tokens()->delete();
320: 
321:             return true;
322:         });
323: 
324:         if (! $deleted) {
325:             return response()->json([
326:                 'message' => 'لا يمكن تعطيل حساب Super Admin أو حساب يمتلك صلاحيات لا تملكها.',
327:             ], 403);
328:         }
329: 
330:         return response()->json([
331:             'message' => 'تم تعطيل حساب الموظف وإلغاء رموزه.',
332:             'data' => UserResource::make($user->refresh()->load(['branch', 'roles.permissions', 'permissions']))->resolve($request),
333:         ]);
334:     }
