336:     /** @param list<string> $roles */
337:     private function mayManageUser(mixed $actor, ?User $target = null, array $roles = []): bool
338:     {
339:         if (! $actor instanceof User) {
340:             return false;
341:         }
342: 
343:         $actor->unsetRelation('roles')->unsetRelation('permissions');
344:         if ($target?->is_system) {
345:             return false;
346:         }
347: 
348:         if ($actor->hasRole(StaffRole::SuperAdmin->value, 'staff')) {
349:             return true;
350:         }
351: 
352:         // Super Admin is privileged by Gate even when it has no explicit permissions.
353:         if (in_array(StaffRole::SuperAdmin->value, $roles, true)
354:             || $target?->hasRole(StaffRole::SuperAdmin->value, 'staff')) {
355:             return false;
356:         }
357: 
358:         $permissions = Role::query()
359:             ->where('guard_name', 'staff')
360:             ->whereIn('name', $roles)
361:             ->with('permissions')
362:             ->get()
363:             ->flatMap(fn (Role $role) => $role->permissions->pluck('name'));
364: 
365:         if ($target !== null) {
366:             $permissions = $permissions->merge($target->getAllPermissions()->pluck('name'));
367:         }
368: 
369:         return $actor->hasAllPermissions($permissions->unique()->all());
370:     }
371: 
372:     private function insufficientPermissionsResponse(): JsonResponse
373:     {
374:         return response()->json([
375:             'message' => 'لا يمكنك إدارة حساب أو إسناد دور يمتلك صلاحيات لا تملكها.',
376:         ], 403);
377:     }
