 52:             'quotation_next_number' => ['sometimes', 'integer', 'min:1', 'max:999999999'],
 53:             'quotation_padding' => ['sometimes', 'integer', 'min:1', 'max:20'],
 54:             'movement_prefix' => ['sometimes', 'nullable', 'string', 'max:30'],
