 92:     public function withValidator(Validator $validator): void
 93:     {
 94:         $allowedKeys = array_values(array_filter(array_keys($this->rules()), fn ($key) => ! str_starts_with($key, 'expected.')));
 95:         $body = $this->validationData();
 96:         $unknownKeys = array_diff(array_keys($body), $allowedKeys, ['_method', '_token']);
 97: 
 98:         $validator->after(function (Validator $validator) use ($unknownKeys, $body): void {
 99:             $changed = array_diff(array_keys($body), ['expected', '_method', '_token']);
100:             $expected = is_array($body['expected'] ?? null) ? $body['expected'] : [];
101:             foreach (array_diff($changed, array_keys($expected)) as $key) {
102:                 $validator->errors()->add('expected.'.$key, 'القيمة الأصلية مطلوبة لهذا الإعداد.');
103:             }
104:             foreach (array_diff(array_keys($expected), $changed) as $key) {
105:                 $validator->errors()->add('expected.'.$key, 'قيمة أصلية غير مرتبطة بإعداد معدل.');
106:             }
107:             foreach ($unknownKeys as $unknownKey) {
108:                 $validator->errors()->add($unknownKey, 'إعداد غير معروف.');
109:             }
110:         });
111:     }
