10: /**
11:  * حلّ مستلمي إشعارات الطاقم: مستخدمون نشطون يملكون أيًا من الصلاحيات
12:  * المعطاة، إضافة إلى حاملي دور Super Admin دائمًا.
13:  */
14: final class StaffRecipients
15: {
16:     /** @param list<string> $permissions */
17:     public static function withAnyPermission(array $permissions): Collection
18:     {
19:         return User::query()
20:             ->where('is_active', true)->where('is_system', false)
21:             ->where(function ($query) use ($permissions): void {
22:                 $query->whereHas('roles', fn ($role) => $role->where('name', 'Super Admin')->where('guard_name', 'staff'));
23:                 foreach ($permissions as $permission) {
24:                     $query->orWhereHas('permissions', fn ($perm) => $perm->where('name', $permission)->where('guard_name', 'staff'))
25:                         ->orWhereHas('roles', fn ($role) => $role->where('guard_name', 'staff')
26:                             ->whereHas('permissions', fn ($perm) => $perm->where('name', $permission)->where('guard_name', 'staff')));
27:                 }
28:             })
29:             ->get();
30:     }
