 5: export function useApi<T>(fn: (signal: AbortSignal) => Promise<T>, deps: unknown[]) {
 6:   const [state, set] = useState<{ data?: T; loading: boolean; error?: ApiError }>({ loading: true });
 7:   const [tick, setTick] = useState(0);
 8:   useEffect(() => {
 9:     const ac = new AbortController();
10:     set(s => ({ ...s, loading: true, error: undefined }));   // خلي الداتا القديمة ظاهرة أثناء التحميل
11:     fn(ac.signal).then(data => { if (!ac.signal.aborted) set({ data, loading: false }); })
12:       .catch(e => { if (!ac.signal.aborted && !isAxiosCancel(e)) set(s => ({ ...s, loading: false, error: normalizeError(e) })); });
13:     return () => ac.abort();
14:     // eslint-disable-next-line react-hooks/exhaustive-deps
15:   }, [...deps, tick]);
16:   return { ...state, reload: () => setTick(t => t + 1) };
