 241: // ---------------- Storage locations ----------------
 242: function LocationForm({ open, initial, branchId, branchName, onClose, onSave }) {
 243:   const blank = { name: '', code: '', type: 'shelf', active: true, branchId };
 244:   const [f, setF] = useState(blank);
 245:   const [err, setErr] = useState({});
 246:   const [busy, setBusy] = useState(false);
 247:   useEffect(() => { if (open) { setF(initial ? { id: initial.id, name: initial.name || '', code: initial.code || '', type: initial.type || 'shelf', active: initial.is_active, branchId } : { ...blank, branchId }); setErr({}); setBusy(false); } }, [open]);
 248:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 249:   const submit = async () => {
 250:     const e = {};
 251:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 252:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 253:     // Code uniqueness inside the branch is enforced by the server (422 under code).
 254:     setErr(e);
 255:     if (Object.keys(e).length) return;
 256:     setBusy(true);
 257:     const res = await onSave(f);
 258:     setBusy(false);
 259:     if (res && (res.fields || res.message)) setErr({ ...res.fields, ...(res.message ? { _form: res.message } : {}) });
 260:   };
 261:   return (
 262:     <Modal open={open} onClose={onClose} title={initial ? 'تعديل موقع التخزين' : 'إضافة موقع تخزين'} sub={`تابع لـ ${branchName || ''}`}
 263:       footer={<><button className="btn btn-dark" onClick={submit} disabled={busy}>{initial ? 'حفظ' : 'إضافة'}</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 264:       <div className="space-y-4">
 265:         {err._form && <InlineAlert kind="red">{err._form}</InlineAlert>}
 266:         <div className="grid grid-cols-2 gap-4">
 267:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="رف A-01" /></Field>
 268:           <Field label="الكود" req error={err.code} hint="فريد داخل الفرع"><input dir="ltr" className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="A-01" maxLength={100} /></Field>
 269:         </div>
 270:         <div>
 271:           <span className="field-label">النوع</span>
 272:           <div className="grid grid-cols-5 gap-2">
 273:             {Object.entries(LOCATION_TYPES).map(([k, t]) => (
 274:               <button key={k} type="button" onClick={() => set('type', k)}
 275:                 className={`rounded-xl py-2.5 text-[12px] font-medium transition border ${f.type === k ? 'border-[var(--accent-orange)] c-primary font-semibold' : 'border-transparent c-secondary'}`}
 276:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>{t}</button>
 277:             ))}
 278:           </div>
 279:         </div>
 280:         <div className="v-subcard p-3.5 flex items-center justify-between">
 281:           <span className="text-[13px] font-semibold c-primary">{f.active ? 'نشط' : 'معطّل'}</span>
 282:           <Toggle on={f.active} onChange={v => set('active', v)} />
 283:         </div>
 284:       </div>
 285:     </Modal>
 286:   );
 287: }
