 446: // ============ 7. Stocktake · 8. Production receipt ============
 447: 
 448: 
 449: function CountsScreen({ go }) {
 450:   const { can, branchesQuery } = useInv();
 451:   const restriction = useRestrictedBranch();
 452:   const [create, setCreate] = useState(false);
 453:   const [branchF, setBranchF] = useState(null);
 454:   const [st, setSt] = useState('all');
 455:   const allowed = canAny(can, 'stocktakes.view', 'stocktakes.manage');
 456: 
 457:   // Small cardinality like branches: fetch all pages so filters run client-side.
 458:   const query = useApi(signal => (async () => {
 459:     const all = []; let page = 1; let last = 1;
 460:     do {
 461:       const res = await stocktakesApi.list({ per_page: 100, page, branch_id: (restriction.locked ? restriction.branchId : branchF) || undefined, status: st === 'all' ? undefined : st }, signal);
 462:       all.push(...(res.data || [])); last = res.meta?.last_page || 1; page += 1;
 463:     } while (page <= last);
 464:     return all;
 465:   })(), [branchF, st, restriction.branchId]);
 466:   const canCreate = canAny(can, 'stocktakes.create', 'stocktakes.manage');
 467: 
 468:   if (!allowed) return <NoPerm title="الجرد" perm="stocktakes.view" go={go} />;
 469: 
 470:   const list = query.data || [];
 471:   const { phase, error } = apiPhase(query, list.length === 0);
 472:   const effBranch = restriction.locked ? restriction.branchId : branchF;
 473:   const rows = list.filter(c => (st === 'all' || c.status === st) && (!effBranch || c.branch?.id === effBranch));
 474:   const shared = branchesQuery.data || [];
 475:   const branchOptions = shared.filter(b => b.is_active && (!restriction.locked || b.id === restriction.branchId)).map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
 476:   const active = (branchF ? 1 : 0) + (st !== 'all' ? 1 : 0);
 477: 
 478:   return (
 479:     <section className="space-y-5">
 480:       <PageHead title="الجرد" sub="مقارنة الكميات الموجودة فعليًا بالمسجّلة في النظام، ثم اعتماد الفروق كتسويات."
 481:         actions={canCreate && <button className="btn btn-dark" onClick={() => setCreate(true)}><Icon n="plus" s={14} w={2.2} /> جرد جديد</button>} />
 482:       <Card stagger={2}>
 483:         <CardHead title="القائمة" meta={phase === 'ready' ? `${rows.length} عملية` : null} right={
 484:           <div className="seg">
 485:             <button className={st === 'all' ? 'on' : ''} onClick={() => setSt('all')}>الكل</button>
 486:             {Object.entries(STOCKTAKE_STATUS).map(([k, t]) => <button key={k} className={st === k ? 'on' : ''} onClick={() => setSt(k)}>{t}</button>)}
 487:           </div>} />
 488:         <FilterBar active={active} onReset={() => { setBranchF(null); setSt('all'); }}>
 489:           <FItem label="الفرع"><Sel small value={effBranch} disabled={restriction.locked} onChange={v => setBranchF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
 490:         </FilterBar>
 491:         <Phase phase={phase} cols={6} error={error} onRetry={() => query.reload()}
 492:           empty={<EmptyState icon="clipboard" title="لم يتم إنشاء أي جرد بعد" sub="ابدأ جردًا لفرع كامل أو لموقع تخزين محدد."
 493:             action={canCreate && <button className="btn btn-dark btn-sm" onClick={() => setCreate(true)}><Icon n="plus" s={13} /> جرد جديد</button>} />}>
 494:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد عمليات جرد بهذه الفلاتر" /> : (
 495:           <table className="vt">
 496:             <thead><tr><th>رقم الجرد</th><th>الفرع</th><th>الموقع</th><th>البنود</th><th>الحالة</th><th>المنشئ</th><th>التاريخ</th><th></th></tr></thead>
 497:             <tbody>
 498:               {rows.map(c => (
 499:                 <tr key={c.id} className="cursor-pointer" onClick={() => go('count', { id: c.id })}>
 500:                   <td><span className="mono text-[12px] font-semibold c-primary" dir="ltr">{c.stocktake_number}</span></td>
 501:                   <td className="c-primary font-medium">{c.branch?.name || '—'}</td>
 502:                   <td className="mono text-[11.5px] c-secondary" dir="ltr">{c.location ? c.location.name : <span className="c-muted" style={{ fontFamily: 'inherit' }}>كل المواقع</span>}</td>
 503:                   <td className="num text-[11.5px] c-secondary">{c.items_count ?? '—'} بند</td>
 504:                   <td><Badge cls={({ draft: 'b-gray', in_progress: 'b-amber', approved: 'b-green', cancelled: 'b-red' })[c.status] || 'b-gray'} dot>{STOCKTAKE_STATUS[c.status] || c.status}</Badge></td>
 505:                   <td className="c-secondary">{c.creator_name || '—'}</td>
 506:                   <td className="num text-[11.5px] c-secondary">{formatDate(c.created_at)}</td>
 507:                   <td><Icon n="chevL" s={15} className="c-muted" /></td>
 508:                 </tr>
 509:               ))}
 510:             </tbody>
 511:           </table>)}
 512:         </Phase>
 513:       </Card>
 514:       <CountCreate open={create} onClose={() => setCreate(false)} go={go} onCreated={() => query.reload()} />
 515:     </section>
 516:   );
 517: }
 518: // NOTE: the stocktake list resource carries items_count but not the items, so the
 519: // old counted/total progress bar was replaced by the items total.
 520: 
 521: function CountCreate({ open, onClose, go, onCreated }) {
 522:   const { toast, can, branchesQuery, variantCache } = useInv();
 523:   const { keyFor, reset } = useIdempotencyKey();
 524:   const [branchId, setBranchId] = useState(null);
 525:   const [locId, setLocId] = useState(null);
 526:   const [note, setNote] = useState('');
 527:   const [mode, setMode] = useState('all');
 528:   const [picked, setPicked] = useState([]);
 529:   const [tried, setTried] = useState(false);
 530:   const [busy, setBusy] = useState(false);
 531:   const [srvErr, setSrvErr] = useState(null);
 532:   useEffect(() => { if (open) { setBranchId(null); setLocId(null); setNote(''); setMode('all'); setPicked([]); setTried(false); setBusy(false); setSrvErr(null); } }, [open]);
 533:   const restriction = useRestrictedBranch();
 534:   const effBranch = restriction.locked ? restriction.branchId : branchId;
 535: 
 536:   const scopeQuery = useApi(signal => (effBranch
 537:     ? (async () => {
 538:         const all = []; let page = 1; let last = 1;
 539:         do {
 540:           const res = await stockApi.levels({ branch_id: effBranch, location_id: locId || undefined, per_page: 100, page }, signal);
 541:           all.push(...(res.data || [])); last = res.meta?.last_page || 1; page += 1;
 542:         } while (page <= last);
 543:         return all;
 544:       })()
 545:     : Promise.resolve([])), [effBranch || 0, locId || 0]);
 546:   const scopeIds = useMemo(() => [...new Set((scopeQuery.data || []).map(s => s.product_variant_id))], [scopeQuery.data]);
 547:   useEffect(() => { cacheVariantNames(variantCache, (scopeQuery.data || []).map(s => s.variant)); }, [scopeQuery.data]);
 548: 
 549:   const locsQuery = useBranchesWithLocations(effBranch);
 550: 
 551:   const items = mode === 'all' ? scopeIds : picked;
 552:   const valid = effBranch && items.length > 0 && (mode !== 'all' || (!scopeQuery.loading && !scopeQuery.error));
 553: 
 554:   const submit = async () => {
 555:     setTried(true); if (!valid || busy) return;
 556:     setBusy(true); setSrvErr(null);
 557:     const payload = {
 558:       branch_id: effBranch, ...(locId ? { location_id: locId } : {}),
 559:       notes: note.trim() || null,
 560:       items: items.slice(0, 500).map(id => ({ product_variant_id: id, counted_qty: null })),
 561:     };
 562:     try {
 563:       // No snapshot is taken without items: a full-scope count is built by
 564:       // paging every stock level, then topping up past 500 via PATCH chunks.
 565:       const res = await stocktakesApi.create(payload, keyFor(payload));
 566:       const rest = items.slice(500);
 567:       for (let i = 0; i < rest.length; i += 500) {
 568:         await stocktakesApi.updateItems(res.data.id, rest.slice(i, i + 500).map(id => ({ product_variant_id: id, counted_qty: null })));
 569:       }
 570:       // New counts start as draft: move straight into counting like the old flow.
 571:       try { await stocktakesApi.update(res.data.id, { status: 'in_progress' }); } catch { /* detail still opens as draft */ }
 572:       reset();
 573:       toast(res.message || 'تم إنشاء الجرد'); onClose(); onCreated && onCreated(); go('count', { id: res.data.id });
 574:     } catch (e) {
 575:       setSrvErr(normalizeError(e).message);
 576:       setBusy(false);
 577:     }
 578:   };
 579: 
 580:   const shared = branchesQuery.data || [];
 581:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
 582:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
 583:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
 584: 
 585:   return (
 586:     <Modal open={open} onClose={onClose} width="max-w-2xl" title="جرد جديد" sub="حتى 500 بند عند الإنشاء، والباقي يُستكمل تلقائيًا"
 587:       footer={<><button className="btn btn-dark" onClick={submit} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} إنشاء وبدء العدّ</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 588:       <div className="space-y-4">
 589:         {srvErr && <InlineAlert kind="red">{srvErr}</InlineAlert>}
 590:         <div className="grid grid-cols-2 gap-4">
 591:           <Field label="الفرع" req error={tried && !effBranch ? 'مطلوب' : null}><Sel value={effBranch} onChange={v => { if (!restriction.locked) { setBranchId(v || null); setLocId(null); } }} placeholder="اختر…" disabled={restriction.locked} options={branchOptions} /></Field>
 592:           <Field label="الموقع" hint="اختياري"><Sel value={locId} onChange={v => setLocId(v || null)} placeholder={effBranch ? 'كل المواقع' : '—'} disabled={!effBranch} options={locOptions} /></Field>
 593:         </div>
 594:         <div>
 595:           <span className="field-label">الأصناف</span>
 596:           <div className="seg mb-3">
 597:             <button className={mode === 'all' ? 'on' : ''} onClick={() => setMode('all')}>كل الأصناف في النطاق</button>
 598:             <button className={mode === 'pick' ? 'on' : ''} onClick={() => setMode('pick')}>اختيار أصناف محددة</button>
 599:           </div>
 600:           {mode === 'all' ? (
 601:             <div className="v-subcard p-3.5 flex items-center justify-between">
 602:               <span className="text-[12.5px] c-secondary">{effBranch ? 'سيتم إدراج كل SKU له رصيد في النطاق المحدد' : 'اختر الفرع لعرض عدد الأصناف'}</span>
 603:               <span className="num font-display text-[20px] font-bold c-primary">{scopeQuery.loading ? '…' : items.length}</span>
 604:             </div>
 605:           ) : (
 606:             <div className="space-y-2">
 607:               <VariantPicker value={null} onChange={v => v && setPicked(p => p.length < 500 ? [...p, v] : p)} exclude={picked} placeholder="أضف SKU…" />
 608:               <div className="flex flex-wrap gap-1.5">
 609:                 {picked.map(v => <span key={v} className="badge b-gray !py-1"><span className="mono" dir="ltr">{variantCache.get(Number(v))?.sku || `#${v}`}</span><button onClick={() => setPicked(p => p.filter(x => x !== v))}><Icon n="x" s={11} /></button></span>)}
 610:                 {picked.length === 0 && <span className="text-[11.5px] c-muted">لم تتم إضافة أصناف</span>}
 611:               </div>
 612:             </div>
 613:           )}
 614:           {tried && effBranch && items.length === 0 && <div className="text-[11px] mt-1.5" style={{ color: 'var(--badge-red-text)' }}>لا توجد أصناف للجرد</div>}
 615:           <div className="text-[11px] c-muted mt-1.5 num">{items.length} / 500</div>
 616:         </div>
 617:         <Field label="ملاحظات"><textarea maxLength={2000} className="inp" rows={2} value={note} onChange={e => setNote(e.target.value)} /></Field>
 618:       </div>
 619:     </Modal>
 620:   );
 621: }
 622: 
 623: function CountDetail({ go, params }) {
 624:   const { toast, can, variantCache } = useInv();
 625:   const id = Number(params.id);
 626:   const [vals, setVals] = useState({});
 627:   const [filter, setFilter] = useState('all');
 628:   const [confirm, setConfirm] = useState(false);
 629:   const [pendingAction, setPendingAction] = useState(null);
 630:   const [busy, setBusy] = useState(false);
 631:   const [err, setErr] = useState(null);
 632:   const [dirty, setDirty] = useState(false);
 633:   const [stale, setStale] = useState({ itemIds: [], variantIds: [] });
 634:   const canEdit = canAny(can, 'stocktakes.update', 'stocktakes.manage');
 635:   const canApprove = canAny(can, 'stocktakes.approve', 'stocktakes.manage');
 636:   const canDelete = canAny(can, 'stocktakes.delete', 'stocktakes.manage');
 637: 
 638:   const query = useApi(signal => stocktakesApi.show(id, signal).then(t => {
 639:     cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
 640:     return t;
 641:   }), [id]);
 642: 
 643:   useEffect(() => {
 644:     const t = query.data;
 645:     if (t && !dirty) {
 646:       setVals(Object.fromEntries((t.items || []).map(it => [it.product_variant_id, it.counted_qty === null ? '' : String(it.counted_qty)])));
 647:     }
 648:   }, [query.data]);
 649: 
 650:   useEffect(() => {
 651:     if (!dirty) return;
 652:     const warn = e => { e.preventDefault(); e.returnValue = ''; };
 653:     window.addEventListener('beforeunload', warn);
 654:     return () => window.removeEventListener('beforeunload', warn);
 655:   }, [dirty]);
 656:   useEffect(() => {
 657:     window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: dirty }));
 658:     return () => window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: false }));
 659:   }, [dirty]);
 660: 
 661:   if (!canAny(can, 'stocktakes.view', 'stocktakes.manage')) return <NoPerm title="تفاصيل الجرد" perm="stocktakes.view" go={go} />;
 662: 
 663:   const c = query.data;
 664:   const { phase, error } = apiPhase(query, !c);
 665:   const onRetry = () => { query.reload(); };
 666: 
 667:   // "" means "not counted yet", "0" means an actual zero — never coerce "" to 0.
 668:   const countedOf = v => (v === '' || v === undefined ? null : Number(toLatinDigits(v)));
 669:   const rows = ((c?.items) || []).map(it => {
 670:     const v = vals[it.product_variant_id];
 671:     const a = countedOf(v);
 672:     const changed = a !== (it.counted_qty == null ? null : Number(it.counted_qty));
 673:     const diff = it.system_qty == null ? null : changed ? (a === null ? null : +((a - Number(it.system_qty)).toFixed(4))) : (it.difference == null ? null : Number(it.difference));
 674:     return { ...it, a, diff, isStale: stale.itemIds.includes(it.id) || stale.variantIds.includes(it.product_variant_id) };
 675:   });
 676:   const counted = rows.filter(r => r.a !== null).length;
 677:   const bookVisible = rows.some(r => r.system_qty != null);
 678:   const shown = rows.filter(r => filter === 'all' || (filter === 'uncounted' && r.a === null) || (filter === 'diff' && r.diff) || (filter === 'match' && r.diff === 0) || (filter === 'stale' && r.isStale));
 679:   const diffs = rows.filter(r => r.diff);
 680:   const editable = c && !['approved', 'cancelled'].includes(c.status) && canEdit;
 681: 
 682:   const chunked = arr => { const out = []; for (let i = 0; i < arr.length; i += 500) out.push(arr.slice(i, i + 500)); return out; };
 683:   const saveCounts = async (only = null) => {
 684:     if (busy) return;
 685:     if (rows.some(r => {
 686:       const v = vals[r.product_variant_id];
 687:       return v !== '' && v !== undefined && (!QTY_RE.test(toLatinDigits(v)) || Number(toLatinDigits(v)) > QTY_MAX);
 688:     })) { setErr('الكمية يجب أن تكون صفرًا أو أكبر، وبحد أقصى أربع خانات عشرية.'); return; }
 689:     setBusy(true); setErr(null);
 690:     const targets = only ? rows.filter(r => only.includes(r.product_variant_id)) : rows.filter(r => {
 691:       const cur = c.items.find(it => it.product_variant_id === r.product_variant_id);
 692:       return r.a !== (cur?.counted_qty == null ? null : Number(cur.counted_qty));
 693:     });
 694:     try {
 695:       for (const part of chunked(targets)) {
 696:         await stocktakesApi.updateItems(id, part.map(r => ({
 697:           product_variant_id: r.product_variant_id, counted_qty: r.a,
 698:           ...(r.isStale ? { recount: true } : {}),
 699:         })));
 700:       }
 701:       const savedIds = new Set(targets.map(r => r.product_variant_id));
 702:       setDirty(rows.some(r => !savedIds.has(r.product_variant_id) && r.a !== (c.items.find(it => it.product_variant_id === r.product_variant_id)?.counted_qty == null ? null : Number(c.items.find(it => it.product_variant_id === r.product_variant_id).counted_qty))));
 703:       setStale(s => ({ itemIds: s.itemIds.filter(x => !targets.some(r => r.id === x)), variantIds: s.variantIds.filter(x => !savedIds.has(x)) }));
 704:       toast('تم حفظ العدّ'); query.reload();
 705:     } catch (e) { setErr(normalizeError(e).message); }
 706:     setBusy(false);
 707:   };
 708:   const startCounting = async () => {
 709:     setBusy(true); setErr(null);
 710:     try { await stocktakesApi.update(id, { status: 'in_progress' }); toast('بدأ العدّ'); query.reload(); }
 711:     catch (e) { setErr(normalizeError(e).message); }
 712:     setBusy(false);
 713:   };
 714:   const changeStatus = async () => {
 715:     if (busy) return;
 716:     setBusy(true); setErr(null);
 717:     try {
 718:       if (pendingAction === 'delete') {
 719:         const res = await stocktakesApi.remove(id);
 720:         setDirty(false); window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: false }));
 721:         toast(res.message || 'تم حذف الجرد'); go('counts');
 722:       } else {
 723:         await stocktakesApi.update(id, { status: 'cancelled' });
 724:         setDirty(false); query.reload(); toast('تم إلغاء الجرد');
 725:       }
 726:       setPendingAction(null);
 727:     } catch (e) { setErr(normalizeError(e).message); }
 728:     setBusy(false);
 729:   };
 730:   const approve = async () => {
 731:     setBusy(true); setErr(null);
 732:     try {
 733:       const res = await stocktakesApi.approve(id);
 734:       setConfirm(false); setStale({ itemIds: [], variantIds: [] });
 735:       toast(res.message || 'تم اعتماد الجرد وترحيل الفروق'); query.reload();
 736:     } catch (e) {
 737:       const ne = normalizeError(e);
 738:       if (/لم تُعدّ/.test(ne.message)) { setFilter('uncounted'); query.reload(); }
 739:       if (ne.fields?.recount_item_ids || ne.fields?.recount_variant_ids) {
 740:         setStale({
 741:           itemIds: (ne.fields.recount_item_ids || []).map(Number),
 742:           variantIds: (ne.fields.recount_variant_ids || []).map(Number),
 743:         });
 744:         setFilter('stale');
 745:       }
 746:       setErr(ne.message);
 747:     }
 748:     setBusy(false);
 749:   };
 750: 
 751:   return (
 752:     <section className="space-y-5">
 753:       <PageHead title={c ? <span className="mono" dir="ltr">{c.stocktake_number}</span> : 'تفاصيل الجرد'} back={{ label: 'الجرد', onClick: () => go('counts') }}
 754:         sub={c && <span className="flex items-center gap-2 flex-wrap">{c.branch?.name || '—'} <span className="c-muted">·</span> {c.location ? <span className="mono" dir="ltr">{c.location.name}</span> : 'كل المواقع'} <Badge cls={({ draft: 'b-gray', in_progress: 'b-amber', approved: 'b-green', cancelled: 'b-red' })[c.status] || 'b-gray'} dot>{STOCKTAKE_STATUS[c.status] || c.status}</Badge></span>}
 755:         actions={c && c.status !== 'approved' && <>
 756:           {canDelete && ['draft', 'cancelled'].includes(c.status) && <button className="btn btn-danger" disabled={busy} onClick={() => { setErr(null); setPendingAction('delete'); }}>حذف الجرد</button>}
 757:           {editable && <button className="btn btn-soft" disabled={busy} onClick={() => { setErr(null); setPendingAction('cancel'); }}>إلغاء الجرد</button>}
 758:           {c.status === 'draft' && canEdit && <button className="btn btn-soft" disabled={busy} onClick={startCounting}>بدء العدّ</button>}
 759:           {editable && <button className="btn btn-soft" disabled={!dirty || busy} onClick={() => saveCounts()}>{busy ? 'جارٍ الحفظ…' : 'حفظ العدّ'}</button>}
 760:           {c.status !== 'cancelled' && (canApprove
 761:             ? <button className="btn btn-orange" onClick={() => { setErr(null); setConfirm(true); }} disabled={busy || dirty || !rows.length || counted < rows.length}><Icon n="check" s={14} w={2.2} /> اعتماد الجرد</button>
 762:             : <span className="inline-flex items-center gap-1.5 text-[11.5px] c-muted px-3 py-1.5 rounded-full v-subcard"><Icon n="lock" s={12} /> الاعتماد يتطلب صلاحية</span>)}
 763:         </>} />
 764: 
 765:       {dirty && <InlineAlert kind="amber" icon="info" title="تغييرات غير محفوظة">احفظ العدّ قبل مغادرة الصفحة حتى لا تضيع الكميات المدخلة.</InlineAlert>}
 766:       {err && !confirm && <InlineAlert kind="red">{err}<button className="btn btn-soft btn-sm" disabled={busy} onClick={() => saveCounts()}>إعادة المحاولة</button></InlineAlert>}
 767: 
 768:       <Phase phase={phase} cols={5} rows={5} error={error} onRetry={onRetry} onBack={() => go('counts')} empty={<Card><EmptyState icon="clipboard" title="لا توجد بنود في هذا الجرد" /></Card>}>
 769:         {c && (<>
 770:         <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
 771:           <KPI hot label="تم العدّ" icon="clipboard" value={`${counted}/${rows.length}`} sub={counted < rows.length ? `${rows.length - counted} بند لم يُعدّ بعد` : 'اكتمل العدّ'} />
 772:           <KPI label="مطابق" icon="check" value={bookVisible ? rows.filter(r => r.diff === 0).length : '—'} />
 773:           <KPI label="بفروق" icon="alert" value={bookVisible ? diffs.length : '—'} />
 774:           <KPI label="صافي الفرق" icon="sliders" value={bookVisible ? (() => { const n = diffs.reduce((a, r) => a + r.diff, 0); return (n > 0 ? '+' : '') + formatQty(n); })() : '—'} sub={bookVisible ? 'بالوحدات' : 'مخفي أثناء العدّ'} />
 775:         </div>
 776: 
 777:         <Card stagger={3}>
 778:           <CardHead title="جدول العدّ" right={
 779:             <div className="seg">
 780:               {[['all', 'الكل'], ['uncounted', 'لم يُعدّ'], ['diff', 'بفروق'], ['match', 'مطابق'], ...(stale.itemIds.length || stale.variantIds.length ? [['stale', 'يحتاج إعادة عدّ']] : [])].map(([k, l]) => <button key={k} disabled={!bookVisible && ['diff', 'match'].includes(k)} className={filter === k ? 'on' : ''} onClick={() => setFilter(k)}>{l}</button>)}
 781:             </div>} />
 782:           {counted < rows.length && c.status !== 'approved' && <div className="mb-3"><InlineAlert kind="amber" icon="info" title="الحقل الفارغ ≠ صفر">الخانة الفارغة المظللة تعني «لم يتم العدّ». إذا كان الصنف غير موجود فعليًا اكتب 0 أو اضغط «صفر».</InlineAlert></div>}
 783:           {stale.itemIds.length + stale.variantIds.length > 0 && <div className="mb-3"><InlineAlert kind="red" icon="alert" title="أصناف تحتاج إعادة عدّ">تغيّر رصيدها بعد عدّها. عدّها من جديد ثم اضغط «إعادة العدّ» على البند.</InlineAlert></div>}
 784:           {shown.length === 0 ? <EmptyState icon="filter" title="لا توجد بنود بهذا الفلتر" /> : (
 785:             <table className="vt">
 786:               <thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">كمية النظام</th><th className="t-num" style={{ width: 200 }}>الكمية الفعلية</th><th className="t-num">الفرق</th><th>الحالة</th></tr></thead>
 787:               <tbody>
 788:                 {shown.map(r => (
 789:                   <tr key={r.product_variant_id} className={r.isStale ? 'ring-1 ring-inset' : ''} style={r.isStale ? { background: 'var(--badge-red-bg)' } : {}}>
 790:                     <td><Sku>{r.sku || `#${r.product_variant_id}`}</Sku></td>
 791:                     <td><div className="font-medium c-primary truncate">{variantDisplayName(variantCache, r.product_variant_id, r.sku)}</div></td>
 792:                     <td className="t-num num c-secondary">{r.system_qty == null ? '—' : formatQty(r.system_qty)}</td>
 793:                     <td className="t-num">
 794:                       {editable ? (
 795:                         <div className="flex items-center gap-1.5 justify-end">
 796:                           {r.a === null && <button className="btn btn-ghost btn-sm !px-2 !py-1 text-[11px]" onClick={() => { setVals(v => ({ ...v, [r.product_variant_id]: '0' })); setDirty(true); }}>صفر</button>}
 797:                           <div className={`rounded-[10px] w-28 ${r.a === null ? 'uncounted' : ''}`}>
 798:                             <NumInput small value={vals[r.product_variant_id] ?? ''} placeholder="لم يُعدّ" onChange={v => { setVals(x => ({ ...x, [r.product_variant_id]: v })); setDirty(true); }} className={r.a === null ? '!bg-transparent' : ''} />
 799:                           </div>
 800:                           {r.a !== null && <button className="icon-btn !w-6 !h-6" title="مسح (لم يُعدّ)" onClick={() => { setVals(v => ({ ...v, [r.product_variant_id]: '' })); setDirty(true); }}><Icon n="x" s={11} /></button>}
 801:                           {r.isStale && <button className="btn btn-soft btn-sm" disabled={busy} onClick={() => saveCounts([r.product_variant_id])}>إعادة العدّ</button>}
 802:                         </div>
 803:                       ) : <span className="num font-semibold c-primary">{r.a === null ? <span className="c-muted font-normal">لم يُعدّ</span> : formatQty(r.a)}</span>}
 804:                     </td>
 805:                     <td className="t-num num font-bold" style={{ color: r.diff === null ? 'var(--text-muted)' : r.diff > 0 ? 'var(--badge-green-text)' : r.diff < 0 ? 'var(--badge-red-text)' : 'var(--text-secondary)' }}>
 806:                       {r.diff === null ? '—' : r.diff === 0 ? '0' : (r.diff > 0 ? '+' : '−') + formatQty(Math.abs(r.diff))}
 807:                     </td>
 808:                     <td>{r.isStale ? <Badge cls="b-red">تحتاج إعادة عدّ</Badge> : r.a === null ? <Badge cls="b-gray">لم يُعدّ</Badge> : r.diff === null ? <Badge cls="b-gray">تم العدّ</Badge> : r.a === 0 ? <Badge cls={r.diff ? 'b-red' : 'b-green'}>صفر فعلي</Badge> : r.diff === 0 ? <Badge cls="b-green">مطابق</Badge> : <Badge cls={r.diff > 0 ? 'b-blue' : 'b-red'}>{r.diff > 0 ? 'زيادة' : 'عجز'}</Badge>}</td>
 809:                   </tr>
 810:                 ))}
 811:               </tbody>
 812:             </table>
 813:           )}
 814:         </Card>
 815:         </>)}
 816:       </Phase>
 817: 
 818:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={approve} busy={busy} error={err} title="اعتماد الجرد" confirmLabel="اعتماد وترحيل الفروق"
 819:         body={<>سيتم ترحيل <b className="num c-primary">{diffs.length}</b> فرق كحركات «فرق جرد» وتحديث الأرصدة. لا يمكن تعديل العدّ بعد الاعتماد.</>} />
 820:       <ConfirmDialog open={!!pendingAction} onClose={() => setPendingAction(null)} onConfirm={changeStatus} busy={busy} error={err} danger
 821:         title={pendingAction === 'delete' ? 'حذف الجرد؟' : 'إلغاء الجرد؟'} confirmLabel={pendingAction === 'delete' ? 'حذف الجرد' : 'إلغاء الجرد'}
 822:         body="سيُقفل الجرد وتُفقد أي تغييرات غير محفوظة. لن تتغير الأرصدة بهذه العملية." />
 823:     </section>
 824:   );
 825: }
