 828: // ---------------- 8. Production receipt ----------------
 829: const PRD_MAX = 50;
 830: let __prKey = 1;
 831: const newPrLine = () => ({ key: __prKey++, variantId: null, qty: '', cost: '' });
 832: 
 833: function ProductionScreen({ go }) {
 834:   const { toast, can, variantCache } = useInv();
 835:   const [open, setOpen] = useState(false);
 836:   const [view, setView] = useState(null);
 837:   const [page, setPage] = useState(1);
 838:   const canEnter = can('inventory.adjust') && can('products.view_cost');
 839:   const showCost = can('products.view_cost');
 840: 
 841:   const history = useApi(signal => productionApi.list({ per_page: 15, page }, signal), [page]);
 842:   const optsQuery = useApi(signal => productionApi.options('', signal), []);
 843:   useEffect(() => {
 844:     const d = optsQuery.data;
 845:     if (d) {
 846:       (d.variants || []).forEach(v => {
 847:         cacheVariantOptions(variantCache, [v]);
 848:       });
 849:     }
 850:   }, [optsQuery.data]);
 851: 
 852:   const branchName = useMemo(() => {
 853:     const m = new Map();
 854:     (optsQuery.data?.branches || []).forEach(b => m.set(b.id, b.name));
 855:     return id => m.get(id) || `#${id}`;
 856:   }, [optsQuery.data]);
 857:   const locName = useMemo(() => {
 858:     const m = new Map();
 859:     (optsQuery.data?.branches || []).forEach(b => (b.locations || []).forEach(l => m.set(l.id, l.name)));
 860:     return id => (id ? m.get(id) || `#${id}` : '—');
 861:   }, [optsQuery.data]);
 862: 
 863:   const rows = history.data?.data || [];
 864:   if (!can('inventory.view')) return <NoPerm title="استلام الإنتاج" perm="inventory.view" go={go} />;
 865:   const { phase, error } = apiPhase(history, rows.length === 0);
 866:   // Raw Laravel paginator (data/current_page/last_page/…) — NOT under meta, so it
 867:   // gets its own small mapper instead of the ResourceCollection one.
 868: 
 869:   return (
 870:     <section className="space-y-5">
 871:       <PageHead title="استلام الإنتاج" sub="تسجيل المنتجات التامة الواردة من التصنيع إلى المخزن مع تكلفة الوحدة."
 872:         actions={canEnter ? <button className="btn btn-dark" onClick={() => setOpen(true)}><Icon n="plus" s={14} w={2.2} /> تسجيل استلام</button>
 873:           : <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-pill-surface"><Icon n="lock" s={12} /> يتطلب صلاحية تسوية المخزون وعرض التكلفة</span>} />
 874:       <Card stagger={2}>
 875:         <CardHead title="سجل الاستلامات" meta={phase === 'ready' ? `${rows.length} استلام` : null} />
 876:         <Phase phase={phase} cols={6} error={error} onRetry={() => history.reload()}
 877:           empty={<EmptyState icon="factory" title="لا توجد استلامات إنتاج" sub="عند وصول دفعة من التصنيع سجّلها هنا لتُضاف إلى رصيد المخزن." action={canEnter && <button className="btn btn-dark btn-sm" onClick={() => setOpen(true)}><Icon n="plus" s={13} /> تسجيل استلام</button>} />}>
 878:           <table className="vt">
 879:             <thead><tr><th>رقم الدفعة</th><th>الفرع</th><th>الموقع</th><th className="t-num">البنود</th><th className="t-num">إجمالي الكمية</th>{showCost && <th className="t-num">إجمالي التكلفة</th>}<th>التاريخ</th></tr></thead>
 880:             <tbody>
 881:               {rows.map(p => (
 882:                 <tr key={p.id} className="cursor-pointer" onClick={() => setView(p)}>
 883:                   <td><Sku>{p.batch_number}</Sku></td>
 884:                   <td className="c-primary font-medium">{branchName(p.branch_id)}</td>
 885:                   <td className="mono text-[11.5px] c-secondary" dir="ltr">{locName(p.location_id)}</td>
 886:                   <td className="t-num num c-secondary">{(p.items || []).length}</td>
 887:                   <td className="t-num num font-semibold c-primary">{(p.items || []).reduce((a, l) => a + Number(l.quantity || 0), 0)}</td>
 888:                   {showCost && <td className="t-num num c-primary">{formatCurrency((p.items || []).reduce((a, l) => a + Number(l.quantity || 0) * Number(l.unit_cost || 0), 0))}</td>}
 889:                   <td className="num text-[11.5px] c-secondary">{formatDate(p.created_at, { includeTime: true })}</td>
 890:                 </tr>
 891:               ))}
 892:             </tbody>
 893:           </table>
 894:           {history.data && history.data.last_page > 1 && (
 895:             <div className="flex items-center justify-between mt-4">
 896:               <button className="btn btn-soft btn-sm" disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>السابق</button>
 897:               <span className="text-[12px] c-muted num">صفحة {history.data.current_page} من {history.data.last_page}</span>
 898:               <button className="btn btn-soft btn-sm" disabled={page >= history.data.last_page} onClick={() => setPage(p => p + 1)}>التالي</button>
 899:             </div>
 900:           )}
 901:         </Phase>
 902:       </Card>
 903:       <ProductionForm open={open} onClose={() => setOpen(false)} branches={optsQuery.data?.branches || []} onSaved={() => { history.reload(); }} />
 904:       <Modal open={!!view} onClose={() => setView(null)} width="max-w-xl" title={view ? <span className="mono" dir="ltr">{view.batch_number}</span> : ''} sub={view && `${branchName(view.branch_id)} · ${locName(view.location_id)}`}>
 905:         {view && <table className="vt mb-4"><thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">الكمية</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}</tr></thead>
 906:           <tbody>{(view.items || []).map((l, i) => <tr key={i}><td><Sku>{variantCache.get(Number(l.product_variant_id))?.sku || `#${l.product_variant_id}`}</Sku></td><td><div className="font-medium c-primary truncate">{variantDisplayName(variantCache, l.product_variant_id, null)}</div></td><td className="t-num num font-semibold">{formatQty(l.quantity)}</td>{showCost && <td className="t-num num">{l.unit_cost != null ? formatCurrency(l.unit_cost) : '—'}</td>}</tr>)}</tbody></table>}
 907:       </Modal>
 908:     </section>
 909:   );
 910: }
