 912: function ProductionForm({ open, onClose, branches, onSaved }) {
 913:   const { toast, variantCache } = useInv();
 914:   const { keyFor, reset } = useIdempotencyKey();
 915:   const restriction = useRestrictedBranch();
 916:   const [f, setF] = useState({ batch: '', branchId: null, locId: null, note: '' });
 917:   const [lines, setLines] = useState([newPrLine()]);
 918:   const [tried, setTried] = useState(false);
 919:   const [busy, setBusy] = useState(false);
 920:   const [err, setErr] = useState(null);
 921:   const [rowErrs, setRowErrs] = useState({});
 922:   useEffect(() => { if (open) { setF({ batch: '', branchId: restriction.locked ? restriction.branchId : null, locId: null, note: '' }); setLines([newPrLine()]); setTried(false); setErr(null); setRowErrs({}); setBusy(false); } }, [open]);
 923:   const upd = (k, p) => { setLines(ls => ls.map(l => l.key === k ? { ...l, ...p } : l)); setRowErrs({}); };
 924:   const bad = l => {
 925:     if (!l.variantId) return true;
 926:     const qv = toLatinDigits(l.qty);
 927:     if (!/^\d+$/.test(qv) || !(Number(qv) >= 1) || Number(qv) > 99999999) return true;
 928:     const cv = toLatinDigits(l.cost);
 929:     if (cv === '' || !QTY_RE.test(cv) || Number(cv) < 0 || Number(cv) > QTY_MAX) return true;
 930:     return false;
 931:   };
 932:   const valid = f.batch.trim() && f.batch.trim().length <= 100 && f.branchId && lines.length && lines.length <= PRD_MAX && lines.every(l => !bad(l));
 933:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId) !== i).length;
 934:   const total = lines.reduce((a, l) => a + (Number(toLatinDigits(l.qty)) || 0) * (Number(toLatinDigits(l.cost)) || 0), 0);
 935:   const locOpts = ((branches.find(b => b.id === f.branchId)?.locations) || []).map(l => ({ value: l.id, label: l.name }));
 936:   const submit = async () => {
 937:     setTried(true); if (!valid || dupes || busy) return;
 938:     setBusy(true); setErr(null); setRowErrs({});
 939:     const payload = {
 940:       batch_number: f.batch.trim(), branch_id: f.branchId,
 941:       ...(f.locId ? { location_id: f.locId } : {}),
 942:       notes: f.note.trim() ? f.note.trim().slice(0, 1000) : null,
 943:       items: lines.map(l => ({ product_variant_id: l.variantId, quantity: Number(toLatinDigits(l.qty)), unit_cost: Number(toLatinDigits(l.cost)) })),
 944:     };
 945:     try {
 946:       // Idempotency-Key is REQUIRED here (422 without it); same payload reuses
 947:       // the same key so a double-click records one receipt only.
 948:       const res = await productionApi.create(payload, keyFor(payload));
 949:       reset();
 950:       toast(res.message || 'تم تسجيل استلام الإنتاج');
 951:       onClose(); onSaved();
 952:     } catch (e) {
 953:       const ne = normalizeError(e);
 954:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
 955:       setErr(ne.message);
 956:       setBusy(false);
 957:     }
 958:   };
 959:   return (
 960:     <Modal open={open} onClose={onClose} width="max-w-4xl" title="تسجيل استلام إنتاج" sub={`حتى ${PRD_MAX} بندًا · الكميات أعداد صحيحة · المتغيرات مميزة`}
 961:       footer={<>
 962:         <button className="btn btn-orange" onClick={submit} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} تسجيل الاستلام</button>
 963:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
 964:         <span className="flex-1" />
 965:         <span className="text-[12px] c-secondary">إجمالي التكلفة <span className="num font-display text-[18px] font-bold c-primary mr-1">{formatCurrency(total)}</span></span>
 966:       </>}>
 967:       <div className="space-y-4">
 968:         {err && <InlineAlert kind="red" title="رفض الخادم العملية">{err}</InlineAlert>}
 969:         {dupes > 0 && <InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر — المتغيرات يجب أن تكون مميزة، احذف التكرار قبل التسجيل.</InlineAlert>}
 970:         <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
 971:           <Field label="رقم الدفعة" req error={tried && !f.batch.trim() ? 'مطلوب' : rowErrs.batch_number}><input dir="ltr" className={`inp mono text-left ${tried && !f.batch.trim() ? 'err' : ''}`} maxLength={100} value={f.batch} onChange={e => setF({ ...f, batch: e.target.value.toUpperCase() })} placeholder="B-2610-08" /></Field>
 972:           <Field label="الفرع / المخزن" req error={tried && !f.branchId ? 'مطلوب' : rowErrs.branch_id}><Sel value={f.branchId} disabled={restriction.locked} onChange={v => setF({ ...f, branchId: v || null, locId: null })} placeholder="اختر…" options={branches.filter(b => !restriction.locked || b.id === restriction.branchId).map(b => ({ value: b.id, label: b.name }))} /></Field>
 973:           <Field label="الموقع" hint="اختياري"><Sel value={f.locId} onChange={v => setF({ ...f, locId: v || null })} placeholder={f.branchId ? 'الموقع الافتراضي' : '—'} disabled={!f.branchId} options={locOpts} /></Field>
 974:         </div>
 975:         <div>
 976:           <div className="flex items-center justify-between mb-2">
 977:             <span className="field-label !mb-0">البنود <span className="num c-muted">{lines.length}/{PRD_MAX}</span></span>
 978:             <button className="btn btn-soft btn-sm" disabled={lines.length >= PRD_MAX} onClick={() => setLines(ls => [...ls, newPrLine()])}><Icon n="plus" s={13} /> إضافة بند</button>
 979:           </div>
 980:           <table className="vt">
 981:             <thead><tr><th className="w-8">#</th><th style={{ minWidth: 300 }}>المتغير / SKU</th><th style={{ width: 120 }}>الكمية</th><th style={{ width: 140 }}>تكلفة الوحدة</th><th className="t-num">الإجمالي</th><th></th></tr></thead>
 982:             <tbody>
 983:               {lines.map((l, i) => {
 984:                 const re = rowErrs[i] || {};
 985:                 return (
 986:                 <tr key={l.key}>
 987:                   <td className="num c-muted">{i + 1}</td>
 988:                   <td><div className={(tried && !l.variantId) || re.product_variant_id ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
 989:                     {re.product_variant_id && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.product_variant_id}</div>}</td>
 990:                   <td><NumInput small integer value={l.qty} onChange={v => upd(l.key, { qty: v })} err={(tried && bad(l)) || re.quantity} />
 991:                     {re.quantity && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.quantity}</div>}</td>
 992:                   <td><NumInput small decimals={4} value={l.cost} onChange={v => upd(l.key, { cost: v })} err={(tried && bad(l)) || re.unit_cost} placeholder="0.00" />
 993:                     {re.unit_cost && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.unit_cost}</div>}</td>
 994:                   <td className="t-num num c-primary font-semibold">{formatCurrency((Number(toLatinDigits(l.qty)) || 0) * (Number(toLatinDigits(l.cost)) || 0))}</td>
 995:                   <td><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
 996:                 </tr>
 997:                 );
 998:               })}
 999:             </tbody>
1000:           </table>
1001:         </div>
1002:         <Field label="ملاحظات"><textarea maxLength={1000} className="inp" rows={2} value={f.note} onChange={e => setF({ ...f, note: e.target.value })} /></Field>
1003:       </div>
1004:     </Modal>
1005:   );
1006: }
