1023: // Product-level then variant-level filter (product narrows the variant list)
1024: 
1025: // ---------------- 3. Stock balances ----------------
1026: function StockScreen({ go, params }) {
1027:   const { toast, can, branchesQuery, variantCache } = useInv();
1028:   const [page, setPage] = useState(1);
1029:   const restriction = useRestrictedBranch();
1030:   const allowed = canAny(can, 'inventory.view');
1031: 
1032:   const f = {
1033:     branchId: params.branchId ? Number(params.branchId) : null,
1034:     locationId: params.locationId ? Number(params.locationId) : null,
1035:     variantId: params.variantId ? Number(params.variantId) : null,
1036:     low: params.low === '1',
1037:   };
1038:   // A restricted user is pinned to their branch (the backend scopes them anyway).
1039:   const effBranch = restriction.locked ? restriction.branchId : f.branchId;
1040:   const set = p => {
1041:     const n = { branchId: f.branchId, locationId: f.locationId, variantId: f.variantId, low: f.low ? '1' : undefined, ...p };
1042:     if (n.branchId !== f.branchId) n.locationId = undefined;
1043:     if (!n.low) delete n.low;
1044:     go('stock', n);
1045:   };
1046: 
1047:   const locsQuery = useBranchesWithLocations(effBranch);
1048:   const query = useApi(signal => stockApi.levels({
1049:     branch_id: effBranch || undefined, location_id: f.locationId || undefined,
1050:     product_variant_id: f.variantId || undefined, low_stock: f.low || undefined,
1051:     per_page: 15, page,
1052:   }, signal).then(res => { cacheVariantNames(variantCache, (res.data || []).map(r => r.variant)); return res; }),
1053:   [effBranch || 0, f.locationId || 0, f.variantId || 0, f.low, page]);
1054: 
1055:   if (!allowed) return <NoPerm title="أرصدة المخزون" perm="inventory.view" go={go} />;
1056: 
1057:   const rows = query.data?.data || [];
1058:   const meta = query.data?.meta;
1059:   const { phase, error } = apiPhase(query, rows.length === 0);
1060:   const onRetry = () => query.reload();
1061:   const shared = branchesQuery.data || [];
1062:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
1063:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1064:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1065:   const active = (effBranch ? 1 : 0) + (f.locationId ? 1 : 0) + (f.variantId ? 1 : 0) + (f.low ? 1 : 0);
1066:   const sum = k => rows.reduce((a, s) => a + Number(s[k] || 0), 0);
1067:   const canAdjust = canAny(can, 'inventory.adjust');
1068: 
1069:   return (
1070:     <section className="space-y-5">
1071:       <PageHead title="أرصدة المخزون" sub="الكميات الحالية لكل SKU في كل فرع وموقع. لتغيير أي كمية استخدم عملية مخزنية."
1072:         actions={canAdjust && <button className="btn btn-dark" onClick={() => go('adjust')}><Icon n="sliders" s={14} /> تسوية جديدة</button>} />
1073: 
1074:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1075:         <KPI hot label="المتاح" icon="box" value={phase === 'ready' ? formatQty(sum('available')) : '—'} sub={`${rows.length} سطر رصيد · في الصفحة الحالية`} />
1076:         <KPI label="المحجوز" icon="lock" value={phase === 'ready' ? formatQty(sum('reserved')) : '—'} sub="لطلبات مفتوحة" />
1077:         <KPI label="قيد النقل" icon="truck" value={phase === 'ready' ? formatQty(sum('in_transit')) : '—'} sub="في تحويلات مشحونة" />
1078:         <button onClick={() => set({ low: f.low ? undefined : '1' })} className="text-right">
1079:           <KPI label="تحت حد إعادة الطلب" icon="alert" value={phase === 'ready' ? rows.filter(r => r.is_low_stock).length : '—'} sub={f.low ? 'الفلتر مفعّل · اضغط للإلغاء' : 'اضغط لعرضها فقط'} />
1080:         </button>
1081:       </div>
1082: 
1083:       <Card stagger={3}>
1084:         <CardHead title="الأرصدة" meta={phase === 'ready' ? `${rows.length} سطر` : null}
1085:           right={<span className="text-[11.5px] c-muted flex items-center gap-1.5"><Icon n="eye" s={13} /> للعرض فقط</span>} />
1086:         <FilterBar active={active} onReset={() => go('stock', {})}>
1087:           <FItem label="الفرع"><Sel small value={effBranch} onChange={v => set({ branchId: v || undefined })} placeholder="كل الفروع" disabled={restriction.locked} options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1088:           <FItem label="الموقع" w="w-40"><Sel small value={f.locationId} onChange={v => set({ locationId: v || undefined })} placeholder={effBranch ? 'كل المواقع' : 'اختر فرعًا أولًا'} disabled={!effBranch} options={locOptions} className="!bg-[var(--bg-card)]" /></FItem>
1089:           <FItem label="الصنف / SKU" w="w-64"><VariantPicker small value={f.variantId} onChange={v => set({ variantId: v || undefined })} placeholder="كل الأصناف" allowClear /></FItem>
1090:           <label className="flex items-center gap-2.5 px-3 py-2 rounded-full cursor-pointer mb-0.5" style={{ background: f.low ? 'var(--accent-orange-light)' : 'var(--bg-card)' }}>
1091:             <Toggle on={f.low} onChange={v => set({ low: v ? '1' : undefined })} />
1092:             <span className="text-[12px] font-medium c-primary">المخزون المنخفض فقط</span>
1093:           </label>
1094:         </FilterBar>
1095:         <Phase phase={phase} cols={10} rows={7} error={error} onRetry={onRetry}
1096:           empty={<EmptyState icon="box" title="لا توجد أرصدة مسجّلة بعد" sub="سجّل الكميات الافتتاحية عن طريق تسوية زيادة مع سبب واضح مثل «رصيد افتتاحي»."
1097:             action={canAdjust && <button className="btn btn-dark btn-sm" onClick={() => go('adjust')}><Icon n="plus" s={13} /> إدخال رصيد افتتاحي</button>} />}>
1098:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد أرصدة تطابق الفلاتر" sub="غيّر الفلاتر أو امسحها لعرض كل الأرصدة." /> : (
1099:             <div className="overflow-x-auto -mx-1 px-1">
1100:               <table className="vt">
1101:                 <thead><tr>
1102:                   <th>المنتج</th><th>SKU</th><th>الفرع</th><th>الموقع</th>
1103:                   <th className="t-num">الموجود</th><th className="t-num">المحجوز</th><th className="t-num">التالف</th><th className="t-num">قيد النقل</th><th className="t-num">المتاح</th><th className="t-num">حد الطلب</th><th>آخر تحديث</th><th></th>
1104:                 </tr></thead>
1105:                 <tbody>
1106:                   {rows.map(s => {
1107:                     const low = !!s.is_low_stock;
1108:                     const pct = Math.min(100, Number(s.reorder_level) ? Number(s.available) / (Number(s.reorder_level) * 2) * 100 : 100);
1109:                     const v = s.variant || variantCache.get(Number(s.product_variant_id)) || {};
1110:                     return (
1111:                       <tr key={s.id}>
1112:                         <td><div className="min-w-0"><div className="font-medium c-primary truncate">{pickName({ product_name_ar: v.product_name_ar, product_name_en: v.product_name_en, sku: v.sku || s.product_variant_id })}</div></div></td>
1113:                         <td><Sku>{v.sku || `#${s.product_variant_id}`}</Sku></td>
1114:                         <td className="c-secondary">{s.branch?.name || '—'}</td>
1115:                         <td>{s.location ? <span className="text-[11.5px] c-secondary">{s.location.name}</span> : <span className="text-[11.5px] c-muted">بدون موقع</span>}</td>
1116:                         <td className="t-num num font-semibold c-primary">{formatQty(s.on_hand)}</td>
1117:                         <td className="t-num num c-secondary">{formatQty(s.reserved)}</td>
1118:                         <td className="t-num num" style={{ color: Number(s.damaged) ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{formatQty(s.damaged)}</td>
1119:                         <td className="t-num num" style={{ color: Number(s.in_transit) ? 'var(--badge-blue-text)' : 'var(--text-muted)' }}>{formatQty(s.in_transit)}</td>
1120:                         <td className="t-num">
1121:                           <div className="flex flex-col items-end gap-1">
1122:                             <span className="flex items-center gap-1.5"><span className={`num font-bold ${low ? '' : 'c-primary'}`} style={low ? { color: 'var(--accent-orange)' } : {}}>{formatQty(s.available)}</span>{low && <Badge cls="b-amber" dot>منخفض</Badge>}</span>
1123:                             <span className="w-16 h-1 rounded-full hatched overflow-hidden flex justify-end" style={{ direction: 'ltr' }}>
1124:                               <span className="block h-full rounded-full" style={{ width: pct + '%', background: low ? 'var(--accent-orange)' : 'var(--text-primary)' }} />
1125:                             </span>
1126:                           </div>
1127:                         </td>
1128:                         <td className="t-num num c-muted">{formatQty(s.reorder_level)}</td>
1129:                         <td className="num text-[11.5px] c-muted">{formatDate(s.updated_at)}</td>
1130:                         <td>
1131:                           <div className="flex items-center gap-0.5 justify-end">
1132:                             <button className="icon-btn" title="حركات الصنف" onClick={() => go('moves', { variantId: s.product_variant_id, branchId: s.branch?.id, locationId: s.location?.id })}><Icon n="history" s={15} /></button>
1133:                             {canAdjust && <button className="icon-btn" title="تسوية" onClick={() => go('adjust', { branchId: s.branch?.id, locId: s.location?.id, variantId: s.product_variant_id })}><Icon n="sliders" s={15} /></button>}
1134:                           </div>
1135:                         </td>
1136:                       </tr>
1137:                     );
1138:                   })}
1139:                 </tbody>
1140:               </table>
1141:             </div>
1142:           )}
1143:         </Phase>
1144:         {meta && (meta.last_page > 1) && (
1145:           <div className="flex items-center justify-between mt-4">
1146:             <button className="btn btn-soft btn-sm" disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>السابق</button>
1147:             <span className="text-[12px] c-muted num">صفحة {page} من {meta.last_page}</span>
1148:             <button className="btn btn-soft btn-sm" disabled={page >= meta.last_page} onClick={() => setPage(p => p + 1)}>التالي</button>
1149:           </div>
1150:         )}
1151:       </Card>
1152:     </section>
1153:   );
1154: }
1155: // NOTE: "المتاح" KPI is page-scoped on purpose — GET inventory returns one page
1156: // and there is no summary endpoint, so a global total cannot be shown honestly.
1157: 
1158: // ---------------- 4. Adjustment ----------------
1159: const ADJ_MAX = 100;
1160: let __adjLineId = 1;
1161: const newAdjLine = (p = {}) => ({ key: __adjLineId++, variantId: null, type: 'increase', qty: '', reason: '', ...p });
1162: 
1163: const ADJ_API_TYPES = {
1164:   increase:         { label: 'زيادة',              cls: 'b-green' },
1165:   decrease:         { label: 'نقصان',              cls: 'b-red'   },
1166:   mark_damaged:     { label: 'تسجيل تالف',         cls: 'b-amber' },
1167:   write_off_damaged:{ label: 'إعدام تالف',         cls: 'b-red'   },
1168:   restore_damaged:  { label: 'استرجاع من التالف',  cls: 'b-blue'  },
1169: };
1170: 
1171: function AdjustScreen({ go, params }) {
1172:   const { toast, can, branchesQuery, variantCache } = useInv();
1173:   const { keyFor, reset } = useIdempotencyKey();
1174:   const [branchId, setBranchId] = useState(params.branchId ? Number(params.branchId) : null);
1175:   const [locId, setLocId] = useState(params.locId ? Number(params.locId) : (params.locationId ? Number(params.locationId) : null));
1176:   const [lines, setLines] = useState(() => [newAdjLine(params.variantId ? { variantId: Number(params.variantId) } : {})]);
1177:   const [tried, setTried] = useState(false);
1178:   const [confirm, setConfirm] = useState(false);
1179:   const [busy, setBusy] = useState(false);
1180:   const [srvErr, setSrvErr] = useState(null);
1181:   const [rowErrs, setRowErrs] = useState({});
1182:   const [opening, setOpening] = useState(false);
1183:   const allowed = can('inventory.adjust');
1184:   const restriction = useRestrictedBranch();
1185:   const effBranch = restriction.locked ? restriction.branchId : branchId;
1186: 
1187:   const locsQuery = useBranchesWithLocations(effBranch);
1188: 
1189:   if (!allowed) return <NoPerm title="تسوية المخزون" perm="inventory.adjust" go={go} />;
1190: 
1191:   const upd = (key, p) => { setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l)); setRowErrs({}); };
1192:   const lineErr = l => {
1193:     const e = {};
1194:     if (!l.variantId) e.variantId = true;
1195:     const qv = toLatinDigits(l.qty);
1196:     if (!qv || !QTY_RE.test(qv) || !(Number(qv) > 0) || Number(qv) > QTY_MAX) e.qty = 'كمية موجبة حتى 4 منازل عشرية';
1197:     if (!l.reason.trim()) e.reason = true;
1198:     else if (l.reason.trim().length > 1000) e.reason = true;
1199:     return e;
1200:   };
1201:   const clientErrs = lines.map(lineErr);
1202:   const valid = effBranch && clientErrs.every(e => !Object.keys(e).length);
1203:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId && x.type === l.type) !== i).length;
1204: 
1205:   const applyOpening = on => {
1206:     setOpening(on);
1207:     setLines(ls => ls.map(l => on ? { ...l, type: 'increase', reason: l.reason || 'رصيد افتتاحي' } : l));
1208:   };
1209: 
1210:   const execute = async () => {
1211:     if (busy) return; // double-click guard: one movement per key
1212:     setBusy(true); setSrvErr(null); setRowErrs({});
1213:     const payload = {
1214:       branch_id: effBranch,
1215:       ...(locId ? { location_id: locId } : {}),
1216:       items: lines.map(l => ({ product_variant_id: l.variantId, adjustment_type: l.type, quantity: Number(toLatinDigits(l.qty)), reason: l.reason.trim() || null })),
1217:     };
1218:     try {
1219:       const res = await adjustmentsApi.create(payload, keyFor(payload));
1220:       reset(); // new key only after success
1221:       setConfirm(false); setLines([newAdjLine()]); setTried(false);
1222:       toast(res.message || `تم تنفيذ التسوية · ${lines.length} بند`);
1223:       go('moves', { branchId: effBranch });
1224:     } catch (e) {
1225:       const ne = normalizeError(e);
1226:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
1227:       // Server messages are Arabic — shown verbatim. 409 busy-lock keeps the
1228:       // dialog open so retry reuses the SAME key (no duplicate movement).
1229:       setSrvErr(ne.message);
1230:       setBusy(false);
1231:     }
1232:   };
1233: 
1234:   const totals = Object.keys(ADJ_API_TYPES).map(k => ({ k, n: lines.filter(l => l.type === k && l.variantId).length })).filter(x => x.n);
1235:   const shared = branchesQuery.data || [];
1236:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
1237:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1238:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1239:   const brName = shared.find(b => b.id === effBranch)?.name || '';
1240:   const locCode = (locsQuery.data || []).find(l => l.id === locId)?.code || '';
1241: 
1242:   return (
1243:     <section className="space-y-5">
1244:       <PageHead title="تسوية المخزون" back={{ label: 'أرصدة المخزون', onClick: () => go('stock') }}
1245:         sub="زيادة أو خصم كميات، أو نقلها من وإلى التالف. التسوية تُنفَّذ كعملية واحدة وتنعكس فورًا على الأرصدة والحركات." />
1246: 
1247:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1248:         <div className="lg:col-span-9 space-y-5">
1249:           <Card stagger={2}>
1250:             <CardHead title="بيانات العملية" />
1251:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
1252:               <Field label="الفرع / المخزن" req error={tried && !effBranch ? 'اختر الفرع' : rowErrs.branch_id}>
1253:                 <Sel value={effBranch} onChange={v => { if (!restriction.locked) { setBranchId(v || null); setLocId(null); } }} placeholder="اختر…" disabled={restriction.locked} options={branchOptions} className={tried && !effBranch ? 'err' : ''} />
1254:               </Field>
1255:               <Field label="موقع التخزين" hint="اختياري — يطبَّق على كل البنود" error={rowErrs.location_id}>
1256:                 <Sel value={locId} onChange={v => setLocId(v || null)} placeholder={effBranch ? 'بدون موقع محدد' : 'اختر الفرع أولًا'} disabled={!effBranch} options={locOptions} />
1257:               </Field>
1258:               <div>
1259:                 <span className="field-label">إدخال رصيد افتتاحي</span>
1260:                 <label className="v-subcard px-3.5 py-2 flex items-center justify-between cursor-pointer" style={{ borderRadius: 12 }}>
1261:                   <span className="text-[12px] c-secondary">كل البنود = زيادة</span>
1262:                   <Toggle on={opening} onChange={applyOpening} />
1263:                 </label>
1264:               </div>
1265:             </div>
1266:             {opening && <div className="mt-4"><InlineAlert kind="blue" icon="info" title="رصيد افتتاحي">تُسجَّل الكميات الافتتاحية حاليًا كتسوية زيادة. اكتب سببًا واضحًا لكل بند حتى يسهل تتبّعها في سجل الحركات.</InlineAlert></div>}
1267:           </Card>
1268: 
1269:           <Card stagger={3}>
1270:             <CardHead title="البنود" meta={<span className="num">{lines.length} / {ADJ_MAX}</span>}
1271:               right={<button className="btn btn-soft btn-sm" disabled={lines.length >= ADJ_MAX} onClick={() => setLines(ls => [...ls, newAdjLine(opening ? { reason: 'رصيد افتتاحي' } : {})])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1272:             {dupes > 0 && <div className="mb-3"><InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر بنفس SKU ونفس نوع التسوية — سيتم دمجها عند التنفيذ.</InlineAlert></div>}
1273:             <div className="overflow-x-auto">
1274:               <table className="vt">
1275:                 <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المنتج / المتغير</th><th style={{ minWidth: 170 }}>نوع التسوية</th><th style={{ minWidth: 120 }}>الكمية</th><th style={{ minWidth: 200 }}>السبب</th><th></th></tr></thead>
1276:                 <tbody>
1277:                   {lines.map((l, i) => {
1278:                     const e = { ...(tried ? clientErrs[i] : {}), ...(rowErrs[i] || {}) };
1279:                     return (
1280:                       <tr key={l.key} className="align-top">
1281:                         <td className="num c-muted pt-4">{i + 1}</td>
1282:                         <td>
1283:                           <div className={e.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1284:                           {e.product_variant_id && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.product_variant_id}</div>}
1285:                         </td>
1286:                         <td><Sel small value={l.type} onChange={v => upd(l.key, { type: v || 'increase' })} options={Object.entries(ADJ_API_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} /></td>
1287:                         <td>
1288:                           <NumInput small value={l.qty} onChange={v => upd(l.key, { qty: v })} err={e.qty || e.quantity} placeholder="0.0000" />
1289:                           {(e.qty || e.quantity) && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.qty || e.quantity}</div>}
1290:                         </td>
1291:                         <td><input maxLength={1000} className={`inp inp-sm ${e.reason ? 'err' : ''}`} value={l.reason} onChange={ev => upd(l.key, { reason: ev.target.value })} placeholder="مثال: كسر أثناء التفريغ" />
1292:                           {e.reason && typeof e.reason === 'string' && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.reason}</div>}</td>
1293:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1294:                       </tr>
1295:                     );
1296:                   })}
1297:                 </tbody>
1298:               </table>
1299:             </div>
1300:             <div className="mt-3 text-[11px] c-muted flex items-center gap-1.5"><Icon n="info" s={12} /> الكميات موجبة دائمًا وتقبل حتى 4 منازل عشرية. اتجاه الحركة يحدده نوع التسوية.</div>
1301:           </Card>
1302:         </div>
1303: 
1304:         <div className="lg:col-span-3 lg:sticky lg:top-5">
1305:           <Card stagger={4}>
1306:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">ملخص</h3>
1307:             <div className="space-y-2 text-[12.5px]">
1308:               <div className="flex justify-between"><span className="c-secondary">الفرع</span><span className="font-medium c-primary">{brName || '—'}</span></div>
1309:               <div className="flex justify-between"><span className="c-secondary">الموقع</span><span className="mono c-primary" dir="ltr">{locCode || '—'}</span></div>
1310:               <div className="flex justify-between"><span className="c-secondary">عدد البنود</span><span className="num font-semibold c-primary">{lines.length}</span></div>
1311:             </div>
1312:             <div className="h-px my-4" style={{ background: 'var(--divider-color)' }} />
1313:             <div className="space-y-1.5">
1314:               {totals.length === 0 && <div className="text-[11.5px] c-muted">لم يتم اختيار أصناف بعد</div>}
1315:               {totals.map(t => <div key={t.k} className="flex items-center justify-between"><Badge cls={ADJ_API_TYPES[t.k].cls}>{ADJ_API_TYPES[t.k].label}</Badge><span className="num text-[12px] c-primary font-semibold">{t.n}</span></div>)}
1316:             </div>
1317:             <div className="mt-5 space-y-2">
1318:               <button className="btn btn-orange w-full" onClick={() => { setTried(true); if (valid) { setSrvErr(null); setRowErrs({}); setConfirm(true); } }}>
1319:                 <Icon n="check" s={14} w={2.2} /> تنفيذ التسوية
1320:               </button>
1321:               <button className="btn btn-soft w-full" onClick={() => go('stock')}>إلغاء</button>
1322:             </div>
1323:             {tried && !valid && <div className="text-[11px] mt-3" style={{ color: 'var(--badge-red-text)' }}>أكمل الحقول المطلوبة المظللة بالأحمر.</div>}
1324:           </Card>
1325:         </div>
1326:       </div>
1327: 
1328:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={execute} busy={busy} error={srvErr}
1329:         title="تأكيد تنفيذ التسوية" confirmLabel="تنفيذ الآن"
1330:         body={<div className="space-y-3">
1331:           <p>سيتم تنفيذ <b className="c-primary num">{lines.length}</b> بند على <b className="c-primary">{brName}</b>{locCode && <> — موقع <span className="mono" dir="ltr">{locCode}</span></>}. لا يمكن تعديل أو حذف الحركات بعد التنفيذ؛ للتصحيح أنشئ تسوية عكسية.</p>
1332:           <div className="v-subcard p-3 space-y-1.5 max-h-40 overflow-y-auto">
1333:             {lines.filter(l => l.variantId).map((l, fi) => (
1334:               <div key={l.key}>
1335:                 <div className="flex items-center justify-between text-[12px]">
1336:                   <span className="flex items-center gap-2"><Sku>{variantCache.get(Number(l.variantId))?.sku || `#${l.variantId}`}</Sku><Badge cls={ADJ_API_TYPES[l.type].cls}>{ADJ_API_TYPES[l.type].label}</Badge></span>
1337:                   <span className="num font-semibold c-primary">{formatQty(toLatinDigits(l.qty))}</span>
1338:                 </div>
1339:                 {(rowErrs[fi]?.quantity || rowErrs[fi]?.product_variant_id) && <div className="text-[11px] mt-1 text-right" style={{ color: 'var(--badge-red-text)' }}>{rowErrs[fi]?.quantity || rowErrs[fi]?.product_variant_id}</div>}
1340:               </div>
1341:             ))}
1342:           </div>
1343:         </div>} />
1344:     </section>
1345:   );
1346: }
