1348: // ---------------- 5. Movements ----------------
1349: function MovesScreen({ go, params }) {
1350:   const { can, branchesQuery, variantCache } = useInv();
1351:   const [f, setF] = useState({ branchId: params.branchId ? Number(params.branchId) : null, locId: params.locationId ? Number(params.locationId) : null, variantId: params.variantId ? Number(params.variantId) : null, type: null, from: '', to: '' });
1352:   const [cursor, setCursor] = useState(null);
1353:   const [prevCursors, setPrevCursors] = useState([]);
1354:   const allowed = canAny(can, 'inventory.view');
1355:   const set = p => { setF(x => {
1356:     const next = { ...x, ...p };
1357:     if (next.from && next.to && next.to < next.from) next.to = next.from;
1358:     return next;
1359:   }); setCursor(null); setPrevCursors([]); };
1360:   const showCost = can('inventory.view_cost');
1361:   const restriction = useRestrictedBranch();
1362:   const effBranch = restriction.locked ? restriction.branchId : f.branchId;
1363: 
1364:   const apiParams = {
1365:     branch_id: effBranch || undefined, location_id: f.locId || undefined,
1366:     product_variant_id: f.variantId || undefined,
1367:     type: f.type || undefined, from_date: f.from || undefined, to_date: f.to || undefined,
1368:     per_page: 15, ...(cursor ? { cursor } : {}),
1369:   };
1370:   const query = useApi(signal => movementsApi.list(apiParams, signal), [JSON.stringify(apiParams)]);
1371:   const locsQuery = useBranchesWithLocations(effBranch);
1372: 
1373:   if (!allowed) return <NoPerm title="حركات المخزون" perm="inventory.view" go={go} />;
1374: 
1375:   const rows = query.data?.data || [];
1376:   const { phase, error } = apiPhase(query, rows.length === 0);
1377:   const onRetry = () => query.reload();
1378:   const shared = branchesQuery.data || [];
1379:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
1380:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1381:   const locOptions = (locsQuery.data || []).filter(l => l.is_active).map(l => ({ value: l.id, label: `${l.name} (${l.code})` }));
1382:   const active = (effBranch ? 1 : 0) + (f.locId ? 1 : 0) + (f.variantId ? 1 : 0) + (f.type ? 1 : 0) + (f.from ? 1 : 0) + (f.to ? 1 : 0);
1383:   const nextCursor = query.data?.meta?.next_cursor || null;
1384:   const prevCursor = query.data?.meta?.prev_cursor || null;
1385:   const goNext = () => { if (nextCursor) { setPrevCursors(p => [...p, cursor]); setCursor(nextCursor); } };
1386:   const goPrev = () => { const p = [...prevCursors]; const c = p.pop(); setPrevCursors(p); setCursor(prevCursor || c || null); };
1387: 
1388:   return (
1389:     <section className="space-y-5">
1390:       <PageHead title="حركات المخزون" sub="سجل غير قابل للتعديل لكل عملية أثّرت على الكميات." />
1391:       <Card stagger={2}>
1392:         <CardHead title="السجل" meta={<span className="flex items-center gap-1.5"><Icon n="lock" s={11} /> عرض فقط</span>}
1393:           right={!showCost && <span className="text-[11px] c-muted flex items-center gap-1"><Icon n="lock" s={11} /> تكلفة الوحدة مخفية حسب صلاحيتك</span>} />
1394:         <FilterBar active={active} onReset={() => { setF({ branchId: null, locId: null, variantId: null, type: null, from: '', to: '' }); setCursor(null); setPrevCursors([]); }}>
1395:           <FItem label="الفرع"><Sel small value={effBranch} onChange={v => set({ branchId: v || null, locId: null })} placeholder="كل الفروع" disabled={restriction.locked} options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1396:           <FItem label="الموقع" w="w-40"><Sel small value={f.locId} onChange={v => set({ locId: v || null })} placeholder={effBranch ? 'كل المواقع' : 'اختر فرعًا أولًا'} disabled={!effBranch} options={locOptions} className="!bg-[var(--bg-card)]" /></FItem>
1397:           <FItem label="الصنف / SKU" w="w-64"><VariantPicker small value={f.variantId} onChange={v => set({ variantId: v || null })} placeholder="كل الأصناف" allowClear /></FItem>
1398:           <FItem label="نوع الحركة" w="w-40"><Sel small value={f.type} onChange={v => set({ type: v || null })} placeholder="كل الأنواع" options={Object.entries(MOVE_TYPE_LABELS).map(([value, t]) => ({ value, label: t.ar }))} className="!bg-[var(--bg-card)]" /></FItem>
1399:           <FItem label="من تاريخ" w="w-36"><input type="date" value={f.from} onChange={e => set({ from: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1400:           <FItem label="إلى تاريخ" w="w-36"><input type="date" value={f.to} onChange={e => set({ to: e.target.value })} min={f.from || undefined} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1401:         </FilterBar>
1402: 
1403:         <Phase phase={phase} cols={9} rows={8} error={error} onRetry={onRetry}
1404:           empty={<EmptyState icon="history" title="لا توجد حركات بعد" sub="ستظهر هنا كل عمليات التسوية والتحويل والجرد واستلام الإنتاج بمجرد تنفيذها." />}>
1405:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد حركات تطابق الفلاتر" sub="وسّع نطاق التاريخ أو امسح بعض الفلاتر." /> : (
1406:             <>
1407:               <div className="overflow-x-auto">
1408:                 <table className="vt">
1409:                   <thead><tr>
1410:                     <th>التاريخ</th><th>المرجع</th><th>SKU</th><th>الفرع</th><th>الموقع</th><th>نوع الحركة</th>
1411:                     <th className="t-num">الكمية</th><th className="t-num">الرصيد قبل ← بعد</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}<th>المنفّذ</th><th>ملاحظات</th>
1412:                   </tr></thead>
1413:                   <tbody>
1414:                     {rows.map(m => {
1415:                       const t = MOVE_TYPE_LABELS[m.type] || { ar: m.type, cls: 'b-gray' };
1416:                       const qty = Number(m.quantity);
1417:                       return (
1418:                         <tr key={m.id}>
1419:                           <td className="num text-[11.5px] c-secondary">{formatDate(m.created_at, { includeTime: true })}</td>
1420:                           <td><span className="mono text-[11.5px] font-semibold c-orange" dir="ltr">{m.reference_number}</span></td>
1421:                           <td><div className="flex flex-col gap-0.5"><Sku>{m.variant?.sku || `#${m.product_variant_id}`}</Sku><span className="text-[10.5px] c-muted">{variantDisplayName(variantCache, m.product_variant_id, null)}</span></div></td>
1422:                           <td className="c-secondary">{m.branch?.name || '—'}</td>
1423:                           <td className="mono text-[11.5px] c-secondary" dir="ltr">{m.location?.name || '—'}</td>
1424:                           <td><Badge cls={t.cls}>{t.ar}</Badge></td>
1425:                           <td className="t-num num font-bold" style={{ color: qty > 0 ? 'var(--badge-green-text)' : qty < 0 ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{qty > 0 ? '+' : qty < 0 ? '−' : ''}{formatQty(Math.abs(qty))}</td>
1426:                           <td className="t-num num text-[12px]"><span className="c-muted">{formatQty(m.balance_before)}</span> <span className="c-muted mx-1">→</span> <span className="font-semibold c-primary">{formatQty(m.balance_after)}</span></td>
1427:                           {showCost && <td className="t-num num c-secondary">{m.unit_cost != null ? formatCurrency(m.unit_cost) : '—'}</td>}
1428:                           <td className="c-secondary">{m.creator_name || '—'}</td>
1429:                           <td className="text-[11.5px] c-muted max-w-[160px] truncate">{m.notes || '—'}</td>
1430:                         </tr>
1431:                       );
1432:                     })}
1433:                   </tbody>
1434:                 </table>
1435:               </div>
1436:               <div className="flex items-center justify-between mt-4 pt-4" style={{ borderTop: '1px solid var(--divider-color)' }}>
1437:                 <span className="text-[11.5px] c-muted">عرض <span className="num">{rows.length}</span> حركة · التنقل بالمؤشر</span>
1438:                 <div className="flex items-center gap-2">
1439:                   <button className="btn btn-soft btn-sm" disabled={!prevCursor && prevCursors.length === 0 && !cursor} onClick={goPrev}><Icon n="chevR" s={13} /> السابق</button>
1440:                   <button className="btn btn-dark btn-sm" disabled={!nextCursor} onClick={goNext}>التالي <Icon n="chevL" s={13} /></button>
1441:                 </div>
1442:               </div>
1443:             </>
1444:           )}
1445:         </Phase>
1446:       </Card>
1447:     </section>
1448:   );
1449: }
