1463: const TR_FLOW = ['draft', 'approved', 'shipped', 'received'];
1464: let __trKey = 1;
1465: const newTrLine = (p = {}) => ({ key: __trKey++, variantId: null, fromLoc: null, toLoc: null, req: '', ...p });
