1470: function TransfersScreen({ go }) {
1471:   const { can, branchesQuery } = useInv();
1472:   const [st, setSt] = useState('all');
1473:   const [q, setQ] = useState('');
1474:   const [fromF, setFromF] = useState(null);
1475:   const [toF, setToF] = useState(null);
1476:   const allowed = canAny(can, 'transfers.view', 'transfers.manage');
1477: 
1478:   // Small cardinality like branches: fetch all pages once (per_page=100) so the
1479:   // KPIs are exact and status/branch/search filters run client-side.
1480:   const query = useApi(signal => (async () => {
1481:     const all = []; let page = 1; let last = 1;
1482:     do {
1483:       const res = await transfersApi.list({ per_page: 100, page, from_branch_id: fromF || undefined, to_branch_id: toF || undefined, status: st === 'all' ? undefined : st }, signal);
1484:       all.push(...(res.data || [])); last = res.meta?.last_page || 1; page += 1;
1485:     } while (page <= last);
1486:     return all;
1487:   })(), [fromF, toF, st]);
1488: 
1489:   if (!allowed) return <NoPerm title="التحويلات المخزنية" perm="transfers.view" go={go} />;
1490: 
1491:   const list = query.data || [];
1492:   const { phase, error } = apiPhase(query, list.length === 0);
1493:   const onRetry = () => query.reload();
1494:   const ql = q.trim().toLowerCase();
1495:   const rows = list.filter(t => (st === 'all' || t.status === st)
1496:     && (!fromF || t.from_branch?.id === fromF) && (!toF || t.to_branch?.id === toF)
1497:     && (!ql || (t.transfer_number || '').toLowerCase().includes(ql)));
1498:   const cnt = k => list.filter(t => t.status === k).length;
1499:   const active = (fromF ? 1 : 0) + (toF ? 1 : 0) + (ql ? 1 : 0) + (st !== 'all' ? 1 : 0);
1500:   const shared = branchesQuery.data || [];
1501:   const branchOptions = shared.filter(b => b.is_active).map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
1502:   const canCreate = canAny(can, 'transfers.create', 'transfers.manage');
1503: 
1504:   return (
1505:     <section className="space-y-5">
1506:       <PageHead title="التحويلات المخزنية" sub="نقل البضاعة بين فرعين أو مخزنين عبر مراحل: مسودة ← اعتماد ← شحن ← استلام."
1507:         actions={canCreate && <button className="btn btn-dark" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={14} w={2.2} /> تحويل جديد</button>} />
1508: 
1509:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1510:         <KPI label="مسودات" icon="edit" value={phase === 'ready' ? cnt('draft') : '—'} sub="بانتظار الاعتماد" />
1511:         <KPI label="معتمدة" icon="check" value={phase === 'ready' ? cnt('approved') : '—'} sub="جاهزة للشحن" />
1512:         <KPI hot label="في الطريق" icon="truck" value={phase === 'ready' ? cnt('shipped') : '—'} sub="بانتظار الاستلام" />
1513:         <KPI label="مستلمة" icon="inbox" value={phase === 'ready' ? cnt('received') : '—'} sub="تحويلات مستلمة" />
1514:       </div>
1515: 
1516:       <Card stagger={3}>
1517:         <CardHead title="القائمة" right={<>
1518:           <div className="seg">
1519:             <button className={st === 'all' ? 'on' : ''} onClick={() => setSt('all')}>الكل</button>
1520:             {Object.entries(TRANSFER_STATUS).map(([k, t]) => <button key={k} className={st === k ? 'on' : ''} onClick={() => setSt(k)}>{t}</button>)}
1521:           </div>
1522:           <SearchPill value={q} onChange={setQ} placeholder="رقم التحويل" w="w-32" />
1523:         </>} />
1524:         <FilterBar active={active} onReset={() => { setFromF(null); setToF(null); setQ(''); setSt('all'); }}>
1525:           <FItem label="من فرع"><Sel small value={fromF} onChange={v => setFromF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1526:           <FItem label="إلى فرع"><Sel small value={toF} onChange={v => setToF(v || null)} placeholder="كل الفروع" options={branchOptions} className="!bg-[var(--bg-card)]" /></FItem>
1527:         </FilterBar>
1528:         <Phase phase={phase} cols={6} error={error} onRetry={onRetry}
1529:           empty={<EmptyState icon="swap" title="لا توجد تحويلات" sub="أنشئ أول تحويل لنقل الكميات من المخزن الرئيسي إلى الفروع."
1530:             action={canCreate && <button className="btn btn-dark btn-sm" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={13} /> تحويل جديد</button>} />}>
1531:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد تحويلات بهذه الحالة" /> : (
1532:             <table className="vt">
1533:               <thead><tr><th>رقم التحويل</th><th>المصدر ← الوجهة</th><th>التقدّم</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead>
1534:               <tbody>
1535:                 {rows.map(t => {
1536:                   const idx = TR_FLOW.indexOf(t.status);
1537:                   return (
1538:                     <tr key={t.id} className="cursor-pointer" onClick={() => go('transfer', { id: t.id })}>
1539:                       <td><span className="mono text-[12px] font-semibold c-primary" dir="ltr">{t.transfer_number}</span></td>
1540:                       <td>
1541:                         <div className="flex items-center gap-2">
1542:                           <span className="font-medium c-primary">{t.from_branch?.name || '—'}</span>
1543:                           <Icon n="arrowL" s={14} className="c-orange" />
1544:                           <span className="font-medium c-primary">{t.to_branch?.name || '—'}</span>
1545:                         </div>
1546:                       </td>
1547:                       <td>
1548:                         <div className="flex items-center gap-1 w-28">
1549:                           {TR_FLOW.slice(1).map((s, i) => <span key={s} className="h-1.5 flex-1 rounded-full" style={{ background: t.status === 'cancelled' ? 'var(--badge-red-bg)' : i < idx ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }} />)}
1550:                         </div>
1551:                       </td>
1552:                       <td><TrStatus s={t.status} /></td>
1553:                       <td className="num text-[11.5px] c-secondary">{formatDate(t.created_at)}</td>
1554:                       <td><Icon n="chevL" s={15} className="c-muted" /></td>
1555:                     </tr>
1556:                   );
1557:                 })}
1558:               </tbody>
1559:             </table>
1560:           )}
1561:         </Phase>
1562:       </Card>
1563:     </section>
1564:   );
1565: }
1566: // NOTE: the transfer list resource omits line items (TransferService::paginate
1567: // loads fromBranch/toBranch/creator only), so the old "items count" column was
1568: // dropped — the contract is the source of truth, not the mock.
1569: 
1570: function TransferEdit({ go, params }) {
1571:   const { toast, can, branchesQuery, variantCache } = useInv();
1572:   const restriction = useRestrictedBranch();
1573:   const { keyFor, reset } = useIdempotencyKey();
1574:   const editId = params.id ? Number(params.id) : null;
1575:   const [from, setFrom] = useState(restriction.locked ? restriction.branchId : null);
1576:   const [to, setTo] = useState(null);
1577:   const [note, setNote] = useState('');
1578:   const [lines, setLines] = useState(() => [newTrLine()]);
1579:   const [tried, setTried] = useState(false);
1580:   const [busy, setBusy] = useState(false);
1581:   const [srvErr, setSrvErr] = useState(null);
1582:   const [rowErrs, setRowErrs] = useState({});
1583:   const [loaded, setLoaded] = useState(!editId);
1584:   const allowed = editId ? canAny(can, 'transfers.update', 'transfers.manage') : canAny(can, 'transfers.create', 'transfers.manage');
1585: 
1586:   const showQuery = useApi(signal => (editId ? transfersApi.show(editId, signal) : Promise.resolve(null)), [editId || 0]);
1587:   useEffect(() => {
1588:     const t = showQuery.data;
1589:     if (editId && t && !loaded) {
1590:       setFrom(t.from_branch?.id ?? null); setTo(t.to_branch?.id ?? null); setNote(t.notes || '');
1591:       setLines((t.items || []).map(it => newTrLine({ variantId: it.product_variant_id, fromLoc: it.from_location?.id ?? null, toLoc: it.to_location?.id ?? null, req: it.requested_qty != null ? String(it.requested_qty) : '' })));
1592:       cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
1593:       setLoaded(true);
1594:     }
1595:   }, [showQuery.data]);
1596:   const fromLocsQuery = useBranchesWithLocations(from);
1597:   const toLocsQuery = useBranchesWithLocations(to);
1598: 
1599:   if (!allowed) return <NoPerm title={editId ? 'تعديل التحويل' : 'تحويل جديد'} perm={editId ? 'transfers.update' : 'transfers.create'} go={go} />;
1600: 
1601:   const t = showQuery.data;
1602:   const same = from && to && from === to;
1603:   const upd = (key, p) => { setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l)); setRowErrs({}); };
1604:   const lineBad = l => {
1605:     if (!l.variantId) return true;
1606:     const qv = toLatinDigits(l.req);
1607:     return !QTY_RE.test(qv) || !(Number(qv) > 0) || Number(qv) > QTY_MAX;
1608:   };
1609:   const valid = from && to && !same && lines.length && lines.length <= 100 && lines.every(l => !lineBad(l));
1610: 
1611:   const save = async () => {
1612:     setTried(true); if (!valid || busy || (editId && (!t || t.status !== 'draft'))) return;
1613:     setBusy(true); setSrvErr(null); setRowErrs({});
1614:     const payload = {
1615:       from_branch_id: from, to_branch_id: to, notes: note.trim() || null,
1616:       items: lines.map(l => ({
1617:         product_variant_id: l.variantId,
1618:         ...(l.fromLoc ? { from_location_id: l.fromLoc } : {}),
1619:         ...(l.toLoc ? { to_location_id: l.toLoc } : {}),
1620:         requested_qty: Number(toLatinDigits(l.req)),
1621:       })),
1622:     };
1623:     try {
1624:       if (editId) {
1625:         // PUT replaces items wholesale (TransferService::update) and is allowed in draft only.
1626:         await transfersApi.update(editId, payload);
1627:         toast('تم حفظ التعديلات'); go('transfer', { id: editId });
1628:       } else {
1629:         const res = await transfersApi.create(payload, keyFor(payload));
1630:         reset(); // new key only after success
1631:         toast(res.message || 'تم إنشاء التحويل بنجاح'); go('transfer', { id: res.data.id });
1632:       }
1633:     } catch (e) {
1634:       const ne = normalizeError(e);
1635:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
1636:       setSrvErr(ne.message);
1637:       setBusy(false);
1638:     }
1639:   };
1640: 
1641:   const shared = branchesQuery.data || [];
