1711:   const restriction = useRestrictedBranch();
1712:   const id = Number(params.id);
1713:   const [stage, setStage] = useState(null); // 'approve' | 'ship' | 'receive'
1714:   const [qtys, setQtys] = useState({});
1715:   const [confirm, setConfirm] = useState(null);
1716:   const [busy, setBusy] = useState(false);
1717:   const [err, setErr] = useState(null);
