1724:     cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
1725:     return t;
1726:   }), [id]);
1727: 
1728:   if (!canView) return <NoPerm title="تفاصيل التحويل" perm="transfers.view" go={go} />;
1729: 
1730:   const t = query.data;
1731:   const { phase, error } = apiPhase(query, !t);
1732:   const onRetry = () => { setConflict(null); query.reload(); };
1733: 
1734:   const stageMeta = {
1735:     approve: { col: 'approved_qty', srcCol: 'requested_qty', label: 'اعتماد', perm: 'transfers.approve', hint: 'حدّد الكمية المعتمدة لكل بند. البند الغائب يأخذ الكمية المطلوبة تلقائيًا.' },
1736:     ship:    { col: 'shipped_qty', srcCol: 'approved_qty', label: 'شحن', perm: 'transfers.ship', hint: 'أدخل الكمية المشحونة فعليًا. سيتم خصمها من المصدر وتظهر «قيد النقل».' },
1737:     receive: { col: 'received_qty', srcCol: 'shipped_qty', label: 'استلام', perm: 'transfers.receive', hint: 'أدخل الكمية المستلمة فعليًا في الوجهة. أي فرق يُسجَّل كعجز تحويل.' },
1738:   };
1739:   const startStage = s => { const m = stageMeta[s]; setStageErrors({}); setErr(null); setStage(s); setQtys(Object.fromEntries((t.items || []).map((l, i) => [i, String(l[m.srcCol] ?? '')]))); };
1740:   const idx = t ? TR_FLOW.indexOf(t.status) : -1;
1741: 
1742:   const stagePayload = () => {
1743:     const m = stageMeta[stage];
1744:     return {
1745:       expected_version: t.version,
1746:       items: (t.items || []).map((l, i) => ({ id: l.id, [m.col]: Number(toLatinDigits(qtys[i])) })),
1747:     };
1748:   };
1749:   const commit = async () => {
1750:     if (busy) return;
1751:     setBusy(true); setErr(null);
1752:     try {
1753:       const res = await transfersApi[stage](id, stagePayload());
1754:       setConfirm(null); setStage(null);
1755:       toast(res.message || `تم ${stageMeta[stage].label} التحويل`);
1756:       query.reload(); // the resource carries the new version
