1759:       setStageErrors(groupItemsErrors(ne.fields));
1760:       if (ne.status === 409) {
1761:         // Version conflict: reload first, never auto-resend.
1762:         setConfirm(null); setStage(null); setConflict(ne.message); setBusy(false); return;
1763:       }
1764:       setErr(ne.message);
1765:     }
1766:     setBusy(false);
1767:   };
1768:   const cancel = async () => {
