1770:     setBusy(true); setErr(null);
1771:     try {
1772:       const res = await transfersApi.cancel(id);
1773:       setConfirm(null); toast(res.message || 'تم إلغاء التحويل'); query.reload();
1774:     } catch (e) { setErr(normalizeError(e).message); }
1775:     setBusy(false);
1776:   };
1777:   const doDelete = async () => {
1778:     if (delBusy) return;
1779:     setDelBusy(true); setErr(null);
