1793:     }
1794:     if (t.status === 'approved' && canSend && can('transfers.ship')) actions.push(<button key="s" className="btn btn-dark" onClick={() => startStage('ship')}><Icon n="truck" s={14} /> شحن</button>);
1795:     if (t.status === 'shipped' && canReceive && can('transfers.receive')) actions.push(<button key="r" className="btn btn-orange" onClick={() => startStage('receive')}><Icon n="inbox" s={14} /> استلام</button>);
1796:     if (canSend && ['draft', 'approved'].includes(t.status) && canAny(can, 'transfers.update', 'transfers.manage')) actions.unshift(<button key="c" className="btn btn-danger" onClick={() => { setErr(null); setConfirm('cancel'); }}>إلغاء التحويل</button>);
1797:     if (canSend && t.status === 'draft' && canAny(can, 'transfers.delete', 'transfers.manage')) actions.push(<button key="d" className="btn btn-soft hover:!text-[var(--badge-red-text)]" disabled={delBusy} onClick={() => { setErr(null); setConfirm('delete'); }}><Icon n="trash" s={14} /> حذف</button>);
1798:   }
