1801:   const steps = [['draft', 'مسودة', 'edit'], ['approved', 'معتمد', 'check'], ['shipped', 'مشحون', 'truck'], ['received', 'مستلم', 'inbox']];
1802:   const shortage = stage === 'receive' && t ? (t.items || []).reduce((a, l, i) => a + (Number(l.shipped_qty || 0) - (Number(toLatinDigits(qtys[i])) || 0)), 0) : 0;
1803: 
1804:   return (
