1806:       <PageHead title={t ? <span className="mono" dir="ltr">{t.transfer_number}</span> : 'تفاصيل التحويل'} back={{ label: 'التحويلات المخزنية', onClick: () => go('transfers') }}
1807:         sub={t && <span className="flex items-center gap-2 flex-wrap">{t.from_branch?.name || '—'} <Icon n="arrowL" s={14} className="c-orange" /> {t.to_branch?.name || '—'} <span className="c-muted">·</span> <TrStatus s={t.status} /></span>}
1808:         actions={actions.length ? actions : nextNeedsPerm ? <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-subcard"><Icon n="lock" s={12} /> الخطوة التالية تتطلب صلاحية أخرى</span> : null} />
1809: 
1810:       {conflict && <InlineAlert kind="amber" title="تعارض — تم تعديل التحويل" onClose={() => setConflict(null)}>{conflict}<div className="mt-2"><button className="btn btn-dark btn-sm" onClick={onRetry}><Icon n="refresh" s={13} /> إعادة تحميل وراجعة الكميات</button></div></InlineAlert>}
1811: 
