1813:       <Phase phase={phase} cols={6} rows={3} error={error} onRetry={onRetry} onBack={() => go('transfers')} empty={<Card><EmptyState icon="swap" title="لا توجد بنود" /></Card>}>
1814:         {t && (<div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
