1832:                 </div>
1833:               )}
1834:             </Card>
1835: 
1836:             <Card stagger={3}>
1837:               <CardHead title="البنود" meta={stage ? `وضع ${stageMeta[stage].label}` : `${(t.items || []).length} بند`} />
