1868:                   <button className="btn btn-orange" onClick={() => {
1869:                     const m = stageMeta[stage];
1870:                     if ((t.items || []).some((l, i) => !QTY_RE.test(toLatinDigits(qtys[i])) || Number(toLatinDigits(qtys[i])) > Math.min(QTY_MAX, Number(l[m.srcCol])))) {
