1905:         title={stage ? `تأكيد ${stageMeta[stage].label} ${t?.transfer_number || ''}` : ''} confirmLabel="تأكيد"
1906:         body={<div className="space-y-2">
1907:           <p>{stage === 'ship' ? 'سيتم خصم الكميات المشحونة من رصيد المصدر وإضافتها كـ«قيد النقل» حتى يتم الاستلام.' : stage === 'receive' ? 'سيتم إضافة الكميات المستلمة إلى رصيد الوجهة وإغلاق التحويل.' : 'بعد الاعتماد لا يمكن تعديل بنود التحويل.'}</p>
1908:           {shortage > 0 && <InlineAlert kind="amber" title="يوجد عجز في الاستلام">الفرق بين المشحون والمستلم {formatQty(shortage)} — سيُسجَّل كعجز تحويل.</InlineAlert>}
1909:         </div>} />
1910:       <ConfirmDialog open={confirm === 'cancel'} onClose={() => setConfirm(null)} onConfirm={cancel} busy={busy} error={err} danger title="إلغاء التحويل؟" confirmLabel="إلغاء التحويل"
1911:         body={<>سيتم إلغاء <span className="mono c-primary" dir="ltr">{t?.transfer_number}</span> نهائيًا ولن يمكن إعادة تفعيله.</>} />
1912:       <ConfirmDialog open={confirm === 'delete'} onClose={() => setConfirm(null)} onConfirm={doDelete} busy={delBusy} error={err} danger title="حذف مسودة التحويل؟" confirmLabel="حذف نهائي"
1913:         body={<>سيتم حذف <span className="mono c-primary" dir="ltr">{t?.transfer_number}</span> نهائيًا. الحذف مسموح للمسودة فقط.</>} />
1914:     </section>
1915:   );
1916: }
