1924: // Dropdowns share successful location reads for this authenticated inventory
1925: // session. Branch/location writes invalidate the context cache before reloading.
1926: export function useBranchesWithLocations(branchId) {
1927:   const { branchesQuery, locationCache } = useInv();
1928:   const query = useApi(async signal => {
1929:     if (!branchId) return [];
1930:     if (locationCache.has(Number(branchId))) return locationCache.get(Number(branchId));
1931:     const rows = await fetchAllLocations(Number(branchId), signal);
1932:     if (!signal.aborted) locationCache.set(Number(branchId), rows);
1933:     return rows;
1934:   }, [branchId || 0, branchesQuery.data]);
1935:   return { ...query, branches: (branchesQuery.data || []).filter(b => b.is_active) };
1936: }
