1939: // ---------- Inventory API layer (Phases 1-2) ----------
1940: // All inventory screens are API-backed. Screens
1941: // use catalog/useApi + @alfarid/api-client with the shared context cache below.
1942: 
1943: // Branch-scoped users (branch_id set, not super admin, no inventory.all_branches)
1944: // are locked to their branch: the backend rejects anything else, and the UI
1945: // hides other branches from dropdowns and disables the branch switcher.
1946: function useRestrictedBranch() {
1947:   const user = useAuthStore(s => s.user);
1948:   const perms = user?.permissions;
1949:   const elevated = hasPermission(perms, 'inventory.all_branches')
1950:     || (user?.roles || []).includes('Super Admin');
1951:   const branchId = user?.branch_id ?? null;
1952:   if (branchId == null || elevated) return { branchId: null, locked: false };
1953:   return { branchId: Number(branchId), locked: true };
1954: }
