1956: // Variant name cache: list endpoints (movements/transfers/stocktakes) return SKU
1957: // only, so every variant seen from any source (options, StockLevel.variant) is
1958: // cached here and reused for display. Never one request per row.
1959: function cacheVariantNames(cache, list) {
1960:   (list || []).forEach(v => {
1961:     if (v && v.id != null) {
1962:       const old = cache.get(Number(v.id)) || {};
1963:       cache.set(Number(v.id), { ...old, name_ar: v.product_name_ar ?? v.name_ar ?? old.name_ar, name_en: v.product_name_en ?? v.name_en ?? old.name_en, sku: v.sku ?? old.sku });
1964:     }
1965:   });
1966: }
1967: function cacheVariantOptions(cache, options) {
1968:   options.forEach(v => {
1969:     const old = cache.get(Number(v.id)) || {};
1970:     const parts = (v.label || '').split(' / ');
1971:     const sku = parts.pop();
1972:     cache.set(Number(v.id), { ...old, label: v.label, name_ar: old.name_ar || parts.join(' / '), sku: old.sku || sku });
1973:   });
1974: }
1975: function variantDisplayName(cache, id, sku) {
1976:   const hit = cache.get(Number(id));
1977:   if (hit) return hit.name_ar || hit.name_en || hit.sku || sku || '—';
1978:   return sku || '—';
1979: }
