2230: // ---------- Variant picker: product → variant/SKU (never stops at product) ----------
2231: // API-backed (Phase 3): GET production-receipts/options?search=, 300ms debounce,
2232: // max 50 active variants. Empty query shows "اكتب للبحث", never a fake full list.
2233: // Disabled variants are rejected by the server on input, so their absence here
2234: // is correct; to decrease a disabled variant, open stock → adjust with variantId.
2235: function VariantPicker({ value, onChange, placeholder = 'ابحث بالاسم أو SKU أو الباركود', small, exclude = [], allowClear }) {
2236:   const { variantCache } = useInv();
2237:   const [open, setOpen] = useState(false);
2238:   const [q, setQ] = useState('');
2239:   const [dq, setDq] = useState('');
2240:   const ref = useRef();
