 54:     public function update(UpdateBranchRequest $request, Branch $branch): BranchResource
 55:     {
 56:         app(BranchAccess::class)->assertCentralAccess($request->user());
 57:         DB::transaction(function () use ($request, $branch): void {
 58:             $locked = Branch::query()->lockForUpdate()->findOrFail($branch->id);
 59:             if (array_key_exists('is_active', $request->validated()) && ! $request->boolean('is_active') && (
 60:                 StockLevel::query()->where('branch_id', $locked->id)->where('in_transit', '>', 0)->exists()
 61:                 || StockTransfer::query()->where('to_branch_id', $locked->id)->where('status', 'shipped')->exists()
 62:             )) {
 63:                 throw new BusinessException('لا يمكن تعطيل الفرع قبل استلام التحويلات المشحونة إليه.');
 64:             }
