 77:     public function destroy(Request $request, Branch $branch): JsonResponse|Response
 78:     {
 79:         app(BranchAccess::class)->assertCentralAccess($request->user());
 80: 
 81:         try {
 82:             $deleted = DB::transaction(function () use ($branch): bool {
 83:                 $lockedBranch = Branch::query()
 84:                     ->whereKey($branch->getKey())
 85:                     ->lockForUpdate()
 86:                     ->firstOrFail();
 87: 
 88:                 if ($lockedBranch->users()->exists()) {
 89:                     return false;
 90:                 }
 91: 
 92:                 // L3: ضمان الـ FK يكفي للدفتر — بلا مسح Schema في كل طلب.
 93:                 // كل حركات التطبيق تحمل branch_id، وحركات المواقع تُمسك
 94:                 // أيضًا بضمان FK عند حذف الموقع تباعًا.
 95:                 $hasMovements = DB::table('stock_movements')
 96:                     ->where('branch_id', $lockedBranch->getKey())
 97:                     ->exists();
 98:                 if ($hasMovements) {
 99:                     return false;
100:                 }
101: 
102:                 // L3: الصفرية تُنظَّف (حذف الفرع يحذف مواقعه تباعًا)، وغير
103:                 // الصفرية تُرفض برسالة مفهومة بدل 409 مبهم.
104:                 $hasBalances = StockLevel::query()->where('branch_id', $lockedBranch->getKey())
105:                     ->hasNonZeroBalance()
106:                     ->exists();
107:                 if ($hasBalances) {
108:                     throw new BusinessException('لا يمكن حذف الفرع وفيه أرصدة (متاح/محجوز/تالف/في الطريق)؛ صفّرها أولًا.');
109:                 }
110:                 StockLevel::query()->where('branch_id', $lockedBranch->getKey())->delete();
111: 
112:                 $lockedBranch->delete();
113: 
114:                 return true;
115:             });
116:         } catch (QueryException $exception) {
117:             if (! $this->isIntegrityConstraintViolation($exception)) {
118:                 throw $exception;
119:             }
120: 
121:             return $this->conflictResponse();
122:         }
123: 
124:         if (! $deleted) {
125:             return $this->conflictResponse();
126:         }
127: 
128:         return response()->noContent();
129:     }
130: 
131:     private function isIntegrityConstraintViolation(QueryException $exception): bool
132:     {
133:         $sqlState = (string) ($exception->errorInfo[0] ?? $exception->getCode());
134: 
135:         return in_array($sqlState, ['23000', '23503'], true);
136:     }
