 29:     public function store(Request $request): JsonResponse
 30:     {
 31:         $data = $request->validate([
 32:             'items' => ['required', 'array', 'min:1', 'max:100'],
 33:             'items.*.product_variant_id' => ['required', 'integer', 'min:1'],
 34:             'items.*.qty' => ['required', 'integer', 'min:1', 'max:9999'],
 35:             'items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
 36:             'items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
 37:             'customer_id' => ['nullable', 'integer', 'min:1'],
 38:             'payment_method' => ['nullable', 'string', 'in:cash,card,mixed'],
 39:             'cash_amount' => ['nullable', 'numeric', 'min:0'],
 40:             'card_amount' => ['nullable', 'numeric', 'min:0'],
 41:             'override_price' => ['nullable', 'boolean'],
 42:             'notes' => ['nullable', 'string', 'max:500'],
 43:         ]);
 44: 
 45:         /** @var PosShift $shift */
 46:         $shift = $request->attributes->get('pos_shift');
 47: 
 48:         // التحقق من صلاحية تجاوز السعر
 49:         if (! empty($data['override_price'])) {
 50:             $user = $request->user('staff');
 51:             if (! $user->can('pos.override_price')) {
 52:                 return response()->json(['message' => 'لا تملك صلاحية تجاوز سعر البيع.'], 403);
 53:             }
 54:         }
 55: 
 56:         $order = app(OperationIdempotencyService::class)->run(
 57:             'pos_sale', $request->user('staff'), $this->requiredIdempotencyKey($request),
 58:             ['shift_id' => $shift->id, ...$data], fn () => $this->pos->createSale($shift, $data),
 59:         );
 60: 
 61:         return response()->json([
 62:             'message' => 'تم تسجيل البيع بنجاح.',
 63:             'data' => $this->formatOrder($order),
 64:         ], 201);
