135:     /**
136:      * POST /pos/sales/{id}/exchange — استبدال من فاتورة POS.
137:      */
138:     public function processExchange(Request $request, Order $sale): JsonResponse
139:     {
140:         $data = $request->validate([
141:             'returned_items' => ['required', 'array', 'min:1'],
142:             'returned_items.*.product_variant_id' => ['required', 'integer', 'min:1'],
143:             'returned_items.*.qty' => ['required', 'integer', 'min:1'],
144:             'returned_items.*.return_to' => ['nullable', 'string', 'in:on_hand,damaged'],
145:             'exchange_items' => ['required', 'array', 'min:1'],
146:             'exchange_items.*.product_variant_id' => ['required', 'integer', 'min:1'],
147:             'exchange_items.*.qty' => ['required', 'integer', 'min:1'],
148:             'exchange_items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
149:             'exchange_items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
150:             'cash_amount' => ['nullable', 'numeric', 'min:0'],
151:             'card_amount' => ['nullable', 'numeric', 'min:0'],
152:         ]);
153: 
154:         /** @var PosShift $shift */
155:         $shift = $request->attributes->get('pos_shift');
156: 
157:         $sale->load('items');
158: 
159:         // C2: الاستبدال = مرتجع مستقل ثم بيع مستقل بمبالغه الخاصة.
160:         $exchangePayload = [
161:             'items' => $data['exchange_items'],
162:             'customer_id' => $sale->customer_id,
163:         ];
164:         if (array_key_exists('cash_amount', $data)) {
165:             $exchangePayload['cash_amount'] = $data['cash_amount'];
166:         }
167:         if (array_key_exists('card_amount', $data)) {
168:             $exchangePayload['card_amount'] = $data['card_amount'];
169:         }
170:         $result = DB::transaction(function () use ($shift, $sale, $data, $exchangePayload): array {
171:             $result = $this->pos->processReturn($shift, $sale, $data['returned_items']);
172:             $exchangeOrder = $this->pos->createSale($shift, $exchangePayload);
173:             $result['exchange_order_id'] = $exchangeOrder->id;
174: 
175:             return $result;
176:         }, 3);
177: 
178:         return response()->json([
179:             'message' => 'تم تسجيل الاستبدال بنجاح.',
180:             'data' => $result,
181:         ]);
182:     }
