30:             || ($user->status === CustomerStatus::Rejected && ! $canInspectRejection)) {
31:             return response()->json([
32:                 'message' => 'غير مصرح لك بالدخول كعميل.',
33:             ], 403);
34:         }
35: 
36:         return $next($request);
37:     }
