 5: namespace App\Services\Auth;
 6: 
 7: use App\Models\User;
 8: use Illuminate\Contracts\Cache\LockTimeoutException;
 9: use Illuminate\Support\Facades\Cache;
10: use Illuminate\Support\Str;
11: 
12: final class StaffHandoffService
13: {
14:     private const TTL_SECONDS = 60;
15: 
16:     public function issue(User $user): string
17:     {
18:         $code = Str::random(64);
19:         Cache::put($this->key($code), ['user_id' => $user->id, 'credentials' => self::credentialFingerprint($user)], now()->addSeconds(self::TTL_SECONDS));
20: 
21:         return $code;
22:     }
23: 
24:     public static function credentialFingerprint(User $user): string
25:     {
26:         return hash_hmac('sha256', json_encode([$user->id, $user->email, $user->password], JSON_THROW_ON_ERROR), (string) config('app.key'));
27:     }
28: 
29:     /** @return array{user_id:int, credentials:string}|null */
30:     public function consume(string $code): ?array
31:     {
32:         // Cache::pull alone is a read followed by delete on database/Redis stores.
33:         // Serialize consumers so concurrent exchanges cannot issue two tokens.
34:         // M8: block() يرمي LockTimeoutException لو تعذّر القفل (تزامن/بطء) —
35:         // تُعامل ككود مستهلك (null) في الكنترولر بدل 500.
36:         try {
37:             return Cache::lock($this->key($code).':lock', 10)
38:                 ->block(5, fn (): ?array => Cache::pull($this->key($code)));
39:         } catch (LockTimeoutException $exception) {
40:             report($exception);
41: 
42:             return null;
43:         }
44:     }
45: 
46:     private function key(string $code): string
47:     {
48:         return 'auth:handoff:'.hash('sha256', $code);
49:     }
50: } 1: <?php
