12: /**
13:  * نطاق الفروع للموظفين — Fail-Closed:
14:  * الوصول لكل الفروع امتياز صريح (Super Admin أو صلاحية inventory.all_branches)،
15:  * والموظف المرتبط بفرع محصور فيه، ومن لا فرع له ولا امتياز يُرفض بدل أن يرى كل شيء.
16:  */
17: class BranchAccess
18: {
19:     /** @var array<int, User> ذاكرة لكل طلب حتى لا يُعاد تحميل المستخدم مع كل فحص. */
20:     private array $usersById = [];
21: 
22:     public function restrictedBranch(?User $user): ?int
23:     {
24:         if ($user === null) {
25:             throw new AuthorizationException;
26:         }
27: 
28:         if ($user->hasRole(StaffRole::SuperAdmin->value, 'staff') || $user->can('inventory.all_branches')) {
29:             return null;
30:         }
31: 
32:         if ($user->branch_id !== null) {
33:             return (int) $user->branch_id;
34:         }
35: 
36:         throw new AuthorizationException('حسابك غير مرتبط بأي فرع ولا تملك صلاحية الوصول لكل الفروع (inventory.all_branches).');
37:     }
38: 
39:     public function assertBranch(int $userId, int ...$branchIds): void
40:     {
41:         $branchId = $this->restrictedBranch($this->usersById[$userId] ??= User::findOrFail($userId));
42:         if ($branchId !== null && ! in_array($branchId, $branchIds, true)) {
43:             throw new AuthorizationException('لا تملك صلاحية الوصول إلى هذا الفرع.');
44:         }
45:     }
46: 
47:     public function assertCentralAccess(?User $user): void
48:     {
49:         if ($this->restrictedBranch($user) !== null) {
50:             throw new AuthorizationException('هذه العملية المركزية تتطلب صلاحية الوصول لكل الفروع.');
51:         }
52:     }
53: 
54:     public function assertTreasury(int $userId, Treasury $treasury): void
55:     {
56:         if ($treasury->branch_id === null) {
57:             $this->assertCentralAccess(User::findOrFail($userId));
58:         } else {
59:             $this->assertBranch($userId, (int) $treasury->branch_id);
60:         }
61:     }
