 32: /**
 33:  * محرك نقطة البيع — كل عملية POS تمر من هنا.
 34:  *
 35:  * القاعدة الذهبية: الكاشير لا يُنفذ أي عملية بلا وردية مفتوحة في فرعه.
 36:  * البيع يخصم من on_hand فوراً (لا حجز مؤقت كالأونلاين).
 37:  */
 38: class PosService
 39: {
 40:     public function __construct(
 41:         private readonly InventoryService $inventory,
 42:         private readonly PricingService $pricing,
 43:         private readonly TreasuryService $treasury,
 44:         private readonly SettingService $settings,
 45:     ) {}
 46: 
 47:     // ===================================================================
