 51:     /**
 52:      * فتح وردية جديدة للكاشير.
 53:      */
 54:     public function openShift(User $user, int $branchId, int $treasuryId, float $openingCash): PosShift
 55:     {
 56:         return DB::transaction(function () use ($user, $branchId, $treasuryId, $openingCash): PosShift {
 57:             app(BranchAccess::class)->assertBranch($user->id, $branchId);
 58:             User::query()->whereKey($user->id)->lockForUpdate()->firstOrFail();
 59:             if (! is_finite($openingCash) || $openingCash < 0) {
 60:                 throw new BusinessException('العهدة النقدية غير صالحة.');
 61:             }
 62:             // التحقق من عدم وجود وردية مفتوحة لنفس الكاشير
 63:             $existingUserShift = PosShift::query()
 64:                 ->where('user_id', $user->id)
 65:                 ->where('status', PosShiftStatus::Open)
 66:                 ->lockForUpdate()
 67:                 ->exists();
 68: 
 69:             if ($existingUserShift) {
 70:                 throw new BusinessException('لديك وردية مفتوحة بالفعل. أغلقها أولًا قبل فتح وردية جديدة.');
 71:             }
 72: 
 73:             // التحقق من عدم وجود وردية مفتوحة على نفس الدرج
 74:             $existingDrawerShift = PosShift::query()
 75:                 ->where('treasury_id', $treasuryId)
 76:                 ->where('status', PosShiftStatus::Open)
 77:                 ->lockForUpdate()
 78:                 ->exists();
 79: 
 80:             if ($existingDrawerShift) {
 81:                 throw new BusinessException('درج النقدية المحدد مفتوح على وردية أخرى.');
 82:             }
 83: 
 84:             // التحقق أن الخزينة تتبع الفرع وهي من نوع درج
 85:             $treasury = Treasury::query()
 86:                 ->where('id', $treasuryId)
 87:                 ->where('branch_id', $branchId)
 88:                 ->where('type', 'pos_drawer')
 89:                 ->where('is_active', true)
 90:                 ->firstOrFail();
 91: 
 92:             $mainSafe = Treasury::query()->where('branch_id', $branchId)->where('type', 'main_safe')->where('is_active', true)->orderBy('id')->first();
 93:             $treasuries = $this->treasury->lockTreasuries(array_filter([$treasury->id, $mainSafe?->id]));
 94:             $treasury = $treasuries->get($treasury->id);
 95:             if (PosShift::query()->where('treasury_id', $treasuryId)->whereIn('status', [PosShiftStatus::Open, PosShiftStatus::ClosedPendingApproval])->exists()) {
 96:                 throw new BusinessException('الدرج مرتبط بوردية مفتوحة أو تنتظر الاعتماد.');
 97:             }
 98:             $existingCash = $this->minor($treasury->current_balance);
 99:             $openingCents = $this->minor($openingCash);
100:             if ($existingCash !== 0 && $existingCash !== $openingCents) {
101:                 throw new BusinessException('العهدة لا تطابق رصيد الدرج القائم؛ سوِّ الرصيد قبل فتح الوردية.');
102:             }
103:             if ($existingCash === 0 && $openingCents > 0 && $mainSafe === null) {
104:                 throw new BusinessException('يلزم وجود خزنة رئيسية لتمويل عهدة الوردية.');
105:             }
106: 
107:             $shiftNumber = $this->settings->generateNextNumber('shift');
108: 
109:             $shift = PosShift::create([
110:                 'shift_number' => $shiftNumber,
111:                 'user_id' => $user->id,
112:                 'branch_id' => $branchId,
113:                 'treasury_id' => $treasuryId,
114:                 'status' => PosShiftStatus::Open,
115:                 'opened_at' => now(),
116:                 'opening_cash' => $openingCash,
117:                 'cash_sales_total' => 0,
118:                 'card_sales_total' => 0,
119:                 'cash_returns_total' => 0,
120:                 'cash_expenses_total' => 0,
121:                 'expected_closing_cash' => $openingCash,
122:             ]);
123: 
124:             // Fund the float from an existing safe; never mint new drawer cash.
125:             if ($existingCash === 0 && $openingCents > 0) {
126:                 $this->treasury->record([
127:                     'treasury_id' => $mainSafe->id, 'shift_id' => $shift->id,
128:                     'type' => TreasuryTransactionType::TransferOut, 'amount' => -$openingCash,
129:                     'reference_type' => PosShift::class, 'reference_id' => $shift->id,
130:                     'created_by' => $user->id, 'notes' => 'تمويل عهدة الوردية '.$shiftNumber,
131:                 ]);
132:                 $this->treasury->record([
133:                     'treasury_id' => $treasury->id,
134:                     'shift_id' => $shift->id,
135:                     'type' => TreasuryTransactionType::OpeningBalance,
136:                     'amount' => $openingCash,
137:                     'reference_type' => PosShift::class,
138:                     'reference_id' => $shift->id,
139:                     'created_by' => $user->id,
140:                     'notes' => "رصيد فتح وردية #{$shiftNumber}",
141:                 ]);
142:             }
143: 
144:             return $shift;
145:         });
146:     }
147: 
148:     /**
149:      * إغلاق الوردية بعد عدّ الكاشير للنقدية.
150:      *
151:      * expected_closing_cash = opening_cash + cash_sales - cash_returns - cash_expenses
152:      * cash_difference = actual - expected
153:      */
154:     public function closeShift(PosShift $shift, float $actualCash, ?string $notes): PosShift
155:     {
156:         if ($shift->status !== PosShiftStatus::Open) {
157:             throw new BusinessException('يمكن إغلاق الورديات المفتوحة فقط.');
158:         }
159: 
160:         return DB::transaction(function () use ($shift, $actualCash, $notes): PosShift {
161:             $shift = $this->lockOpenShift($shift);
162:             if (! is_finite($actualCash) || $actualCash < 0) {
163:                 throw new BusinessException('النقدية الفعلية غير صالحة.');
164:             }
165:             // إعادة حساب مجاميع الوردية من بيانات الطلبات الفعلية
166:             $salesStats = Order::query()
167:                 ->where('pos_shift_id', $shift->id)
168:                 ->where('status', OrderStatus::Delivered)
169:                 ->selectRaw('
170:                     COALESCE(SUM(cash_amount), 0) AS cash_sales,
171:                     COALESCE(SUM(card_amount), 0) AS card_sales
172:                 ')
173:                 ->first();
174: 
175:             $cashSales = (float) ($salesStats?->cash_sales ?? 0);
176:             $cardSales = (float) ($salesStats?->card_sales ?? 0);
177: 
178:             $cashReturns = (float) Order::query()
179:                 ->where('pos_shift_id', $shift->id)
180:                 ->where('status', OrderStatus::Returned)
181:                 ->sum('cash_amount');
182: 
183:             $cashExpenses = (float) Expense::query()
184:                 ->where('shift_id', $shift->id)
185:                 ->sum('amount');
186: 
187:             $expectedClosingCash = (float) $shift->opening_cash
188:                 + $cashSales
189:                 - $cashReturns
190:                 - $cashExpenses;
191: 
192:             $cashDifference = $actualCash - $expectedClosingCash;
193: 
194:             $shift->update([
195:                 'status' => PosShiftStatus::ClosedPendingApproval,
196:                 'closed_at' => now(),
197:                 'cash_sales_total' => $cashSales,
198:                 'card_sales_total' => $cardSales,
199:                 'cash_returns_total' => $cashReturns,
200:                 'cash_expenses_total' => $cashExpenses,
201:                 'expected_closing_cash' => $expectedClosingCash,
202:                 'actual_closing_cash' => $actualCash,
203:                 'cash_difference' => $cashDifference,
204:                 'notes' => $notes,
205:             ]);
206: 
207:             return $shift->fresh();
208:         });
209:     }
210: 
211:     /**
212:      * الاعتماد الإداري للوردية المغلقة وترحيل النقدية للخزنة الرئيسية.
213:      */
214:     public function approveShift(PosShift $shift, User $approver): PosShift
215:     {
216:         if ($shift->status !== PosShiftStatus::ClosedPendingApproval) {
217:             throw new BusinessException('يمكن اعتماد الورديات المغلقة المنتظرة للاعتماد فقط.');
218:         }
219: 
220:         return DB::transaction(function () use ($shift, $approver): PosShift {
221:             $shift = PosShift::query()->lockForUpdate()->findOrFail($shift->id);
222:             app(BranchAccess::class)->assertBranch($approver->id, $shift->branch_id);
223:             if ($shift->status !== PosShiftStatus::ClosedPendingApproval) {
224:                 throw new BusinessException('الوردية ليست في انتظار الاعتماد.');
225:             }
226:             $shift->update([
227:                 'status' => PosShiftStatus::Approved,
228:                 'approved_at' => now(),
229:                 'approved_by' => $approver->id,
230:             ]);
231: 
232:             // ترحيل النقدية من الدرج إلى الخزنة الرئيسية
233:             $this->treasury->settleShiftToMainSafe($shift, $approver->id);
234: 
235:             return $shift->fresh();
236:         });
237:     }
238: 
239:     // ===================================================================
240:     //  البيع
241:     // ===================================================================
242: 
243:     /**
244:      * إنشاء فاتورة بيع POS مع الخصم الفوري من المخزن.
245:      *
246:      * @param  array{
247:      *     items: array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>,
248:      *     customer_id?: int|null,
249:      *     payment_method?: string,
250:      *     cash_amount?: float,
251:      *     card_amount?: float,
252:      *     notes?: string|null,
253:      *     override_price?: bool,
254:      * }  $payload
255:      */
256:     public function createSale(PosShift $shift, array $payload): Order
257:     {
258:         if ($shift->status !== PosShiftStatus::Open) {
259:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي بيع.');
260:         }
261: 
262:         return DB::transaction(function () use ($shift, $payload): Order {
263:             $shift = $this->lockOpenShift($shift);
264:             $actor = User::findOrFail($shift->user_id);
265:             if (! empty($payload['override_price']) && ! $actor->can('pos.override_price')) {
266:                 throw new AuthorizationException('لا تملك صلاحية تجاوز سعر البيع.');
267:             }
268:             if (collect($payload['items'])->contains(fn ($item) => (float) ($item['discount_amount'] ?? 0) > 0) && ! $actor->can('pos.discount')) {
269:                 throw new AuthorizationException('لا تملك صلاحية تطبيق خصم يدوي.');
270:             }
271:             $stockRows = StockLevel::query()->where('branch_id', $shift->branch_id)
272:                 ->whereIn('product_variant_id', array_column($payload['items'], 'product_variant_id'))
273:                 ->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)))
274:                 ->get(['branch_id', 'location_id', 'product_variant_id']);
275:             $levels = $this->inventory->lockLevels($stockRows->map->getAttributes()->all());
276:             $customer = isset($payload['customer_id'])
277:                 ? Customer::find($payload['customer_id'])
278:                 : null;
279: 
280:             $overridePrice = (bool) ($payload['override_price'] ?? false);
281:             $items = $this->resolveItems($shift, $payload['items'], $customer, $overridePrice);
282: 
283:             // C1: subtotal إجمالي قبل الخصم، والإجمالي هو مجموع line_total (الصافي).
284:             // line_total محسوب في resolveItems كـ round(unit*qty - discount).
285:             $subtotal = $items->sum(fn ($item) => $this->minor($item['unit_price']) * (int) $item['qty']) / 100;
286:             $discountTotal = $items->sum(fn ($item) => $this->minor($item['discount_amount'])) / 100;
287:             $grandTotal = $items->sum(fn ($item) => $this->minor($item['line_total'])) / 100;
288: 
289:             if ($grandTotal < 0) {
290:                 throw new BusinessException('إجمالي الفاتورة لا يمكن أن يكون سالبًا.');
291:             }
292: 
293:             // التحقق من الدفع المختلط — M10: لا مبالغ سالبة، ومطابقة بالقروش الصحيحة
294:             $cashAmount = (float) ($payload['cash_amount'] ?? $grandTotal);
295:             $cardAmount = (float) ($payload['card_amount'] ?? 0);
296: 
297:             if ($cashAmount < 0 || $cardAmount < 0) {
298:                 throw new BusinessException('مبالغ الدفع يجب ألا تكون سالبة.');
299:             }
300: 
301:             $grandCents = $this->minor($grandTotal);
302:             $paidCents = $this->minor($cashAmount) + $this->minor($cardAmount);
303: 
304:             if ($paidCents !== $grandCents) {
305:                 throw new BusinessException('مجموع المبالغ (نقدي + بطاقة) لا يساوي إجمالي الفاتورة.');
306:             }
307: 
308:             // توليد رقم الطلب بنفس آلية الـ order_next_number
309:             $orderNumber = $this->settings->generateNextNumber('order');
310: 
311:             // إنشاء الطلب بحالة delivered مباشرة (POS = تسليم فوري)
312:             $order = Order::create([
313:                 'order_number' => $orderNumber,
314:                 'channel' => 'pos',
315:                 'customer_id' => $customer?->id,
316:                 'allocated_branch_id' => $shift->branch_id,
317:                 'pos_shift_id' => $shift->id,
318:                 'status' => OrderStatus::Delivered,
319:                 'payment_method' => $payload['payment_method'] ?? 'mixed',
320:                 'payment_status' => 'paid',
321:                 'subtotal' => $subtotal,
322:                 'discount_amount' => $discountTotal,
323:                 'shipping_cost' => 0,
324:                 'tax_amount' => 0,
325:                 'grand_total' => $grandTotal,
326:                 'cash_amount' => $cashAmount,
327:                 'card_amount' => $cardAmount,
328:             ]);
329: 
330:             // إنشاء عناصر الطلب وخصم المخزون فوراً
331:             foreach ($items as $item) {
332:                 OrderItem::create([
333:                     'order_id' => $order->id,
334:                     'product_variant_id' => $item['product_variant_id'],
335:                     'product_name_snapshot' => $item['product_name_snapshot'],
336:                     'sku_snapshot' => $item['sku_snapshot'],
337:                     'allocated_branch_id' => $shift->branch_id,
338:                     'qty' => $item['qty'],
339:                     'unit_price' => $item['unit_price'],
340:                     'discount_amount' => $item['discount_amount'],
341:                     'line_total' => $item['line_total'],
342:                 ]);
343: 
344:                 $remaining = (int) round((float) $item['qty'] * 10000);
345:                 foreach ($levels->where('product_variant_id', $item['product_variant_id']) as $level) {
346:                     $take = min($remaining, (int) round($level->available * 10000));
347:                     if ($take <= 0) {
348:                         continue;
349:                     }
350:                     $this->inventory->recordMovement([
351:                         'product_variant_id' => $item['product_variant_id'],
352:                         'branch_id' => $shift->branch_id,
353:                         'location_id' => $level->location_id,
354:                         'type' => StockMovementType::Sale,
355:                         'affected_bucket' => StockBucket::OnHand,
356:                         'quantity' => -$take / 10000,
357:                         'unit_cost' => $item['unit_cost'],
358:                         'reference_type' => Order::class,
359:                         'reference_id' => $order->id,
360:                         'created_by' => $shift->user_id,
361:                         'notes' => "بيع POS #{$orderNumber}",
362:                     ], $level);
363:                     $remaining -= $take;
364:                 }
365:                 if ($remaining > 0) {
366:                     throw new BusinessException('الرصيد المتاح تغير؛ أعد مراجعة الكميات.');
367:                 }
368:             }
369: 
370:             // تسجيل تاريخ الحالة
371:             OrderStatusHistory::create([
372:                 'order_id' => $order->id,
373:                 'from_status' => null,
374:                 'to_status' => OrderStatus::Delivered,
375:                 'changed_by_type' => User::class,
376:                 'changed_by_id' => $shift->user_id,
377:                 'notes' => 'بيع POS مباشر',
378:             ]);
379: 
380:             // تسجيل المقبوضة النقدية في الخزينة
381:             if ($cashAmount > 0) {
382:                 $this->treasury->record([
383:                     'treasury_id' => $shift->treasury_id,
384:                     'shift_id' => $shift->id,
385:                     'type' => TreasuryTransactionType::PosSale,
386:                     'amount' => $cashAmount,
387:                     'reference_type' => Order::class,
388:                     'reference_id' => $order->id,
389:                     'created_by' => $shift->user_id,
390:                     'notes' => "مبيعات نقدية POS #{$orderNumber}",
391:                 ]);
392:             }
393: 
394:             return $order->load(['items.variant', 'customer']);
395:         });
396:     }
397: 
398:     /**
399:      * مرتجع كلي أو جزئي من فاتورة POS.
400:      * يُعيد البضاعة إلى on_hand ويرد النقدية من الدرج إن كانت مدفوعة نقداً.
401:      *
402:      * @param  array<array{product_variant_id: int, qty: int, return_to?: string}>  $returnedItems
403:      * @param  array<array{product_variant_id: int, qty: int}>  $exchangeItems  (للاستبدال)
404:      */
405:     public function processReturn(
406:         PosShift $shift,
407:         Order $originalOrder,
408:         array $returnedItems,
409:         array $exchangeItems = []
410:     ): array {
411:         if ($shift->status !== PosShiftStatus::Open) {
412:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي مرتجع.');
413:         }
414: 
415:         if ($originalOrder->channel !== 'pos') {
416:             throw new BusinessException('يمكن مرتجع طلبات POS فقط من شاشة الـ POS.');
417:         }
418: 
419:         return DB::transaction(function () use ($shift, $originalOrder, $returnedItems, $exchangeItems): array {
420:             $shift = $this->lockOpenShift($shift);
421:             // C2: قفل الطلب الأصلي أولًا حتى تتسلسل المرتجعات المتزامنة عليه.
422:             /** @var Order $originalOrder */
423:             $originalOrder = Order::query()->lockForUpdate()->findOrFail($originalOrder->id);
424:             $originalOrder->load('items');
425:             app(BranchAccess::class)->assertBranch($shift->user_id, (int) $originalOrder->allocated_branch_id);
426:             if ($originalOrder->channel !== 'pos') {
427:                 throw new BusinessException('يمكن مرتجع طلبات POS فقط من شاشة الـ POS.');
428:             }
429: 
430:             if ($originalOrder->status !== OrderStatus::Delivered) {
431:                 throw new BusinessException('المرتجع متاح لطلبات POS المسلمة فقط.');
432:             }
433: 
434:             // C2: طلبات المرتجع نفسها حالتها Returned — منع "إرجاع المرتجع".
435:             // (الحالة Delivered إلزامية أعلاه، وهذا تأكيد دفاعي + عمود الربط بعد المايجريشن.)
436:             if ($originalOrder->getAttribute('return_of_order_id') !== null) {
437:                 throw new BusinessException('لا يمكن إرجاع طلب مرتجع.');
438:             }
439: 
440:             // C2: إزالة مسار الاستبدال المحسوب داخليًا (كان يفشل دائمًا).
441:             // الاستبدال عملية بيع مستقلة يرسلها العميل بمبالغها.
442:             if (! empty($exchangeItems)) {
443:                 throw new BusinessException('الاستبدال يتم كعملية بيع مستقلة بعد المرتجع، وليس ضمن نفس الطلب.');
444:             }
445: 
446:             $returnValue = 0.0;
447:             $returnOrderId = null;
448: 
449:             // ===== معالجة الأصناف المرتجعة =====
450:             if (! empty($returnedItems)) {
451:                 // C2: تجميع الأسطر المكررة لنفس المتغير قبل أي فحص.
452:                 $grouped = [];
453:                 foreach ($returnedItems as $ret) {
454:                     $vid = (int) $ret['product_variant_id'];
455:                     $qty = (float) $ret['qty'];
456:                     if (! is_finite($qty) || $qty <= 0 || floor($qty) !== $qty) {
457:                         throw new BusinessException('كمية المرتجع يجب أن تكون موجبة.');
458:                     }
459:                     $destination = $ret['return_to'] ?? 'on_hand';
460:                     if (! in_array($destination, ['on_hand', 'damaged'], true)
461:                         || (isset($grouped[$vid]) && $grouped[$vid]['return_to'] !== $destination)) {
462:                         throw new BusinessException('حدد حالة واحدة صحيحة لكل صنف مرتجع.');
463:                     }
464:                     if (! isset($grouped[$vid])) {
465:                         $grouped[$vid] = ['qty' => 0.0, 'return_to' => $ret['return_to'] ?? 'on_hand'];
466:                     }
467:                     $grouped[$vid]['qty'] += $qty;
468:                 }
469: 
470:                 $previousQuantities = StockMovement::query()
471:                     ->whereIn('reference_type', array_unique([$originalOrder->getMorphClass(), Order::class]))
472:                     ->where('reference_id', $originalOrder->id)->where('type', StockMovementType::SaleReturn)
473:                     ->selectRaw('product_variant_id, SUM(quantity) AS qty')->groupBy('product_variant_id')->pluck('qty', 'product_variant_id');
474:                 $previousRefunds = DB::table('order_items as ri')->join('orders as ro', 'ro.id', '=', 'ri.order_id')
475:                     ->where('ro.return_of_order_id', $originalOrder->id)
476:                     ->selectRaw('ri.product_variant_id, SUM(ri.qty) AS qty, SUM(ri.line_total) AS amount')
477:                     ->groupBy('ri.product_variant_id')->get()->keyBy('product_variant_id');
478:                 foreach ($previousQuantities as $variantId => $quantity) {
479:                     if ((float) $quantity > (float) ($previousRefunds->get($variantId)?->qty ?? 0) + 0.00001) {
480:                         // Legacy unlinked refunds have no reliable cash/card attribution.
481:                         // Never guess their payment split or pay the same quantity twice.
482:                         throw new BusinessException('للفاتورة مرتجعات تاريخية غير مرتبطة؛ راجع ربط مستندات الرد بالأصل قبل رد مبلغ جديد.', [], 409);
483:                     }
484:                 }
485: 
486:                 $lines = [];
487:                 foreach ($grouped as $variantId => $g) {
488:                     // C2: كل سطور الطلب الأصلي لنفس المتغير (وليس firstWhere فقط).
489:                     $matching = $originalOrder->items->where('product_variant_id', $variantId);
490:                     if ($matching->isEmpty()) {
491:                         throw new BusinessException("الصنف {$variantId} غير موجود في الطلب الأصلي.");
492:                     }
493: 
494:                     $soldQty = (float) $matching->sum('qty');
495:                     $soldNet = round((float) $matching->sum('line_total'), 2);
496:                     $netUnit = $soldQty > 0 ? $soldNet / $soldQty : 0.0;
497: 
498:                     // C2: الكميات المرتجعة سابقًا من دفتر الحركات (مصدر الحقيقة قبل مايجريشن returned_qty).
499:                     $alreadyReturned = (float) $previousQuantities->get($variantId, 0);
500: 
501:                     $remaining = $soldQty - $alreadyReturned;
502:                     if ($g['qty'] > $remaining + 1e-9) {
503:                         throw new BusinessException("كمية المرتجع ({$g['qty']}) تتجاوز المتبقي القابل للإرجاع ({$remaining}).");
504:                     }
505: 
506:                     // C2: الرد بالسعر الصافي (line_total/qty) لا بسعر الوحدة قبل الخصم.
507:                     $previousRefund = $previousRefunds->get($variantId)?->amount ?? 0;
508:                     $targetCents = (int) round(($alreadyReturned + $g['qty']) * $this->minor($soldNet) / $soldQty);
509:                     $lineRefund = max(0, min($this->minor($soldNet), $targetCents) - $this->minor($previousRefund)) / 100;
510:                     $returnValue = round($returnValue + $lineRefund, 2);
511: 
512:                     $first = $matching->first();
513:                     $lines[$variantId] = [
514:                         'qty' => $g['qty'],
515:                         'return_to' => $g['return_to'],
516:                         'net_unit' => $netUnit,
517:                         'line_refund' => $lineRefund,
518:                         'product_name_snapshot' => $first->product_name_snapshot,
519:                         'sku_snapshot' => $first->sku_snapshot,
520:                     ];
521:                 }
522: 
523:                 if ($returnValue < 0) {
524:                     throw new BusinessException('قيمة المرتجع لا يمكن أن تكون سالبة.');
525:                 }
526: 
527:                 // C2: سقف الرد النقدي = النقد المدفوع في الأصل ناقص ما رُد سابقًا.
528:                 $previousCashRefunded = 0.0;
529:                 $previousCashRefunded = (float) Order::withTrashed()
530:                     ->where('return_of_order_id', $originalOrder->id)
531:                     ->sum('cash_amount');
532:                 $maxCashRefund = round((float) $originalOrder->cash_amount - $previousCashRefunded, 2);
533:                 $cashRefund = min($returnValue, max(0.0, $maxCashRefund));
534: 
535:                 $locationId = $this->inventory->receivingLocation((int) $shift->branch_id);
536:                 $levels = $this->inventory->lockLevels(array_map(fn ($variantId) => [
537:                     'product_variant_id' => $variantId, 'branch_id' => $shift->branch_id, 'location_id' => $locationId,
538:                 ], array_keys($lines)));
539: 
540:                 foreach ($lines as $variantId => $line) {
541:                     $base = [
542:                         'product_variant_id' => $variantId,
543:                         'branch_id' => $shift->branch_id,
544:                         'location_id' => $locationId,
545:                         'type' => StockMovementType::SaleReturn,
546:                         'affected_bucket' => StockBucket::OnHand,
547:                         'quantity' => $line['qty'],
548:                         'reference_type' => Order::class,
549:                         'reference_id' => $originalOrder->id,
550:                         'created_by' => $shift->user_id,
551:                         'notes' => "مرتجع POS من #{$originalOrder->order_number}",
552:                     ];
553:                     $level = $levels->get($this->inventory->levelKey($base));
554:                     $saleCost = StockMovement::query()->whereIn('reference_type', array_unique([$originalOrder->getMorphClass(), Order::class]))
555:                         ->where('reference_id', $originalOrder->id)->where('product_variant_id', $variantId)->where('type', 'sale')->value('unit_cost');
556:                     $this->inventory->recordMovement([...$base, 'unit_cost' => $saleCost], $level);
557:                     if ($line['return_to'] === 'damaged') {
558:                         $this->inventory->recordMovement([...$base, 'type' => StockMovementType::Damage, 'affected_bucket' => StockBucket::Damaged], $level);
559:                     }
560:                 }
561: 
562:                 // إنشاء طلب مرتجع مرتبط بالأصل
563:                 $returnOrderNumber = $this->settings->generateNextNumber('order');
564:                 $returnAttrs = [
565:                     'order_number' => $returnOrderNumber,
566:                     'channel' => 'pos',
567:                     'customer_id' => $originalOrder->customer_id,
568:                     'allocated_branch_id' => $shift->branch_id,
569:                     'pos_shift_id' => $shift->id,
570:                     'status' => OrderStatus::Returned,
571:                     'payment_method' => $originalOrder->payment_method,
572:                     'payment_status' => 'refunded',
573:                     'subtotal' => $returnValue,
574:                     'discount_amount' => 0,
575:                     'shipping_cost' => 0,
576:                     'tax_amount' => 0,
577:                     'grand_total' => $returnValue,
578:                     'cash_amount' => $cashRefund,
579:                     'card_amount' => round($returnValue - $cashRefund, 2),
580:                 ];
581:                 $returnAttrs['return_of_order_id'] = $originalOrder->id;
582:                 $returnAttrs['requires_refund'] = $returnAttrs['card_amount'] > 0;
583:                 $returnAttrs['payment_status'] = $returnAttrs['card_amount'] > 0 ? 'refund_pending' : 'refunded';
584:                 $returnOrder = Order::create($returnAttrs);
585: 
586:                 foreach ($lines as $variantId => $line) {
587:                     OrderItem::create([
588:                         'order_id' => $returnOrder->id,
589:                         'product_variant_id' => $variantId,
590:                         'product_name_snapshot' => $line['product_name_snapshot'],
591:                         'sku_snapshot' => $line['sku_snapshot'],
592:                         'allocated_branch_id' => $shift->branch_id,
593:                         'qty' => $line['qty'],
594:                         'unit_price' => round($line['net_unit'], 2),
595:                         'discount_amount' => 0,
596:                         'line_total' => $line['line_refund'],
597:                     ]);
598:                 }
599: 
600:                 foreach ($grouped as $variantId => $g) {
601:                     // Reconcile counters from the ledger as well as this return, including legacy returns.
602:                     $remaining = (float) StockMovement::query()
603:                         ->whereIn('reference_type', array_unique([$originalOrder->getMorphClass(), Order::class]))
604:                         ->where('reference_id', $originalOrder->id)->where('type', StockMovementType::SaleReturn)
605:                         ->where('product_variant_id', $variantId)->sum('quantity');
606:                     foreach ($originalOrder->items->where('product_variant_id', $variantId)->sortBy('id') as $item) {
607:                         $take = min($remaining, (float) $item->qty);
608:                         $item->update(['returned_qty' => $take]);
609:                         $remaining -= $take;
610:                     }
611:                 }
612: 
613:                 OrderStatusHistory::create([
614:                     'order_id' => $returnOrder->id,
615:                     'from_status' => null,
616:                     'to_status' => OrderStatus::Returned,
617:                     'changed_by_type' => User::class,
618:                     'changed_by_id' => $shift->user_id,
619:                     'notes' => "مرتجع من #{$originalOrder->order_number}",
620:                 ]);
621: 
622:                 // رد النقدية للعميل من الدرج (مكبوتة بسقف النقد المدفوع)
623:                 if ($cashRefund > 0) {
624:                     $this->treasury->record([
625:                         'treasury_id' => $shift->treasury_id,
626:                         'shift_id' => $shift->id,
627:                         'type' => TreasuryTransactionType::PosReturn,
628:                         'amount' => -$cashRefund,
629:                         'reference_type' => Order::class,
630:                         'reference_id' => $returnOrder->id,
631:                         'created_by' => $shift->user_id,
632:                         'notes' => "رد مرتجع #{$returnOrderNumber}",
633:                     ]);
634:                 }
635: 
636:                 $returnOrderId = $returnOrder->id;
637:             }
638: 
639:             return [
640:                 'return_order_id' => $returnOrderId,
641:                 'exchange_order_id' => null,
642:                 'refund_amount' => $returnValue,
643:             ];
644:         });
645:     }
