651:     public function holdSale(PosShift $shift, array $payload): PosHeldSale
652:     {
653:         return PosHeldSale::create([
654:             'hold_reference' => 'HOLD-'.strtoupper(Str::random(8)),
655:             'branch_id' => $shift->branch_id,
656:             'user_id' => $shift->user_id,
657:             'customer_id' => $payload['customer_id'] ?? null,
658:             'items_payload' => $payload['items'],
659:             'notes' => $payload['notes'] ?? null,
660:             'created_at' => now(),
661:         ]);
