664:     // ===================================================================
665:     //  البحث السريع عن المنتجات
666:     // ===================================================================
667: 
668:     /**
669:      * بحث فائق السرعة بالباركود أو SKU أو جزء من الاسم.
670:      * يرجع المتغير مع رصيده في الفرع الحالي فقط وسعره.
671:      *
672:      * @return array<int, array<string, mixed>>
673:      */
674:     public function lookupProducts(string $query, int $branchId, ?Customer $customer = null): array
675:     {
676:         $variants = ProductVariant::query()
677:             ->with(['product', 'media'])
678:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->whereNotNull('published_at'))
679:             ->where('is_active', true)
680:             ->where(function ($q) use ($query): void {
681:                 $q->where('barcode', $query)
682:                     ->orWhere('sku', $query)
683:                     ->orWhereHas('product', fn ($pq) => $pq->whereRaw('LOWER(name_ar) LIKE ? OR LOWER(name_en) LIKE ?', ['%'.mb_strtolower($query).'%', '%'.mb_strtolower($query).'%']));
684:             })
685:             ->limit(20)
686:             ->get();
687: 
688:         $result = [];
689:         foreach ($variants as $variant) {
690:             $stock = StockLevel::query()
691:                 ->where('product_variant_id', $variant->id)
692:                 ->where('branch_id', $branchId)
693:                 ->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)))
694:                 ->get();
695: 
696:             try {
697:                 $priceData = $this->pricing->resolve($variant, $customer, 1, $branchId);
698:             } catch (\Throwable) {
699:                 $priceData = ['unit_price' => null, 'source' => 'unpriced', 'price_list_id' => null];
700:             }
701: 
702:             $result[] = [
703:                 'id' => $variant->id,
704:                 'sku' => $variant->sku,
705:                 'barcode' => $variant->barcode,
706:                 'product_name' => $variant->product->name_ar ?? $variant->product->name_en,
707:                 'variant_name' => $variant->color_name_ar ?? $variant->color_name_en,
708:                 'on_hand' => (float) $stock->sum('on_hand'),
709:                 'available' => (float) $stock->sum('available'),
710:                 'unit_price' => $priceData['unit_price'],
711:                 'price_source' => $priceData['source'],
712:                 'price_list_id' => $priceData['price_list_id'],
713:             ];
714:         }
715: 
716:         return $result;
717:     }
718: 
719:     // ===================================================================
720:     //  المساعدات الداخلية
721:     // ===================================================================
722: 
723:     /**
724:      * تجهيز عناصر الفاتورة مع حل الأسعار.
725:      *
726:      * @param  array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>  $rawItems
727:      * @return Collection<int, array<string, mixed>>
728:      */
729:     private function resolveItems(
730:         PosShift $shift,
731:         array $rawItems,
732:         ?Customer $customer,
733:         bool $overridePrice
734:     ): Collection {
735:         return collect($rawItems)->map(function (array $item) use ($shift, $customer, $overridePrice): array {
736:             $qty = (float) $item['qty'];
737:             if (! is_finite($qty) || $qty <= 0 || floor($qty) !== $qty) {
738:                 throw new BusinessException('كمية البيع يجب أن تكون عددًا صحيحًا موجبًا.');
739:             }
740:             /** @var ProductVariant $variant */
741:             $variant = ProductVariant::query()
742:                 ->where('id', $item['product_variant_id'])
743:                 ->where('is_active', true)
744:                 ->firstOrFail();
745: 
746:             // التحقق من المخزون المتاح في الفرع
747:             $stock = StockLevel::query()
748:                 ->where('product_variant_id', $variant->id)
749:                 ->where('branch_id', $shift->branch_id)
750:                 ->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)))
751:                 ->get();
752: 
753:             $available = (float) $stock->sum('available');
754: 
755:             if ($available < $item['qty']) {
756:                 throw new BusinessException(
757:                     "الكمية المتاحة للصنف [{$variant->sku}] في الفرع هي {$available} فقط.",
758:                     status: 422,
759:                 );
760:             }
761: 
762:             // السعر: يدوي (بشرط الصلاحية) أو محسوب
763:             if ($overridePrice && isset($item['unit_price'])) {
764:                 $unitPrice = (float) $item['unit_price'];
765:             } else {
766:                 $priceData = $this->pricing->resolve($variant, $customer, (float) $item['qty'], $shift->branch_id);
767:                 $unitPrice = (float) $priceData['unit_price'];
768:             }
769: 
770:             if (! is_finite($unitPrice) || $unitPrice < 0) {
771:                 throw new BusinessException("سعر الصنف [{$variant->sku}] لا يمكن أن يكون سالبًا.");
772:             }
773: 
774:             $discount = (float) ($item['discount_amount'] ?? 0);
775:             $maxDiscount = (float) config('inventory.pos_max_discount_percent', 100);
776:             if ($discount > round($unitPrice * (float) $item['qty'] * $maxDiscount / 100, 2)) {
777:                 throw new BusinessException('الخصم يتجاوز النسبة القصوى المسموحة.');
778:             }
779:             if (! is_finite($discount) || $discount < 0) {
780:                 throw new BusinessException("خصم الصنف [{$variant->sku}] لا يمكن أن يكون سالبًا.");
781:             }
782:             $lineTotal = round($unitPrice * $item['qty'] - $discount, 2);
783: 
784:             if ($lineTotal < 0) {
785:                 throw new BusinessException("إجمالي السطر للصنف [{$variant->sku}] لا يمكن أن يكون سالبًا.");
786:             }
787: 
788:             return [
789:                 'product_variant_id' => $variant->id,
790:                 'product_name_snapshot' => $variant->product->name_ar ?? $variant->product->name_en ?? 'POS Item',
791:                 'sku_snapshot' => $variant->sku,
792:                 'qty' => $item['qty'],
793:                 'unit_price' => $unitPrice,
794:                 'discount_amount' => $discount,
795:                 'line_total' => $lineTotal,
796:                 'unit_cost' => $variant->cost_price,
797:             ];
798:         });
799:     }
