801:     /**
802:      * تسجيل مصروف من درج الوردية الحالية.
803:      */
804:     public function recordExpense(PosShift $shift, array $data, int $userId): Expense
805:     {
806:         if ($shift->status !== PosShiftStatus::Open) {
807:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن تسجيل مصاريف.');
808:         }
809: 
810:         return DB::transaction(function () use ($shift, $data, $userId): Expense {
811:             $shift = $this->lockOpenShift($shift);
812:             $expenseNumber = $this->settings->generateNextNumber('expense');
813: 
814:             $expense = Expense::create([
815:                 'expense_number' => $expenseNumber,
816:                 'branch_id' => $shift->branch_id,
817:                 'treasury_id' => $shift->treasury_id,
818:                 'shift_id' => $shift->id,
819:                 'category' => $data['category'],
820:                 'amount' => $data['amount'],
821:                 'expense_date' => $data['expense_date'] ?? today(),
822:                 'attachment_path' => $data['attachment_path'] ?? null,
823:                 'notes' => $data['notes'] ?? null,
824:                 'created_by' => $userId,
825:             ]);
826: 
827:             // خصم من الخزينة
828:             $this->treasury->record([
829:                 'treasury_id' => $shift->treasury_id,
830:                 'shift_id' => $shift->id,
831:                 'type' => TreasuryTransactionType::Expense,
832:                 'amount' => -(float) $data['amount'],
833:                 'reference_type' => Expense::class,
834:                 'reference_id' => $expense->id,
835:                 'created_by' => $userId,
836:                 'notes' => "مصروف: {$data['category']} #{$expenseNumber}",
837:             ]);
838: 
839:             return $expense;
840:         });
841:     }
842: 
843:     private function lockOpenShift(PosShift $shift): PosShift
844:     {
845:         $shift = PosShift::query()->lockForUpdate()->findOrFail($shift->id);
846:         if ($shift->status !== PosShiftStatus::Open) {
847:             throw new BusinessException('الوردية غير مفتوحة.');
848:         }
849: 
850:         return $shift;
851:     }
852: 
853:     private function minor(mixed $value): int
854:     {
855:         try {
856:             return BigDecimal::of((string) $value)->toScale(2, RoundingMode::Unnecessary)->getUnscaledValue()->toInt();
857:         } catch (\Throwable) {
858:             throw new BusinessException('المبلغ المالي غير صالح؛ يُسمح بخانتين عشريتين فقط.');
859:         }
860:     }
