21: class ProductionReceiptController extends Controller implements HasMiddleware
22: {
23:     public static function middleware(): array
24:     {
25:         return [
26:             new Middleware('can:inventory.view', only: ['options', 'index']),
27:         ];
28:     }
29: 
30:     public function options(Request $request): JsonResponse
31:     {
32:         $filters = $request->validate(['search' => ['nullable', 'string', 'max:100']]);
33:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
34:         $branches = Branch::where('is_active', true)->when($branch, fn ($q) => $q->whereKey($branch))
35:             ->with(['locations' => fn ($q) => $q->where('is_active', true)])->orderBy('id')->get();
36:         $variants = ProductVariant::where('is_active', true)->whereHas('product')
37:             ->with('product:id,name_ar')->when($filters['search'] ?? null, function ($q, $search): void {
38:                 $pattern = SearchTerm::pattern($search);
39:                 $q->where(fn ($q) => $q->whereLike('sku', $pattern)->orWhereLike('barcode', $pattern)
40:                     ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern)->orWhereLike('name_en', $pattern)));
41:             })->orderBy('id')->limit(50)->get();
42: 
43:         return response()->json(['data' => [
44:             'branches' => $branches->map(fn ($b) => ['id' => $b->id, 'name' => $b->name,
45:                 'locations' => $b->locations->map(fn ($l) => ['id' => $l->id, 'name' => $l->name])]),
46:             'variants' => $variants->map(fn ($v) => ['id' => $v->id, 'label' => $v->product->name_ar.' / '.$v->sku]),
47:         ]]);
48:     }
49: 
50:     public function index(Request $request): JsonResponse
51:     {
52:         $filters = $request->validate(['per_page' => ['nullable', 'integer', 'min:1', 'max:100']]);
53:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
54:         $receipts = ProductionReceipt::query()->when($branch, fn ($q) => $q->where('branch_id', $branch))
55:             ->orderByDesc('id')->paginate($filters['per_page'] ?? 15);
56:         if (! CostAccess::canView($request->user())) {
57:             $receipts->getCollection()->each(function ($receipt): void {
58:                 $receipt->items = array_map(function ($item) {
59:                     unset($item['unit_cost']);
60: 
61:                     return $item;
62:                 }, $receipt->items);
63:             });
64:         }
65: 
66:         return response()->json($receipts);
67:     }
68: 
69:     public function store(StoreProductionReceiptRequest $request, ProductionReceiptService $service): JsonResponse
70:     {
71:         $key = $this->idempotencyKey($request);
72:         abort_if($key === null, 422, 'مفتاح Idempotency-Key مطلوب لاستلام الإنتاج.');
73:         $receipt = $service->receive($request->validated(), $request->user()->id, $key);
74: 
75:         return response()->json(['message' => 'تم استلام الإنتاج وإضافة الكميات للمخزون.', 'data' => $receipt], 201);
76:     }
77: }  1: <?php
