211:     /** معرّف مستخدم النظام منفّذًا لحركات مخزون العميل (نفس اصطلاح OrderService). */
212:     private function systemActorId(): ?int
213:     {
214:         $id = User::query()
215:             ->where('is_system', true)
216:             ->value('id');
217: 
218:         return $id !== null ? (int) $id : null;
219:     }
220: 
221:     /**
222:      * توزيع مبلغ على بنود بأوزان مالية بطريقة أكبر باقٍ (بالقروش) — مجموع
223:      * الحصص يساوي المبلغ بالضبط ولا تقع حصة سالبة.
224:      *
225:      * @param  list<float>  $weights
226:      * @return list<float>
227:      */
228:     private function distributeLargestRemainder(float $amount, array $weights): array
229:     {
230:         $count = count($weights);
231:         $totalCents = (int) round($amount * 100);
232:         $totalWeight = array_sum($weights);
233: 
234:         if ($count === 0 || $totalCents === 0 || $totalWeight <= 0) {
235:             return array_fill(0, $count, 0.0);
236:         }
237: 
238:         $shares = [];
239:         $remainders = [];
240:         $allocated = 0;
241:         foreach ($weights as $i => $weight) {
242:             $exact = $totalCents * $weight / $totalWeight;
243:             $floor = (int) floor($exact);
244:             $shares[$i] = $floor;
245:             $remainders[$i] = $exact - $floor;
246:             $allocated += $floor;
247:         }
248: 
249:         $order = array_keys($remainders);
250:         usort($order, fn (int $a, int $b): int => $remainders[$b] <=> $remainders[$a]);
251:         for ($k = 0; $k < $totalCents - $allocated; $k++) {
252:             $shares[$order[$k % $count]]++;
253:         }
254: 
255:         return array_map(fn (int $cents): float => $cents / 100, $shares);
256:     }
