 18: final class UnifiedAuthService
 19: {
 20:     public function __construct(private readonly CustomerAuthService $customerAuth) {}
 21: 
 22:     public function attempt(string $login, string $password): User|SupplierUser|Customer
 23:     {
 24:         $identifier = str_contains($login, '@') ? mb_strtolower(trim($login)) : Customer::normalizePhone($login);
 25:         $key = 'unified-login:failures:'.hash_hmac('sha256', $identifier, (string) config('app.key'));
 26:         $ipKey = 'unified-login:ip-failures:'.hash_hmac('sha256', (string) request()->ip(), (string) config('app.key'));
 27:         $pairKey = $key.':ip:'.hash('sha256', (string) request()->ip()).':hour';
 28:         $dayKey = $key.':day';
 29:         $staff = str_contains($identifier, '@') ? User::query()->whereRaw('LOWER(email) = ?', [$identifier])->first() : null;
 30:         $dayLimit = max(1, (int) config('auth.unified_login_failures_day', 1000));
 31:         $pairLimit = max(1, (int) config('auth.unified_login_failures_hour', 10));
 32:         $ipLimit = max(1, (int) config('auth.unified_login_ip_failures_hour', 1000));
 33:         if (RateLimiter::tooManyAttempts($pairKey, $pairLimit)) {
 34:             throw new TooManyRequestsHttpException(RateLimiter::availableIn($pairKey), 'محاولات دخول كثيرة؛ حاول لاحقًا.');
 35:         }
 36:         $broadLimitReached = RateLimiter::tooManyAttempts($ipKey, $ipLimit)
 37:             || RateLimiter::tooManyAttempts($dayKey, $dayLimit);
 38:         try {
 39:             $actor = $this->resolve($identifier, $password, $staff);
 40:         } catch (BusinessException $exception) {
 41:             if ($exception->status === 401) {
 42:                 RateLimiter::hit($pairKey, 3600);
 43:                 if (RateLimiter::hit($ipKey, 3600) === $ipLimit) {
 44:                     app(AuthenticationAlerts::class)->report('ip_failures', $staff?->id);
 45:                 }
 46:                 if (RateLimiter::hit($dayKey, 86400) === $dayLimit) {
 47:                     app(AuthenticationAlerts::class)->report('identifier_failures', $staff?->id);
 48:                 }
 49:                 // Broad quotas must not lock out valid credentials behind NAT or CGNAT.
 50:                 if ($broadLimitReached) {
 51:                     throw new TooManyRequestsHttpException(60, 'محاولات دخول كثيرة؛ حاول لاحقًا.');
 52:                 }
 53:             }
 54:             throw $exception;
 55:         }
 56:         RateLimiter::clear($pairKey);
 57: 
 58:         return $actor;
 59:     }
 60: 
 61:     private function resolve(string $login, string $password, ?User $staff = null): User|SupplierUser|Customer
 62:     {
 63:         $login = trim($login);
 64: 
 65:         if (str_contains($login, '@')) {
 66:             $email = mb_strtolower($login);
 67: 
 68:             // H3: bcrypt واحدة ثابتة لكل محاولة بالبريد — نجلب المرشحين من
 69:             // الجداول الثلاثة (استعلامات indexed رخيصة)، ثم نفحص مرشحًا واحدًا
 70:             // بالأولوية (staff ثم supplier ثم customer) أو dummy hash عند غياب
 71:             // الجميع. الفحص الإضافي يحدث فقط في حالة البريد المشترك الشاذة.
 72:             $supplierUser = null; // Supplier accounts are historical; dealers use Customer accounts.
 73:             $customer = Customer::query()
 74:                 ->whereNotNull('email_verified_at')
 75:                 ->whereRaw('LOWER(email) = ?', [$email])
 76:                 ->first();
 77: 
 78:             // L4: رصد أي بريد مشترك بين جدولين — بما فيها العملاء.
 79:             $present = array_values(array_filter([$staff, $supplierUser, $customer]));
 80:             if (count($present) >= 2) {
 81:                 logger()->warning('auth.shared_email', ['identifier_key' => hash_hmac('sha256', $email, (string) config('app.key'))]);
 82:             }
 83: 
 84:             if ($present === []) {
 85:                 Hash::check($password, CustomerAuthService::dummyHash());
 86:                 logger()->info('unified.login', ['result' => 'wrong_password']);
 87: 
 88:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 89:             }
 90: 
 91:             $matched = null;
 92:             foreach ($present as $candidate) {
 93:                 if (! Hash::check($password, $candidate->password)) {
 94:                     continue;
 95:                 }
 96:                 if ($candidate instanceof User && (! $candidate->is_active || $candidate->is_system)) {
 97:                     logger()->info('staff.login', ['user_id' => $candidate->id, 'ip' => request()->ip(), 'result' => 'inactive']);
 98: 
 99:                     continue;
100:                 }
101:                 if ($candidate instanceof SupplierUser && (! $candidate->is_active || $candidate->supplier_id === null
102:                     || $candidate->supplier?->is_active !== true)) {
103:                     logger()->info('supplier.login', ['supplier_user_id' => $candidate->id, 'ip' => request()->ip(), 'result' => 'inactive']);
104: 
105:                     continue;
106:                 }
107:                 $matched = $candidate;
108:                 break;
109:             }
110: 
111:             if ($matched === null) {
112:                 if ($customer !== null) {
113:                     defer(fn () => CustomerAuditLog::record($customer, 'login_failed', null, [
114:                         'identifier_key' => hash_hmac('sha256', $email, (string) config('app.key')),
115:                     ]))->always();
116:                 } else {
117:                     logger()->info('unified.login', ['result' => 'wrong_password']);
118:                 }
119: 
120:                 foreach ([$staff, $supplierUser] as $account) {
121:                     if ($account !== null) {
122:                         logger()->info($account instanceof User ? 'staff.login' : 'supplier.login', [
123:                             'user_id' => $account->id, 'ip' => request()->ip(), 'result' => 'wrong_password',
124:                         ]);
125:                     }
126:                 }
127:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
128:             }
129: 
130:             if ($matched instanceof User) {
131:                 $this->rehashIfNeeded($matched, $password);
132: 
133:                 logger()->info('staff.login', ['user_id' => $matched->id, 'ip' => request()->ip(), 'result' => 'success']);
134: 
135:                 return $matched;
136:             }
137: 
138:             if ($matched instanceof SupplierUser) {
139:                 $this->rehashIfNeeded($matched, $password);
140: 
141:                 logger()->info('supplier.login', ['supplier_user_id' => $matched->id, 'ip' => request()->ip(), 'result' => 'success']);
142: 
143:                 return $matched;
144:             }
145: 
146:             /** @var Customer $matched */
147:             if ($matched->status === CustomerStatus::Suspended) {
148:                 CustomerAuditLog::record($matched, 'login_failed', null, ['reason' => 'suspended']);
149: 
150:                 throw new BusinessException(
151:                     'هذا الحساب موقوف.'.($matched->suspension_reason ? ' السبب: '.$matched->suspension_reason : ''),
152:                     ['suspension_reason' => $matched->suspension_reason],
153:                     403,
154:                 );
155:             }
156:             // L7: إعادة التجزئة بعد فحص الإيقاف.
157:             if (Hash::needsRehash($matched->password)) {
158:                 $matched->forceFill(['password' => $password])->save();
159:             }
160:             CustomerAuditLog::record($matched, 'login_succeeded', null);
161: 
162:             return $matched;
163:         }
164: 
165:         // يرمي BusinessException ‏401 أو 403 بنفسه
166:         return $this->customerAuth->login($login, $password);
167:     }
