169:     private function rehashIfNeeded(User|SupplierUser $model, string $password): void
170:     {
171:         if (Hash::needsRehash($model->password)) {
172:             $original = $model->password;
173:             $replacement = Hash::make($password);
174:             // A rehash must never overwrite an administrator's concurrent password reset.
175:             if ($model->newQuery()->whereKey($model->id)->where('password', $original)->update(['password' => $replacement]) !== 1) {
176:                 throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
177:             }
178:             // Keep the exact credential snapshot just verified; a later reset invalidates its handoff.
179:             $model->forceFill(['password' => $replacement])->syncOriginalAttribute('password');
180:         }
