234:   function changeTheme(targetDark, origin) {
235:     const isDark = targetDark === state.darkMode ? !state.darkMode : targetDark;
236:     cancelAnimationFrame(timers.current.wipe);
237:     const viewport = viewportRef.current;
238:     const underlay = underlayRef.current;
239:     if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
240:       viewport.style.clipPath = 'none';
241:       viewport.classList.remove('no-theme-transitions');
242:       underlay.classList.add('hidden');
243:       underlay.replaceChildren();
244:       window.dispatchEvent(new CustomEvent('vortix:theme-change', { detail: { darkMode: isDark } }));
245:       update(next => { next.darkMode = isDark; });
246:       return;
247:     }
248:     const rect = origin.getBoundingClientRect();
249:     const cx = Math.round(rect.left + rect.width / 2);
250:     const cy = Math.round(rect.top + rect.height / 2);
251:     const scrollY = window.scrollY || 0;
252:     const maxRadius = Math.ceil(Math.hypot(Math.max(cx, window.innerWidth - cx), Math.max(cy, window.innerHeight - cy))) + 30;
253:     const snapshot = viewport.cloneNode(true);
254:     const liveInputs = viewport.querySelectorAll('input');
255:     snapshot.querySelectorAll('input').forEach((input, index) => {
256:       input.value = liveInputs[index].value;
257:       input.checked = liveInputs[index].checked;
258:     });
259:     const liveHosts = viewport.querySelectorAll('[data-catalog-mock], [data-categories-mock], [data-inventory-mock], [data-admin-mock]');
260:     snapshot.querySelectorAll('[data-catalog-mock], [data-categories-mock], [data-inventory-mock], [data-admin-mock]').forEach((hostClone, index) => {
261:       const liveHost = liveHosts[index];
262:       if (liveHost?.shadowRoot) {
263:         const cloneRoot = hostClone.attachShadow({ mode: 'open' });
264:         cloneRoot.innerHTML = liveHost.shadowRoot.innerHTML;
265:       }
266:     });
267:     snapshot.removeAttribute('id');
268:     snapshot.style.clipPath = 'none';
269:     snapshot.style.width = viewport.offsetWidth + 'px';
270:     snapshot.style.transform = `translateY(-${scrollY}px)`;
271:     snapshot.querySelectorAll('[id]').forEach(element => element.removeAttribute('id'));
272:     underlay.replaceChildren(snapshot);
273:     underlay.classList.remove('hidden');
274:     try {
275:       localStorage.setItem('vortix_theme', isDark ? 'dark' : 'light');
276:     } catch {}
277:     window.dispatchEvent(new CustomEvent('vortix:theme-change', { detail: { darkMode: isDark } }));
278:     document.documentElement.setAttribute('data-theme', isDark ? 'dark' : 'light');
279:     flushSync(() => update(next => { next.darkMode = isDark; }));
280:     hostRef.current.setAttribute('data-theme', isDark ? 'dark' : 'light');
281:     viewport.classList.add('no-theme-transitions');
282:     const clipY = cy + scrollY;
283:     viewport.style.clipPath = `circle(0px at ${cx}px ${clipY}px)`;
284:     const started = performance.now();
285:     function step(now) {
286:       const progress = Math.min((now - started) / 660, 1);
287:       const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
288:       viewport.style.clipPath = `circle(${(eased * maxRadius).toFixed(1)}px at ${cx}px ${clipY}px)`;
289:       if (progress < 1) timers.current.wipe = requestAnimationFrame(step);
290:       else {
291:         viewport.style.clipPath = 'none';
292:         viewport.classList.remove('no-theme-transitions');
293:         underlay.classList.add('hidden');
294:         underlay.replaceChildren();
295:       }
296:     }
297:     timers.current.wipe = requestAnimationFrame(step);
298:   }
