  5: namespace App\Models;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Models\Concerns\SerializesAccountEmail;
 10: use Illuminate\Database\Eloquent\Attributes\Fillable;
 11: use Illuminate\Database\Eloquent\Attributes\Hidden;
 12: use Illuminate\Database\Eloquent\Factories\HasFactory;
 13: use Illuminate\Database\Eloquent\Relations\BelongsTo;
 14: use Illuminate\Database\Eloquent\Relations\HasMany;
 15: use Illuminate\Database\Eloquent\SoftDeletes;
 16: use Illuminate\Foundation\Auth\User as Authenticatable;
 17: use Illuminate\Notifications\Notifiable;
 18: use Laravel\Sanctum\HasApiTokens;
 19: 
 20: #[Fillable([
 21:     'name',
 22:     'email',
 23:     'phone',
 24:     'password',
 25:     'type',
 26:     'status',
 27:     'customer_group_id',
 28:     'company_name',
 29:     'tax_number',
 30:     'commercial_register',
 31:     'credit_limit',
 32:     'rejection_reason',
 33:     'suspension_reason',
 34:     'approved_at',
 35:     'approved_by',
 36:     'phone_verified_at',
 37: ])]
 38: #[Hidden(['password', 'remember_token'])]
 39: class Customer extends Authenticatable
 40: {
 41:     use HasApiTokens, HasFactory, Notifiable, SoftDeletes;
 42:     use SerializesAccountEmail;
 43: 
 44:     protected static function booted(): void
 45:     {
 46:         static::creating(function (Customer $customer): void {
 47:             if (! array_key_exists('status', $customer->getAttributes())) {
 48:                 $customer->status = in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
 49:                     ? CustomerStatus::Pending : CustomerStatus::Approved;
 50:             }
 51:         });
 52:     }
 53: 
 54:     public function customerGroup(): BelongsTo
 55:     {
 56:         return $this->belongsTo(CustomerGroup::class);
 57:     }
 58: 
 59:     public function getEmailForPasswordReset(): string
 60:     {
 61:         return 'customer:'.$this->getKey();
 62:     }
 63: 
 64:     public function setEmailAttribute(?string $email): void
 65:     {
 66:         $normalized = $email === null ? null : mb_strtolower(trim($email));
 67:         if (($this->attributes['email'] ?? null) !== $normalized) {
 68:             $this->attributes['email_verified_at'] = null;
 69:         }
 70:         $this->attributes['email'] = $normalized;
 71:     }
 72: 
 73:     public function setPhoneAttribute(string $phone): void
 74:     {
 75:         $this->attributes['phone'] = self::normalizePhone($phone);
 76:     }
 77: 
 78:     public static function normalizePhone(string $phone): string
 79:     {
 80:         $phone = strtr(trim($phone), array_combine(
 81:             preg_split('//u', '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', -1, PREG_SPLIT_NO_EMPTY),
 82:             str_split('01234567890123456789'),
 83:         ));
 84:         $phone = preg_replace('/[\s().-]+/u', '', $phone);
 85:         if (str_starts_with($phone, '+20')) {
 86:             return '0'.substr($phone, 3);
 87:         }
 88:         if (str_starts_with($phone, '0020')) {
 89:             return '0'.substr($phone, 4);
 90:         }
 91: 
 92:         return $phone;
 93:     }
 94: 
 95:     public function auditLogs(): HasMany
 96:     {
 97:         return $this->hasMany(CustomerAuditLog::class);
 98:     }
 99: 
100:     public function approver(): BelongsTo
101:     {
102:         return $this->belongsTo(User::class, 'approved_by');
103:     }
104: 
105:     public function documents(): HasMany
106:     {
107:         return $this->hasMany(CustomerDocument::class);
108:     }
109: 
110:     public function addresses(): HasMany
111:     {
112:         return $this->hasMany(CustomerAddress::class);
113:     }
114: 
115:     public function returnRequests(): HasMany
116:     {
117:         return $this->hasMany(ReturnRequest::class);
118:     }
119: 
120:     protected function casts(): array
121:     {
122:         return [
123:             'password' => 'hashed',
124:             'type' => CustomerType::class,
125:             'status' => CustomerStatus::class,
126:             'credit_limit' => 'decimal:2',
127:             'wallet_balance' => 'decimal:2',
128:             'approved_at' => 'datetime',
129:             'phone_verified_at' => 'datetime',
130:             'email_verified_at' => 'datetime',
131:         ];
132:     }
