 65:     private const SEQUENCE_TYPES = [
 66:         'order' => 'order_next_number',
 67:         'purchase_order' => 'purchase_order_next_number',
 68:         'quotation' => 'quotation_next_number',
 69:         'transfer' => 'transfer_next_number',
 70:         'stocktake' => 'stocktake_next_number',
