 78:     /**
 79:      * Return all settings grouped by their group name, with values cast to their declared types.
 80:      * Numbering counters are read fresh because they change for every generated document number.
 81:      *
 82:      * @return array<string, array<string, mixed>>
 83:      */
 84:     public function getAllGrouped(): array
 85:     {
 86:         $grouped = $this->staticSettings();
 87: 
 88:         $counters = Setting::query()
 89:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 90:             ->orderBy('key')
 91:             ->get()
 92:             ->mapWithKeys(fn (Setting $setting): array => [
 93:                 $setting->key => $this->castValue($setting->value, $setting->type),
 94:             ])
 95:             ->all();
 96: 
 97:         if (isset($counters['movement_next_number'])) {
 98:             $counters['movement_next_number'] = $this->nextMovementNumber();
 99:         }
100:         foreach (self::SEQUENCE_TYPES as $type => $key) {
101:             if (isset($counters[$key])) {
102:                 $counters[$key] = $this->nextDocumentNumber($type);
103:             }
104:         }
105: 
106:         if ($counters !== []) {
107:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
108:             ksort($grouped['numbering']);
109:         }
110: 
111:         return $grouped;
112:     }
113: 
114:     private function staticSettings(): array
115:     {
116:         $read = function (): array {
117:             return Setting::query()
118:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
119:                 ->orderBy('group')
120:                 ->orderBy('key')
121:                 ->get()
122:                 ->groupBy('group')
123:                 ->map(fn ($settings): array => $settings
124:                     ->mapWithKeys(fn (Setting $setting): array => [
125:                         $setting->key => $this->castValue($setting->value, $setting->type),
126:                     ])
127:                     ->all())
128:                 ->all();
129:         };
130: 
131:         $inTransaction = DB::transactionLevel() > 0;
132:         if ($inTransaction && $this->transactionSnapshot !== null) {
133:             return $this->transactionSnapshot;
134:         }
135:         if ($inTransaction && $this->uncommittedSettings) {
136:             return $this->transactionSnapshot = $read();
137:         }
138:         $version = Cache::get(self::CACHE_VERSION_KEY);
139:         if (! is_string($version)) {
140:             Cache::add(self::CACHE_VERSION_KEY, (string) Str::uuid());
141:             $version = Cache::get(self::CACHE_VERSION_KEY);
142:         }
143: 
144:         $key = self::CACHE_KEY.':'.$version;
145:         if ($inTransaction) {
146:             // Reuse committed cache values, but never publish an uncommitted cache miss.
147:             return $this->transactionSnapshot = Cache::get($key) ?? $read();
148:         }
149: 
150:         return Cache::remember($key, self::CACHE_TTL_SECONDS, $read);
151:     }
152: 
153:     public function get(string $key, mixed $default = null): mixed
154:     {
155:         if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
156:             if ($key === 'movement_next_number') {
157:                 return $this->nextMovementNumber();
158:             }
159:             $type = array_search($key, self::SEQUENCE_TYPES, true);
160:             if (is_string($type)) {
161:                 return $this->nextDocumentNumber($type);
162:             }
163:             $setting = Setting::query()->where('key', $key)->first();
164: 
165:             return $setting ? $this->castValue($setting->value, $setting->type) : $default;
166:         }
167:         foreach ($this->staticSettings() as $settings) {
168:             if (array_key_exists($key, $settings)) {
169:                 return $settings[$key];
170:             }
171:         }
172: 
173:         return $default;
174:     }
175: 
176:     /**
177:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
178:      *
179:      * @param  array<string, mixed>  $settings
180:      *
181:      * @throws JsonException
182:      */
183:     public function updateBatch(array $settings, ?array $expected = null): void
184:     {
185:         $this->warnings = [];
186:         DB::transaction(function () use ($settings, $expected): void {
187:             $this->uncommittedSettings = true;
188:             $this->resetReadSnapshot();
189:             $movementSequenceTarget = null;
190:             /** @var array<string, int> $documentSequenceTargets */
191:             $documentSequenceTargets = [];
192:             $lockedSettings = Setting::query()
193:                 ->whereIn('key', array_keys($settings))
194:                 ->orderBy('key')
195:                 ->lockForUpdate()
196:                 ->get()
197:                 ->keyBy('key');
198: 
199:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
200: 
201:             if ($missingKeys !== []) {
202:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
203:             }
204: 
205:             $before = [];
206:             $after = [];
207:             foreach ($settings as $key => $value) {
208:                 /** @var Setting $setting */
209:                 $setting = $lockedSettings->get($key);
210:                 $current = $this->castValue($setting->value, $setting->type);
211:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
212:                     $current = $this->get($key);
213:                 }
214:                 if ($expected !== null && (! array_key_exists($key, $expected)
215:                     || $this->comparisonValue($current, $setting->type) !== $this->comparisonValue($expected[$key], $setting->type))) {
216:                     abort(409, 'تم تغيير إعداد أو عداد منذ فتح الصفحة؛ أعد تحميل الإعدادات قبل الحفظ.');
217:                 }
218:                 $before[$key] = $current;
219: 
220:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
221:                     $requested = $this->counterValue($value);
222:                     if ($requested > 999999999) {
223:                         throw ValidationException::withMessages([$key => 'الحد الأقصى للعداد هو 999999999.']);
224:                     }
225:                     $value = max($this->counterValue($setting->value), $requested);
226:                     if ($key === 'movement_next_number') {
227:                         $value = max($value, $this->nextMovementNumber());
228:                         $movementSequenceTarget = $value;
229:                     }
230:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
231:                     if (is_string($sequenceType)) {
232:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
233:                         $documentSequenceTargets[$sequenceType] = $value;
234:                     }
235:                     if ($requested < $value) {
236:                         throw ValidationException::withMessages([$key => 'لا يمكن خفض عداد الترقيم عن قيمته الحالية.']);
237:                     }
238:                 }
239: 
240:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
241:                     ? ''
242:                     : $this->serializeValue($value, $setting->type);
243:                 $setting->save();
244:                 $after[$key] = $this->castValue($setting->value, $setting->type);
245:             }
246: 
247:             StaffAdministration::audit(request()->user('staff'), 'settings.updated', 'settings', null, array_keys($settings),
248:                 ['settings' => $this->auditableSettings($before)], ['settings' => $this->auditableSettings($after)]);
249:             DB::afterCommit(fn () => $this->clearCache());
250: 
251:             if ($movementSequenceTarget !== null) {
252:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
253:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
254:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
255:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
256:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
257:                     $this->synchronizeSequence(fn () => DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]));
258:                 });
259:             }
260:             if ($documentSequenceTargets !== []) {
261:                 DB::afterCommit(function () use ($documentSequenceTargets): void {
262:                     foreach ($documentSequenceTargets as $type => $minimum) {
263:                         $this->synchronizeSequence(fn () => DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]));
264:                     }
265:                 });
266:             }
267:         }, attempts: 3);
268:     }
269: 
270:     /**
271:      * Atomically return and increment the next document number for the requested type.
272:      *
273:      * @throws JsonException
274:      */
275:     public function generateNextNumber(string $type): string
276:     {
277:         if ($type === 'movement') {
278:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
279:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
280: 
281:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
282:         }
283:         if (isset(self::SEQUENCE_TYPES[$type])) {
284:             $definitions = $this->numberingDefinitions();
285:             $definition = $definitions[$type];
286:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
287:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
288: 
289:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
290:         }
291:         $definitions = $this->numberingDefinitions();
292: 
293:         if (! isset($definitions[$type])) {
294:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
295:         }
296: 
297:         $definition = $definitions[$type];
298:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
299: 
300:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
301:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
302:             $nextSetting = Setting::query()
303:                 ->where('key', $definition['next'])
304:                 ->lockForUpdate()
305:                 ->first();
306: 
307:             if ($nextSetting === null) {
308:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
309:             }
310: 
311:             $nextValue = $this->counterValue($nextSetting->value);
312: 
313:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
314:             $nextSetting->value = (string) ($nextValue + 1);
315:             $nextSetting->save();
316: 
317:             return $formatted;
318:         }, attempts: 3);
319:     }
320: 
321:     /**
322:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
323:      *
324:      * @return array{0: string, 1: int}
325:      */
326:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
327:     {
328:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
329:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
330: 
331:             foreach ([$prefixKey, $paddingKey] as $key) {
332:                 if (! $settings->has($key)) {
333:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
334:                 }
335:             }
336: 
337:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
338:         })();
339:     }
340: 
341:     private function synchronizeSequence(callable $sync): void
342:     {
343:         try {
344:             $sync();
345:         } catch (\Throwable $exception) {
346:             report($exception);
347:             $this->warnings[] = 'تم حفظ الإعدادات، لكن تعذرت مزامنة أحد عدادات الترقيم؛ أعد حفظ العداد للمحاولة مرة أخرى.';
348:         }
349:     }
