351:     public function clearCache(): void
352:     {
353:         Cache::forever(self::CACHE_VERSION_KEY, (string) Str::uuid());
354:         Cache::forget(self::CACHE_KEY); // Retire the cache key used before versioning.
355:         $this->numberingConfig = [];
356:         $this->resetReadSnapshot();
357:     }
