364:     private function auditableSettings(array $settings): array
365:     {
366:         // Only the public administrative settings schema is safe to audit as values.
367:         $allowed = array_keys((new UpdateSettingsRequest)->rules());
368: 
369:         return array_intersect_key($settings, array_flip($allowed));
370:     }
