396:     private function nextMovementNumber(): int
397:     {
398:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
399: 
400:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
401:     }
402: 
403:     private function nextDocumentNumber(string $type): int
404:     {
405:         if (! isset(self::SEQUENCE_TYPES[$type])) {
406:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
407:         }
408:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
409: 
410:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
411:     }
412: 
413:     private function counterValue(mixed $value): int
414:     {
415:         $number = (is_int($value) || is_string($value))
416:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
417:             : false;
418:         if ($number === false) {
419:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
420:         }
421: 
422:         return $number;
423:     }
424: 
425:     private function castValue(?string $value, string $type): mixed
426:     {
427:         if ($value === null) {
428:             return null;
429:         }
430: 
431:         return match ($type) {
432:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
433:             'integer' => (int) $value,
434:             'float' => (float) $value,
435:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
436:             default => $value,
437:         };
438:     }
439: 
440:     /** @throws JsonException */
441:     private function serializeValue(mixed $value, string $type): ?string
442:     {
443:         if ($value === null) {
444:             return null;
445:         }
446: 
447:         if ($type === 'json') {
448:             return json_encode($value, JSON_THROW_ON_ERROR);
449:         }
450: 
451:         if ($type === 'boolean') {
452:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
453:         }
454: 
455:         return (string) $value;
456:     }
