18: export function App() {
19:   if (window.location.pathname === '/auth/session') return <SessionProbePage />;
20:   if (window.location.pathname === '/auth/callback') return <AuthCallbackPage />;
21:   if (window.location.pathname === '/login') return <LoginPage />;
22:   return <ProtectedRoute><AuthenticatedApp /></ProtectedRoute>;
23: }
