25: function AuthenticatedApp() {
26:   const user = useAuthStore((state) => state.user);
27:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
28:   const readRoute = () => window.location.hash.replace(/^#/, '').split('?')[0]
29:     || window.location.pathname;
30:   const [route, setRoute] = useState(readRoute);
31:   const can = useCallback((permission: string) =>
32:     hasPermission(user?.permissions, permission), [user]);
33:   const cashierOnly = user?.roles.length === 1 && user.roles[0] === 'cashier';
34:   useEffect(() => {
35:     // Stocktake navigation guards may synchronously restore the accepted hash.
36:     const changed = () => queueMicrotask(() => setRoute(readRoute()));
37:     window.addEventListener('hashchange', changed);
38:     window.addEventListener('popstate', changed);
39:     return () => {
40:       window.removeEventListener('hashchange', changed);
41:       window.removeEventListener('popstate', changed);
42:     };
43:   }, []);
44:   useEffect(() => {
45:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) window.location.replace('/dashboard');
46:     else if (!['/', '/dashboard', '/categories', '/dealers', '/production', '/pos', '/users', '/roles', '/settings'].includes(route) && !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route) && !/^\/inventory(?:\/[a-z-]+)?$/.test(route)) window.location.replace('/dashboard');
47:   }, [cashierOnly, route]);
48:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
49:   if (route === '/pos') return <PosPage />;
50:   const categoriesActive = route === '/categories';
51:   const inventoryActive = route === '/inventory' || route.startsWith('/inventory/');
52:   const adminActive = route === '/users' ? 'users' : route === '/roles' ? 'roles' : route === '/settings' ? 'settings' : null;
53:   const catalogActive = inventoryActive ? 'inventory' : route.startsWith('/products') ? 'products' : route === '/dealers' ? 'dealers' : route === '/production' ? 'production' : adminActive;
54:   return <FinancialDashboard
55:     onLogout={logoutRemote}
56:     catalogActive={catalogActive}
57:     catalogPage={inventoryActive ? (can('inventory.view') ? <Suspense fallback={<div dir="rtl" className="p-6">جارٍ تحميل المخزون…</div>}><InventoryPage can={can}/></Suspense> : <div dir="rtl" className="p-6">ليس لديك صلاحية عرض المخزون.</div>) : adminActive ? <AdminMockPage key={adminActive} page={adminActive} can={can} /> : catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />}
58:     catalogNav={!cashierOnly ? [
59:       ...(can('inventory.view') ? [{ id: 'inventory', label: 'المخزون', onOpen: () => { window.location.hash = '/inventory/stock'; } }] : []),
60:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
61:       ...(can('customers.view') ? [{ id: 'dealers', label: 'التجار والموزعون', onOpen: () => { window.location.hash = '/dealers'; } }] : []),
62:       ...(can('inventory.view') ? [{ id: 'production', label: 'استلام الإنتاج', onOpen: () => { window.location.hash = '/production'; } }] : []),
63:       ...((can('users.view') || can('users.manage')) ? [{ id: 'users', label: 'المستخدمون', onOpen: () => { window.location.hash = '/users'; } }] : []),
64:       ...((can('roles.view') || can('roles.manage')) ? [{ id: 'roles', label: 'الأدوار', onOpen: () => { window.location.hash = '/roles'; } }] : []),
65:       ...((can('settings.view') || can('settings.manage')) ? [{ id: 'settings', label: 'الإعدادات', onOpen: () => { window.location.hash = '/settings'; } }] : []),
66:     ] : []}
67:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
68:     categoriesActive={categoriesActive}
69:     categoriesPage={<CategoriesMockPage can={can} embedded />}
70:     onOpenCategories={!cashierOnly && can('categories.view')
71:       ? () => { window.location.hash = '/categories'; }
72:       : undefined}
73:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
74:   />;
75: }
