312:             $order->refresh();
313: 
314:             // تسجيل استخدام الكوبون فعليًا (خصم البضاعة أو الشحن المُعفى).
315:             // كوبون شحن مجاني وشحن الطلب صفر أصلًا لا يستهلك حدًا بلا فائدة (L4)
316:             if ($coupon !== null
317:                 && ! ($coupon->type === 'free_shipping' && $waivedShipping <= 0)) {
318:                 $this->couponService->recordUsage(
319:                     $coupon,
320:                     $order,
321:                     $customer,
322:                     $coupon->type === 'free_shipping' ? $waivedShipping : $couponDiscount,
323:                 );
324:             }
325: 
326:             if (($data['payment_method'] ?? 'cod') === 'wallet') {
327:                 if ($customer === null || $customer->fresh()->status !== CustomerStatus::Approved) {
328:                     throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
329:                 }
330:                 app(WalletService::class)->record($customer->id, -$grandTotal, 'checkout_payment', 'order', $order->id);
331:                 $order->update(['payment_status' => 'paid']);
332:             }
333: 
334:             // أول سجل حالة: إنشاء الطلب
335:             $order->statusHistories()->create([
336:                 'from_status' => null,
337:                 'to_status' => OrderStatus::Pending,
338:                 'changed_by_type' => $customer?->getMorphClass(),
339:                 'changed_by_id' => $customer?->getKey(),
340:                 'notes' => 'تم إنشاء الطلب من السلة',
341:             ]);
342: 
343:             // إفراغ السلة من البنود التي تحولت لطلب فقط (F-23): بند أُضيف
344:             // والتزم أثناء المعاملة لا يجب أن يمسحه مسحٌ كامل للسلة
345:             $orderedItemIds = array_values(array_unique(array_map(
346:                 fn (array $line): int => (int) $line['item_id'],
347:                 $lines,
348:             )));
349:             if ($orderedItemIds !== []) {
350:                 $cart->items()->whereIn('id', $orderedItemIds)->delete();
351:             }
352:             $cart->update(['coupon_id' => null]);
353: 
354:             $created = $order->fresh(['items', 'statusHistories']);
355:             OrderCreated::dispatch($created);
356: 
357:             return $created;
358:         });
359:     }
360: 
361:     /**
362:      * بوابة الحالة الوحيدة. $expectedFrom (F-11): حالات مصدر يفترضها
363:      * المستدعي على نسخته غير المقفولة — تُفحص بعد إعادة القراءة بالقفل،
364:      * فسباق (عميل يلغي × أدمن يجهّز) لا يمر من فحص قديم.
365:      * $returnEffects (المرحلة 9): عند false ينتقل الطلب إلى Returned بلا
366:      * إعادة مخزون وبلا علم استرداد — مسار RMA سوّى المخزون عند الاستلام
367:      * الفعلي والمال عند رد المبلغ، فتكرار الأثر هنا ازدواج.
368:      *
369:      * @param  array<int, OrderStatus>|null  $expectedFrom
370:      */
371:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true): Order
372:     {
373:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
374: 
375:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects): Order {
376:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
377:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
378:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
379:             $from = $order->status;
380: 
381:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
382:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
383:             }
384: 
385:             if ($from === $to) {
386:                 return $order;
387:             }
388: 
389:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
390:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
391:             }
392: 
393:             $actorId = $this->inventoryActorId($actor);
394: 
395:             if ($to === OrderStatus::Returned && $returnEffects && $order->channel === 'pos') {
396:                 throw new BusinessException('استخدم مرتجع POS لتسوية المخزون والنقدية معًا.');
397:             }
398: 
399:             if ($to === OrderStatus::Returned && $returnEffects
400:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
401:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
402:                 ])->exists()) {
403:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
404:             }
405: 
406:             // آثار المخزون بحسب الانتقال
407:             $extraNote = null;
408:             if ($to === OrderStatus::Shipped) {
409:                 $this->shipOrder($order, $actorId);
410:             } elseif ($to === OrderStatus::Cancelled
411:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
412:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
413:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
414:             } elseif ($to === OrderStatus::Returned
415:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
416:                 && $returnEffects) {
417:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13) —
418:                 // تُتخطى في مسار RMA لأن الاستلام الفعلي سوّاها بالفعل (مرحلة 9)
419:                 if (! $this->returnSalesToStock($order, $actorId)) {
420:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
421:                 }
422:             }
423: 
424:             if ($to === OrderStatus::Cancelled) {
425:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
426:                 $this->reverseCouponUsage($order);
427:                 if ($order->payment_status === 'paid') {
428:                     $order->update(['requires_refund' => true]);
429:                 }
430:             }
431: 
432:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14) —
433:             // في مسار RMA الاسترداد اكتمل داخل طلب المرتجع نفسه فلا علم هنا
434:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
435:                 $order->update(['requires_refund' => true]);
436:             }
437: 
438:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
439:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
440:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
441:                     ->where('type', 'checkout_payment')->first();
442:                 if ($payment !== null) {
443:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
444:                         'order_reversal', 'order', $order->id, $actorId);
445:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
446:                 }
447:             }
448: 
449:             $order->update(['status' => $to]);
450: 
451:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
452:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
453:             if ($to === OrderStatus::Delivered
454:                 && $order->payment_method === 'cod'
455:                 && $order->payment_status !== 'paid') {
456:                 $order->update(['payment_status' => 'paid']);
457:             }
458: 
459:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
460:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
461:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
462: 
463:             $order->statusHistories()->create([
464:                 'from_status' => $from,
465:                 'to_status' => $to,
466:                 'changed_by_type' => $actor?->getMorphClass(),
467:                 'changed_by_id' => $actor?->getKey(),
468:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
469:             ]);
470: 
471:             // التوزيع ناقص إن غاب فرع الطلب أو بقي بند بلا فرع: الاعتماد على
472:             // allocated_branch_id وحده يفشل عندما تُوزَّع البنود في فروع
473:             // مختلفة فيبقى حقل الطلب فارغًا (F1)
474:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
475:                 $this->allocationService->allocate($order, performedBy: $actorId);
476:             }
477: 
478:             return $order->fresh(['items', 'statusHistories']);
479:         });
480:     }
481: 
482:     /**
483:      * كفاية التوزيع: يكفي أن يكون لفرع الطلب قيمة أو أن يكون كل بند موزّعًا
484:      * فعليًا في فرع ما (F1) — التوزيع الجزئي (بند بلا فرع) يُعيد الاستدعاء.
485:      */
486:     private function isAllocated(Order $order): bool
487:     {
488:         if ($order->allocated_branch_id !== null) {
489:             return true;
490:         }
491: 
492:         $distribution = $order->items()
493:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
494:             ->first();
495: 
496:         if ($distribution === null || (int) $distribution->total === 0) {
497:             return false;
498:         }
499: 
500:         return (int) $distribution->total === (int) $distribution->allocated;
501:     }
502: 
503:     /** عميل جملة/توزيع معتمد — يُستثنى من سقوف التجزئة (H2). */
504:     private function isWholesaleApproved(?Customer $customer): bool
505:     {
506:         return $customer !== null
507:             && $customer->status === CustomerStatus::Approved
508:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
509:     }
510: 
511:     /**
512:      * توزيع مبلغ على أوزان بطريقة «أكبر باقٍ» بعدد صحيح من القروش (L5):
513:      * مجموع الحصص يساوي المبلغ بالضبط، ولا حصة سالبة بسبب التقريب.
514:      *
515:      * @param  array<int, float>  $weights
516:      * @return array<int, float>
517:      */
518:     private function distributeLargestRemainder(float $total, array $weights): array
519:     {
520:         $count = count($weights);
521:         if ($count === 0) {
522:             return [];
523:         }
524:         $totalCents = (int) round($total * 100);
525:         $weightSum = array_sum($weights);
526:         if ($totalCents <= 0 || $weightSum <= 0) {
527:             return array_fill(0, $count, 0.0);
528:         }
529: 
530:         $floorCents = [];
531:         $remainders = [];
532:         $assigned = 0;
533:         foreach ($weights as $i => $weight) {
534:             $exact = $totalCents * ((float) $weight / $weightSum);
535:             $floor = (int) floor($exact);
536:             $floorCents[$i] = $floor;
537:             $remainders[$i] = $exact - $floor;
538:             $assigned += $floor;
539:         }
540: 
541:         $left = $totalCents - $assigned;
542:         arsort($remainders);
543:         foreach (array_keys($remainders) as $i) {
544:             if ($left <= 0) {
545:                 break;
546:             }
547:             $floorCents[$i]++;
548:             $left--;
549:         }
550: 
551:         ksort($floorCents);
552: 
553:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
554:     }
555: 
556:     /**
557:      * الشحن: الحجز القائم الصافي لكل (متغير، فرع، موقع) — فك الحجز من reserved
558:      * وخصم فعلي sale من on_hand على نفس صف الرصيد (C3).
559:      * التجميع من الدفتر نفسه يجعل تكرار الشحن/الفك آمنًا: لا يُفك أي حجز مرتين.
560:      */
561:     private function shipOrder(Order $order, ?int $actorId): void
562:     {
563:         $net = $this->netReservations($order);
564:         if ($net->isEmpty()) {
565:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
566:         }
567: 
568:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
569:             'product_variant_id' => $row['product_variant_id'],
570:             'branch_id' => $row['branch_id'],
571:             'location_id' => $row['location_id'],
572:         ])->all());
573: 
574:         $costs = ProductVariant::withTrashed()->whereIn('id', $net->pluck('product_variant_id'))->pluck('cost_price', 'id');
575:         foreach ($net as $row) {
576:             $base = [
577:                 'product_variant_id' => $row['product_variant_id'],
578:                 'branch_id' => $row['branch_id'],
579:                 'location_id' => $row['location_id'],
580:                 'reference_type' => Order::class,
581:                 'reference_id' => $order->id,
582:                 'created_by' => $actorId,
583:             ];
584:             $level = $levels->get($this->inventoryService->levelKey($row));
585:             $this->inventoryService->recordMovement([...$base,
586:                 'type' => StockMovementType::ReleaseReserve,
587:                 'affected_bucket' => StockBucket::Reserved,
588:                 'quantity' => -1 * (float) $row['net_qty'],
589:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
590:             ], $level);
591:             $this->inventoryService->recordMovement([...$base,
592:                 'type' => StockMovementType::Sale,
593:                 'unit_cost' => $costs[$row['product_variant_id']] ?? null,
594:                 'affected_bucket' => StockBucket::OnHand,
595:                 'quantity' => -1 * (float) $row['net_qty'],
596:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
597:             ], $level);
598:         }
599: 
600:         foreach ($order->items as $item) {
601:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
602:         }
603:     }
604: 
605:     /** إلغاء طلب مُحجوز: فك الحجز القائم الصافي فقط فتعود الكميات متاحة للبيع (C3). */
606:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
607:     {
608:         $net = $this->netReservations($order);
609:         if ($net->isEmpty()) {
610:             return;
611:         }
612: 
613:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
614:             'product_variant_id' => $row['product_variant_id'],
615:             'branch_id' => $row['branch_id'],
616:             'location_id' => $row['location_id'],
617:         ])->all());
618: 
619:         foreach ($net as $row) {
620:             $this->inventoryService->recordMovement([
621:                 'product_variant_id' => $row['product_variant_id'],
622:                 'branch_id' => $row['branch_id'],
623:                 'location_id' => $row['location_id'],
624:                 'type' => StockMovementType::ReleaseReserve,
625:                 'affected_bucket' => StockBucket::Reserved,
626:                 'quantity' => -1 * (float) $row['net_qty'],
627:                 'reference_type' => Order::class,
628:                 'reference_id' => $order->id,
629:                 'created_by' => $actorId,
630:                 'notes' => "{$reason} {$order->order_number}",
631:             ], $levels->get($this->inventoryService->levelKey($row)));
632:         }
633:     }
634: 
635:     /**
636:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: صافي البيع القائم
637:      * (المبيع ناقص sale_return المرتبط بالطلب) لكل مفتاح (C3/H7).
638:      * ترجع false إذا لم يوجد صافي بيع (يحتاج استلامًا يدويًا).
639:      */
640:     private function returnSalesToStock(Order $order, ?int $actorId): bool
641:     {
642:         $net = StockMovement::query()
643:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
644:             ->where('reference_id', $order->id)
645:             ->whereIn('type', [StockMovementType::Sale->value, StockMovementType::SaleReturn->value])
646:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
647:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty, MAX(unit_cost) FILTER (WHERE type = \'sale\') AS sale_unit_cost')
648:             ->get()
649:             // Sale سالبة وSaleReturn موجبة: الصافي السالب هو البيع القائم.
650:             ->map(fn ($row): array => [
651:                 'product_variant_id' => (int) $row->product_variant_id,
652:                 'branch_id' => (int) $row->branch_id,
653:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
654:                 'net_qty' => (float) $row->net_qty,
655:                 'sale_unit_cost' => $row->sale_unit_cost,
656:             ])
657:             ->filter(fn (array $row): bool => $row['net_qty'] < -1e-9)
658:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
659:             ->values();
660: 
661:         if ($net->isEmpty()) {
662:             return false;
663:         }
664: 
665:         $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
666:             'product_variant_id' => $row['product_variant_id'],
667:             'branch_id' => $row['branch_id'],
668:             'location_id' => $row['location_id'],
669:         ])->all());
670: 
671:         foreach ($net as $row) {
672:             $this->inventoryService->recordMovement([
673:                 'product_variant_id' => $row['product_variant_id'],
674:                 'branch_id' => $row['branch_id'],
675:                 'location_id' => $row['location_id'],
676:                 'type' => StockMovementType::SaleReturn,
677:                 'affected_bucket' => StockBucket::OnHand,
678:                 'quantity' => -1 * (float) $row['net_qty'],
679:                 'unit_cost' => $row['sale_unit_cost'],
680:                 'reference_type' => Order::class,
681:                 'reference_id' => $order->id,
682:                 'created_by' => $actorId,
683:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
684:             ], $levels->get($this->inventoryService->levelKey($row)));
685:         }
686: 
687:         foreach ($order->items as $item) {
688:             if ($item->variant?->product_id) {
689:                 Product::query()->whereKey($item->variant->product_id)
690:                     ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
691:             }
692:         }
693: 
694:         return true;
695:     }
696: 
697:     /**
698:      * الحجز القائم الصافي لكل (متغير، فرع، موقع): مجموع Reserve ناقص ما فُك
699:      * بـ ReleaseReserve لنفس الطلب (C3). الصفوف تُقفل مرتبة عبر lockLevels
700:      * قبل التنفيذ في المستدعي.
701:      *
702:      * @return Collection<int, array{product_variant_id: int, branch_id: int, location_id: int|null, net_qty: float}>
703:      */
704:     private function netReservations(Order $order): Collection
705:     {
706:         return StockMovement::query()
707:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
708:             ->where('reference_id', $order->id)
709:             ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
710:             ->groupBy('product_variant_id', 'branch_id', 'location_id')
711:             ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
712:             ->get()
713:             ->map(fn ($row): array => [
714:                 'product_variant_id' => (int) $row->product_variant_id,
715:                 'branch_id' => (int) $row->branch_id,
716:                 'location_id' => $row->location_id === null ? null : (int) $row->location_id,
717:                 'net_qty' => (float) $row->net_qty,
718:             ])
719:             ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
720:             ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
721:             ->values();
722:     }
723: 
724:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
725:     private function reverseCouponUsage(Order $order): void
726:     {
727:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
728:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
729:             $usage->delete();
730:         }
731:     }
732: 
733:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
734:     private function reserveMovements(Order $order): Collection
735:     {
736:         return StockMovement::query()
737:             ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
738:             ->where('reference_id', $order->id)
739:             ->where('type', StockMovementType::Reserve)
740:             ->orderBy('id')
741:             ->get();
742:     }
743: 
744:     // التخزين على مستوى الـ instance لا static (F-27): في Octane/العمال
