765:                 ->value('id');
766:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
767:         }
768:         if ($this->systemActorId !== null) {
769:             return $this->systemActorId;
770:         }
771: 
772:         throw new \LogicException('The System audit identity is missing; run the system-user migration before processing automated order effects.');
773:     }
